{
  "name": "battle-world-elite-survival",
  "version": "1.0.0",
  "private": true,
  "description": "BATTLE WORLD: ELITE SURVIVAL — an original 3D mobile battle royale built with Three.js.",
  "type": "module",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3000",
    "build": "vite build --base ./",
    "preview": "vite preview --host 0.0.0.0 --port 3000",
    "test": "node --test tests/*.test.mjs",
    "server": "node server/index.js",
    "android:add": "npx cap add android",
    "android:sync": "npm run build && npx cap sync android",
    "android:apk": "npm run android:sync && cd android && ./gradlew assembleDebug"
  },
  "dependencies": {
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^7.1.7"
  }
}

import { defineConfig } from 'vite'

export default defineConfig({
  base: './',
  build: {
    target: 'es2020',
    assetsInlineLimit: 0,
    chunkSizeWarningLimit: 2000,
  },
  server: {
    host: '0.0.0.0',
    port: 3000,
  },
})

/* ═══════════════════════════════════════════════════════════════
   BATTLE WORLD: ELITE SURVIVAL — original UI system
   ═══════════════════════════════════════════════════════════════ */
@font-face { font-family: 'Rajdhani'; font-style: normal; font-weight: 400; font-display: swap; src: url('/fonts/rajdhani-400.woff2') format('woff2'); }
@font-face { font-family: 'Rajdhani'; font-style: normal; font-weight: 600; font-display: swap; src: url('/fonts/rajdhani-600.woff2') format('woff2'); }
@font-face { font-family: 'Rajdhani'; font-style: normal; font-weight: 700; font-display: swap; src: url('/fonts/rajdhani-700.woff2') format('woff2'); }
@font-face { font-family: 'Teko'; font-style: normal; font-weight: 600; font-display: swap; src: url('/fonts/teko-600.woff2') format('woff2'); }

:root {
  --bg: #050a10;
  --bg2: #07131e;
  --ink: #eaf6ff;
  --muted: #7e9bb0;
  --dim: #52697a;
  --orange: #ff7a1a;
  --orange2: #ffb347;
  --amber: #ffc857;
  --cyan: #63dcff;
  --green: #54e6a5;
  --red: #ff4b4b;
  --violet: #b78bff;
  --glass: rgba(7, 17, 27, .76);
  --glass2: rgba(12, 27, 40, .62);
  --line: rgba(134, 198, 235, .18);
  --line2: rgba(134, 198, 235, .34);
  --shadow: 0 22px 60px rgba(0, 0, 0, .5);
  --font: 'Rajdhani', 'Segoe UI', system-ui, sans-serif;
  --display: 'Teko', 'Rajdhani', 'Segoe UI', sans-serif;
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; background: var(--bg); color: var(--ink); font-family: var(--font); }
body { user-select: none; -webkit-user-select: none; touch-action: none; }
button, input, select { font-family: inherit; color: inherit; }
button { cursor: pointer; border: 0; background: none; }
button:focus-visible { outline: 2px solid var(--cyan); outline-offset: 3px; }
svg { display: block; }
.hidden { display: none !important; }
#app { position: fixed; inset: 0; overflow: hidden; }
#game-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; touch-action: none; }
#screen-vignette { position: absolute; inset: 0; pointer-events: none; z-index: 1;
  background: radial-gradient(ellipse at 50% 45%, transparent 48%, rgba(0, 4, 8, .44) 100%);
  mix-blend-mode: multiply; }

kbd { display: inline-block; min-width: 20px; padding: 1px 6px; border: 1px solid var(--line2); border-radius: 3px; background: rgba(255,255,255,.05); color: var(--ink); font: 600 11px/1.5 var(--font); text-align: center; }
.dot { display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px currentColor; }
.dot.amber { background: var(--amber); }
.dot.cyan { background: var(--cyan); }

/* ══════════════════ LOADING ══════════════════ */
.screen { position: absolute; inset: 0; z-index: 20; }
.loading-screen { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px;
  background: radial-gradient(circle at 50% 42%, rgba(22, 49, 70, .55), transparent 55%), linear-gradient(180deg, #04080d, #07131c 60%, #03070b);
  z-index: 80; transition: opacity .55s ease, visibility .55s; }
.loading-screen::before { content: ''; position: absolute; inset: 0; opacity: .35;
  background-image: linear-gradient(rgba(99,220,255,.06) 1px, transparent 1px), linear-gradient(90deg, rgba(99,220,255,.06) 1px, transparent 1px);
  background-size: 56px 56px; mask-image: radial-gradient(circle at center, #000 20%, transparent 72%); }
.loading-screen::after { content: ''; position: absolute; width: 780px; height: 780px; border: 1px solid rgba(99,220,255,.12); border-radius: 50%; animation: spin 26s linear infinite; }
.load-emblem { width: 96px; height: 96px; filter: drop-shadow(0 0 26px rgba(255, 122, 26, .45)); animation: emblemPulse 3.2s ease-in-out infinite; }
.load-emblem svg { width: 100%; height: 100%; }
.load-title { position: relative; margin: 6px 0 0; font: 600 66px/.82 var(--display); letter-spacing: 5px; text-align: center; }
.load-title span { color: var(--orange); }
.load-sub { font: 700 12px/1 var(--font); letter-spacing: 8px; color: var(--muted); margin-top: 2px; }
.load-bar { position: relative; width: min(420px, 72vw); height: 4px; background: rgba(255,255,255,.08); margin-top: 38px; overflow: hidden; clip-path: polygon(0 0, 100% 0, calc(100% - 6px) 100%, 0 100%); }
.load-bar i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--orange), var(--orange2), var(--cyan)); box-shadow: 0 0 16px rgba(255,150,60,.8); transition: width .25s ease; }
.load-row { width: min(420px, 72vw); display: flex; justify-content: space-between; font: 600 11px/1 var(--font); letter-spacing: 2.5px; color: var(--muted); margin-top: 9px; }
.load-row span:last-child { color: var(--orange2); }
.load-tip { position: absolute; bottom: max(34px, var(--safe-b)); width: min(560px, 82vw); text-align: center; font: 500 13px/1.5 var(--font); letter-spacing: .8px; color: var(--dim); }
.load-tip::before { content: ''; display: block; width: 40px; height: 1px; background: var(--orange); margin: 0 auto 12px; opacity: .7; }

/* ══════════════════ MENU ══════════════════ */
.menu-screen { z-index: 30; display: flex; flex-direction: column; padding: calc(20px + var(--safe-t)) calc(26px + var(--safe-r)) calc(14px + var(--safe-b)) calc(26px + var(--safe-l)); opacity: 1; transition: opacity .4s ease, visibility .4s; }
.menu-screen.out { opacity: 0; visibility: hidden; }
.menu-scrim { position: absolute; inset: 0; pointer-events: none;
  background:
    linear-gradient(90deg, rgba(3,8,13,.92) 0%, rgba(3,8,13,.64) 30%, rgba(3,8,13,.06) 57%, rgba(3,8,13,.3) 100%),
    linear-gradient(180deg, rgba(3,8,13,.7) 0%, transparent 18%, transparent 72%, rgba(3,8,13,.88) 100%); }
.menu-top { position: relative; z-index: 3; display: flex; align-items: center; gap: 22px; min-height: 62px; }
.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark { width: 50px; height: 50px; filter: drop-shadow(0 0 14px rgba(255, 122, 26, .35)); }
.brand-type { display: flex; flex-direction: column; line-height: .82; }
.brand-type b { font: 600 30px/.78 var(--display); letter-spacing: 2.5px; }
.brand-type b span { color: var(--orange); }
.brand-type em { font: 700 9px/1 var(--font); letter-spacing: 5.2px; color: var(--muted); font-style: normal; margin-top: 4px; }
.season-chip { display: flex; align-items: center; gap: 8px; padding: 7px 12px; border: 1px solid var(--line); background: rgba(9, 23, 34, .5); font: 700 10px/1 var(--font); letter-spacing: 2px; color: var(--muted); clip-path: polygon(6px 0, 100% 0, calc(100% - 6px) 100%, 0 100%); }
.season-chip i { width: 5px; height: 5px; background: var(--orange); border-radius: 50%; box-shadow: 0 0 8px var(--orange); }
.season-chip span { color: var(--ink); }
.profile-chip { margin-left: auto; display: flex; align-items: center; gap: 11px; padding: 6px 8px 6px 7px; min-width: 280px; border: 1px solid var(--line); background: linear-gradient(180deg, rgba(14,32,46,.82), rgba(6,15,23,.78)); backdrop-filter: blur(12px); clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px); cursor: pointer; transition: border-color .2s; }
.profile-chip:hover { border-color: var(--line2); }
.avatar { width: 44px; height: 44px; flex: none; display: grid; place-items: center; border: 1px solid rgba(255, 179, 71, .45); background: radial-gradient(circle at 50% 30%, #31546b, #0c1c28 70%); font: 600 24px/1 var(--display); color: var(--orange2); position: relative; overflow: hidden; }
.avatar::after { content: ''; position: absolute; inset: 0; background: linear-gradient(135deg, transparent 40%, rgba(255,255,255,.14)); }
.profile-meta { flex: 1; min-width: 0; }
.profile-name { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.profile-name span { font: 700 14px/1 var(--font); letter-spacing: .8px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.profile-name b { font: 600 12px/1 var(--display); letter-spacing: 1px; color: var(--orange2); }
.xp-bar { height: 3px; background: rgba(255,255,255,.1); margin: 5px 0 4px; overflow: hidden; }
.xp-bar i { display: block; height: 100%; background: linear-gradient(90deg, var(--orange), var(--amber)); box-shadow: 0 0 8px rgba(255, 150, 50, .5); }
.profile-stats { display: flex; justify-content: space-between; font: 600 9px/1 var(--font); letter-spacing: 1.1px; color: var(--dim); }
.profile-stats span:last-child { color: var(--muted); }
.icon-btn { width: 32px; height: 32px; flex: none; display: grid; place-items: center; border: 1px solid var(--line); background: rgba(255,255,255,.03); color: var(--muted); transition: .2s; }
.icon-btn svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.4; }
.icon-btn:hover { color: var(--orange2); border-color: rgba(255,179,71,.4); }

.menu-main { position: relative; z-index: 3; flex: 1; display: flex; align-items: center; justify-content: space-between; min-height: 0; gap: 28px; }
.menu-left { width: 486px; max-width: 46vw; display: flex; flex-direction: column; gap: 12px; }
.eyebrow { font: 700 10px/1 var(--font); letter-spacing: 4px; color: var(--orange2); display: flex; align-items: center; gap: 9px; }
.eyebrow::before { content: ''; width: 18px; height: 1px; background: var(--orange); }
.mode-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 7px; }
.mode-card { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 2px; padding: 10px 10px 9px; min-height: 82px; border: 1px solid var(--line); background: linear-gradient(180deg, rgba(16,35,50,.62), rgba(6,14,22,.72)); text-align: left; transition: .18s; clip-path: polygon(7px 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%, 0 7px); }
.mode-card:hover { border-color: var(--line2); background: linear-gradient(180deg, rgba(24,50,70,.7), rgba(8,20,30,.8)); transform: translateY(-1px); }
.mode-card.active { border-color: rgba(255, 138, 43, .7); background: linear-gradient(160deg, rgba(255,122,26,.2), rgba(20,35,48,.78) 55%, rgba(6,14,22,.8)); box-shadow: inset 0 0 22px rgba(255, 122, 26, .08), 0 8px 22px rgba(0,0,0,.25); }
.mode-card.active::after { content: ''; position: absolute; top: 0; left: 10px; right: 10px; height: 2px; background: linear-gradient(90deg, var(--orange), transparent); }
.mode-icon { width: 25px; height: 25px; color: var(--muted); margin-bottom: 2px; }
.mode-icon svg { width: 100%; height: 100%; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; }
.mode-card.active .mode-icon { color: var(--orange2); }
.mode-card b { font: 600 16px/.95 var(--display); letter-spacing: 1.3px; }
.mode-card em { font: 600 8px/1 var(--font); letter-spacing: 1.1px; color: var(--dim); font-style: normal; }
.mode-card.practice .mode-icon { color: var(--cyan); }
.mode-card.practice.active { border-color: rgba(99,220,255,.6); background: linear-gradient(160deg, rgba(99,220,255,.15), rgba(20,35,48,.78) 55%, rgba(6,14,22,.8)); }
.mode-card.practice.active::after { background: linear-gradient(90deg, var(--cyan), transparent); }

.match-card { display: flex; gap: 12px; padding: 10px; border: 1px solid var(--line); background: var(--glass); backdrop-filter: blur(10px); clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px); }
.match-map { position: relative; width: 106px; height: 106px; flex: none; overflow: hidden; border: 1px solid rgba(99,220,255,.22); background: #0a1b26; }
.match-map canvas { width: 100%; height: 100%; display: block; }
.map-scan { position: absolute; inset: 0; background: linear-gradient(180deg, transparent 0%, rgba(99,220,255,.22) 50%, transparent 51%); background-size: 100% 8px; opacity: .5; animation: scan 5s linear infinite; pointer-events: none; }
.map-tag { position: absolute; left: 0; right: 0; bottom: 0; padding: 4px 5px; font: 700 8px/1 var(--font); letter-spacing: 1.4px; text-align: center; background: rgba(3,9,14,.78); color: var(--orange2); }
.match-info { flex: 1; min-width: 0; display: flex; flex-direction: column; justify-content: center; }
.match-title { font: 600 17px/1 var(--display); letter-spacing: 1.6px; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.match-title span { font: 700 8px/1 var(--font); letter-spacing: 1.5px; color: var(--green); border: 1px solid rgba(84,230,165,.35); padding: 3px 5px; }
.match-sub { font: 500 11px/1.2 var(--font); color: var(--muted); margin-top: 2px; }
.match-stats { display: flex; gap: 18px; margin-top: 7px; }
.match-stats div { display: flex; flex-direction: column; }
.match-stats b { font: 600 19px/.9 var(--display); letter-spacing: 1px; color: var(--ink); }
.match-stats span { font: 600 7px/1 var(--font); letter-spacing: 1.2px; color: var(--dim); margin-top: 2px; }
.match-chips { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 8px; }
.match-chips > span { display: flex; align-items: center; gap: 4px; font: 700 7.5px/1 var(--font); letter-spacing: .9px; color: var(--muted); border: 1px solid rgba(255,255,255,.07); background: rgba(255,255,255,.025); padding: 4px 5px; }
.cta-row { display: flex; gap: 8px; align-items: stretch; }
.play-btn { position: relative; flex: 1; min-height: 68px; display: flex; flex-direction: column; justify-content: center; align-items: flex-start; padding: 10px 64px 10px 26px; overflow: hidden; color: #120801; background: linear-gradient(100deg, #ffb347, #ff7a1a 52%, #ef5a0c); clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%); box-shadow: 0 14px 38px rgba(255, 100, 20, .28); transition: transform .15s, filter .15s; }
.play-btn::before { content: ''; position: absolute; inset: 0; background: linear-gradient(120deg, transparent 30%, rgba(255,255,255,.4) 50%, transparent 70%); transform: translateX(-120%); animation: shine 4.2s ease-in-out infinite; }
.play-btn:hover { transform: translateY(-2px); filter: brightness(1.07); }
.play-btn:active { transform: translateY(0); }
.play-btn-glow { position: absolute; inset: auto 0 0; height: 3px; background: rgba(255,255,255,.55); opacity: .5; }
.play-label { font: 600 40px/.78 var(--display); letter-spacing: 4px; }
.play-sub { font: 700 9px/1 var(--font); letter-spacing: 2px; opacity: .7; margin-top: 5px; }
.play-arrow { position: absolute; right: 22px; top: 50%; width: 28px; height: 28px; transform: translateY(-50%); fill: none; stroke: #170900; stroke-width: 1.6; transition: transform .2s; }
.play-btn:hover .play-arrow { transform: translate(4px, -50%); }
.online-btn { width: 118px; flex: none; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px; border: 1px solid var(--line2); background: rgba(8,20,30,.72); color: var(--muted); clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%); transition: .2s; }
.online-btn:hover { color: var(--cyan); border-color: rgba(99,220,255,.5); background: rgba(15,38,52,.8); }
.online-btn svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.5; }
.online-btn span { font: 700 10px/1 var(--font); letter-spacing: 2px; }
.online-btn em { display: block; font: 600 6.5px/1 var(--font); letter-spacing: 1px; font-style: normal; color: var(--dim); margin-top: 3px; }
.menu-hint { font: 500 10px/1.2 var(--font); letter-spacing: .7px; color: var(--dim); }
.menu-hint kbd { font-size: 9px; padding: 0 4px; }

.menu-right { align-self: flex-end; margin-bottom: 12px; width: 330px; max-width: 28vw; }
.operator-card { padding: 13px 15px 12px; border: 1px solid var(--line); background: linear-gradient(160deg, rgba(13,30,44,.82), rgba(5,13,20,.8)); backdrop-filter: blur(14px); clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px); }
.op-head { display: flex; justify-content: space-between; align-items: center; font: 700 8px/1 var(--font); letter-spacing: 1.8px; color: var(--dim); }
.op-head b { color: var(--cyan); border: 1px solid rgba(99,220,255,.28); padding: 3px 5px; font-weight: 700; }
.op-name { font: 600 30px/.9 var(--display); letter-spacing: 2px; margin-top: 4px; color: var(--ink); }
.op-sub { font: 600 7.5px/1 var(--font); letter-spacing: 1.2px; color: var(--dim); margin-top: 2px; }
.op-stats { display: flex; flex-direction: column; gap: 5px; margin: 12px 0; }
.op-stats div { display: flex; align-items: center; gap: 8px; }
.op-stats span { width: 56px; font: 700 7.5px/1 var(--font); letter-spacing: 1px; color: var(--muted); }
.op-stats i { flex: 1; height: 3px; background: rgba(255,255,255,.08); }
.op-stats i b { display: block; height: 100%; background: linear-gradient(90deg, var(--orange), var(--orange2)); }
.op-actions { display: flex; gap: 6px; }
.ghost-btn { flex: 1; padding: 8px 5px; border: 1px solid var(--line); background: rgba(255,255,255,.03); font: 700 8px/1 var(--font); letter-spacing: 1.4px; color: var(--muted); transition: .2s; }
.ghost-btn:hover { border-color: rgba(255,179,71,.5); color: var(--orange2); }
.skin-row { display: flex; gap: 5px; margin-top: 10px; }
.skin-row button { width: 28px; height: 28px; border: 1px solid rgba(255,255,255,.12); position: relative; overflow: hidden; }
.skin-row button.active { border-color: var(--orange2); box-shadow: 0 0 0 1px rgba(255,179,71,.4); }
.skin-row button.locked::after { content: '🔒'; position: absolute; inset: 0; display: grid; place-items: center; font-size: 9px; background: rgba(0,0,0,.55); }

.menu-nav { position: relative; z-index: 3; display: flex; gap: 2px; padding-top: 9px; border-top: 1px solid rgba(134,198,235,.1); }
.menu-nav button { display: flex; align-items: center; gap: 7px; padding: 8px 15px; color: var(--muted); font: 700 9px/1 var(--font); letter-spacing: 1.6px; transition: .18s; border-bottom: 1px solid transparent; }
.menu-nav button svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.4; }
.menu-nav button:hover { color: var(--ink); background: rgba(255,255,255,.035); border-bottom-color: var(--orange); }
.menu-footer { position: relative; z-index: 3; display: flex; justify-content: space-between; padding-top: 7px; font: 600 7.5px/1 var(--font); letter-spacing: 1.3px; color: #3d5261; }
.menu-footer b { color: var(--muted); }
.footer-right { display: flex; align-items: center; gap: 6px; }
.footer-right i { width: 4px; height: 4px; border-radius: 50%; background: var(--green); box-shadow: 0 0 6px var(--green); }

/* ══════════════════ HUD ══════════════════ */
.hud { position: absolute; inset: 0; z-index: 12; pointer-events: none; padding: calc(12px + var(--safe-t)) calc(14px + var(--safe-r)) calc(10px + var(--safe-b)) calc(14px + var(--safe-l)); }
.hud button, .hud .interact-prompt, .hud .quick-actions { pointer-events: auto; }
.hud-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; }
.hud-block { min-width: 150px; }
.alive-block { display: flex; align-items: center; gap: 14px; padding: 7px 12px; border-left: 2px solid var(--orange); background: linear-gradient(90deg, rgba(5,13,20,.7), transparent); }
.alive-num { display: flex; align-items: baseline; gap: 5px; }
.alive-num b { font: 600 34px/.8 var(--display); letter-spacing: 1px; }
.alive-num span { font: 700 8px/1 var(--font); letter-spacing: 1.4px; color: var(--muted); }
.hud-kills { display: flex; align-items: center; gap: 4px; color: var(--orange2); }
.hud-kills svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.6; }
.hud-kills b { font: 600 22px/.8 var(--display); }
.compass-wrap { flex: 1; max-width: 430px; display: flex; flex-direction: column; align-items: center; gap: 4px; margin-top: 1px; }
.compass { position: relative; width: 100%; height: 25px; overflow: hidden; mask-image: linear-gradient(90deg, transparent, #000 16%, #000 84%, transparent); }
.compass-track { position: absolute; inset: 0; display: flex; align-items: center; }
.compass-track span { position: absolute; transform: translateX(-50%); font: 700 8px/1 var(--font); letter-spacing: 1px; color: var(--muted); white-space: nowrap; }
.compass-track span.cardinal { font-size: 11px; color: var(--ink); }
.compass-track span.tick { width: 1px; height: 6px; background: rgba(255,255,255,.22); padding: 0; }
.compass-needle { position: absolute; left: 50%; top: 0; width: 2px; height: 8px; background: var(--orange); transform: translateX(-50%); box-shadow: 0 0 8px var(--orange); }
.zone-strip { display: flex; align-items: center; gap: 8px; padding: 4px 10px; border: 1px solid rgba(99,220,255,.18); background: rgba(5,14,21,.62); clip-path: polygon(5px 0, 100% 0, calc(100% - 5px) 100%, 0 100%); }
.zone-strip span { font: 700 8px/1 var(--font); letter-spacing: 1.4px; color: var(--cyan); }
.zone-strip span:last-child { color: var(--dim); }
.zone-strip .zone-timer { font: 600 17px/.8 var(--display); letter-spacing: 1px; color: var(--ink); font-style: normal; }
.hud-right { text-align: right; padding-top: 4px; }
.match-id { font: 700 9px/1 var(--font); letter-spacing: 1.5px; color: var(--muted); }
.match-id b { color: var(--orange2); margin-left: 5px; }
.network { display: flex; align-items: center; justify-content: flex-end; gap: 5px; margin-top: 4px; font: 600 7.5px/1 var(--font); letter-spacing: 1px; color: var(--dim); }
.network i { width: 4px; height: 4px; border-radius: 50%; background: var(--green); box-shadow: 0 0 5px var(--green); }
.killfeed { position: absolute; top: 76px; right: calc(16px + var(--safe-r)); width: 290px; display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
.killfeed-item { display: flex; align-items: center; gap: 6px; padding: 4px 8px; background: linear-gradient(90deg, transparent, rgba(4,11,17,.82)); border-right: 2px solid var(--orange); font: 600 10px/1 var(--font); letter-spacing: .5px; animation: feedIn .22s ease; }
.killfeed-item b { color: var(--ink); }
.killfeed-item em { font-style: normal; color: var(--muted); }
.killfeed-item .killer { color: var(--orange2); }
.killfeed-item .victim { color: var(--cyan); }
.killfeed-item svg { width: 13px; height: 13px; fill: none; stroke: var(--muted); stroke-width: 1.5; }
.killfeed-item .zone-kill { color: var(--violet); }

.announce { position: absolute; top: 19%; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 3px; opacity: 0; transition: opacity .3s, transform .3s; text-align: center; }
.announce.show { opacity: 1; transform: translate(-50%, -4px); }
.announce b { font: 600 30px/1 var(--display); letter-spacing: 3px; text-shadow: 0 3px 18px rgba(0,0,0,.7); }
.announce span { font: 700 9px/1 var(--font); letter-spacing: 2.5px; color: var(--orange2); }
.match-banner { position: absolute; top: 38%; left: 50%; transform: translate(-50%, -50%); text-align: center; padding: 14px 40px; background: linear-gradient(90deg, transparent, rgba(4,11,17,.8) 20%, rgba(4,11,17,.8) 80%, transparent); animation: bannerIn .5s ease; }
.match-banner b { display: block; font: 600 36px/1 var(--display); letter-spacing: 4px; color: var(--orange2); text-shadow: 0 0 30px rgba(255,122,26,.45); }
.match-banner span { display: block; font: 700 9px/1 var(--font); letter-spacing: 3px; color: var(--muted); margin-top: 5px; }

.crosshair { position: absolute; left: 50%; top: 50%; width: 60px; height: 60px; transform: translate(-50%, -50%); pointer-events: none; transition: opacity .15s; }
.ch { position: absolute; background: rgba(245, 252, 255, .9); box-shadow: 0 0 2px rgba(0,0,0,.8); }
.ch-t, .ch-b { width: 1.5px; height: 7px; left: 50%; transform: translateX(-50%); }
.ch-l, .ch-r { width: 7px; height: 1.5px; top: 50%; transform: translateY(-50%); }
.ch-t { top: 7px; } .ch-b { bottom: 7px; } .ch-l { left: 7px; } .ch-r { right: 7px; }
.ch-dot { position: absolute; left: 50%; top: 50%; width: 2px; height: 2px; background: var(--orange2); transform: translate(-50%, -50%); border-radius: 50%; }
.crosshair.ads .ch { background: var(--cyan); }
.crosshair.hidden-cross { opacity: 0; }
.hitmarker { position: absolute; inset: 0; opacity: 0; }
.hitmarker.show { opacity: 1; animation: hitPulse .18s ease; }
.hitmarker i { position: absolute; width: 9px; height: 2px; background: #fff; left: 50%; top: 50%; box-shadow: 0 0 5px rgba(255,255,255,.9); }
.hitmarker i:nth-child(1) { transform: translate(-50%, -50%) rotate(45deg) translate(9px, 0); }
.hitmarker i:nth-child(2) { transform: translate(-50%, -50%) rotate(-45deg) translate(9px, 0); }
.hitmarker i:nth-child(3) { transform: translate(-50%, -50%) rotate(45deg) translate(-9px, 0); }
.hitmarker i:nth-child(4) { transform: translate(-50%, -50%) rotate(-45deg) translate(-9px, 0); }
.hitmarker.kill i { background: var(--red); width: 12px; }
.damage-indicator { position: absolute; inset: 0; pointer-events: none; opacity: 0; transition: opacity .3s; }
.damage-indicator.show { opacity: 1; }
.damage-vignette { position: absolute; inset: 0; pointer-events: none; opacity: 0; background: radial-gradient(ellipse at center, transparent 38%, rgba(180, 15, 20, .55) 100%); transition: opacity .25s; }
.damage-vignette.show { opacity: 1; }
.interact-prompt { position: absolute; left: 50%; top: 62%; transform: translateX(-50%); }
.interact-prompt button { display: flex; align-items: center; gap: 9px; padding: 7px 14px 7px 8px; border: 1px solid rgba(255,179,71,.5); background: rgba(6,15,22,.86); clip-path: polygon(6px 0, 100% 0, calc(100% - 6px) 100%, 0 100%); }
.interact-prompt .key { width: 22px; height: 22px; display: grid; place-items: center; background: var(--orange2); color: #120801; font: 700 11px/1 var(--font); }
.interact-prompt b { font: 700 10px/1 var(--font); letter-spacing: 1.6px; color: var(--ink); }

.hud-bottom { position: absolute; left: calc(16px + var(--safe-l)); right: calc(16px + var(--safe-r)); bottom: calc(13px + var(--safe-b)); display: flex; align-items: flex-end; justify-content: space-between; gap: 18px; }
.vitals { width: 246px; padding: 9px 11px 8px; background: linear-gradient(100deg, rgba(4,11,17,.86), rgba(4,11,17,.2)); border-left: 2px solid var(--orange); }
.vitals-name { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 5px; }
.vitals-name b { font: 700 12px/1 var(--font); letter-spacing: 1.2px; }
.vitals-name span { font: 700 7px/1 var(--font); letter-spacing: 1.2px; color: var(--muted); }
.bar { position: relative; height: 12px; background: rgba(255,255,255,.1); margin-bottom: 4px; overflow: hidden; }
.bar i { display: block; height: 100%; width: 100%; transition: width .18s; }
.armor-bar i { background: linear-gradient(90deg, #2e9dc4, #63dcff); }
.health-bar i { background: linear-gradient(90deg, #35b77a, #6ff0a8); }
.bar span { position: absolute; right: 4px; top: 0; font: 700 9px/12px var(--font); color: rgba(0,0,0,.75); }
.bar em { position: absolute; left: 4px; top: 0; font: 700 7px/12px var(--font); letter-spacing: 1.3px; color: rgba(0,10,15,.6); font-style: normal; }
.health-bar.low i { background: linear-gradient(90deg, #c93030, #ff5b5b); animation: lowHealth 1s ease-in-out infinite; }
.vitals-row { display: flex; gap: 4px; flex-wrap: wrap; margin-top: 4px; }
.equip-tag, .status-tag { font: 700 6.5px/1 var(--font); letter-spacing: .9px; padding: 3px 4px; border: 1px solid rgba(255,255,255,.09); color: var(--dim); }
.status-tag { color: var(--green); border-color: rgba(84,230,165,.25); }
.heal-progress { position: relative; height: 13px; margin-top: 5px; background: rgba(255,255,255,.09); }
.heal-progress i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, #35b77a, #6ff0a8); }
.heal-progress span { position: absolute; inset: 0; text-align: center; font: 700 7px/13px var(--font); letter-spacing: 1.2px; color: #06130d; }

.weapon-hud { flex: 1; display: flex; justify-content: center; align-items: flex-end; gap: 8px; }
.weapon-slots { display: flex; gap: 4px; }
.wslot { width: 62px; padding: 5px 6px; border: 1px solid rgba(255,255,255,.1); background: rgba(4,11,17,.58); opacity: .6; transition: .2s; }
.wslot.active { opacity: 1; border-color: rgba(255,179,71,.55); background: rgba(10,20,28,.82); box-shadow: inset 0 0 12px rgba(255,122,26,.08); }
.wslot b { display: block; font: 700 7px/1 var(--font); color: var(--orange2); }
.wslot span { display: block; font: 600 11px/.95 var(--display); letter-spacing: .7px; margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wslot em { display: block; font: 600 6px/1 var(--font); letter-spacing: .8px; color: var(--dim); font-style: normal; margin-top: 2px; }
.ammo-panel { min-width: 156px; padding: 4px 10px 5px; background: linear-gradient(180deg, rgba(4,11,17,.72), rgba(4,11,17,.4)); border-bottom: 2px solid var(--orange); }
.ammo-main { display: flex; align-items: baseline; gap: 4px; }
.ammo-main b { font: 600 38px/.8 var(--display); letter-spacing: 1px; }
.ammo-main span { font: 600 15px/.9 var(--display); color: var(--muted); }
.ammo-main i { font-style: normal; }
.ammo-meta { display: flex; justify-content: space-between; gap: 8px; margin-top: 1px; }
.ammo-meta span { font: 700 8px/1 var(--font); letter-spacing: 1px; color: var(--ink); }
.ammo-meta em { font: 700 7px/1 var(--font); letter-spacing: 1px; color: var(--orange2); font-style: normal; }
.reload-bar { height: 3px; background: rgba(255,255,255,.1); margin-top: 4px; }
.reload-bar i { display: block; height: 100%; width: 0; background: var(--orange2); }
.minimap-wrap { position: relative; width: 172px; }
.minimap-frame { position: relative; width: 172px; height: 172px; border: 1px solid rgba(99,220,255,.28); background: #07141d; overflow: hidden; box-shadow: 0 8px 26px rgba(0,0,0,.35); }
.minimap-frame canvas { width: 100%; height: 100%; display: block; }
.mini-grid { position: absolute; inset: 0; pointer-events: none; background-image: linear-gradient(rgba(99,220,255,.07) 1px, transparent 1px), linear-gradient(90deg, rgba(99,220,255,.07) 1px, transparent 1px); background-size: 25% 25%; }
.mini-n { position: absolute; top: 3px; left: 50%; transform: translateX(-50%); font: 700 7px/1 var(--font); color: var(--cyan); }
.mini-info { display: flex; justify-content: space-between; padding: 3px 4px; font: 700 7px/1 var(--font); letter-spacing: 1px; color: var(--muted); background: rgba(4,11,17,.6); }
.mini-info b { color: var(--ink); }
.mini-map-btn { position: absolute; right: 4px; top: 4px; width: 25px; height: 25px; display: grid; place-items: center; background: rgba(4,11,17,.7); border: 1px solid var(--line); }
.mini-map-btn svg { width: 13px; height: 13px; fill: none; stroke: var(--cyan); stroke-width: 1.5; }
.quick-actions { position: absolute; right: calc(18px + var(--safe-r)); bottom: calc(196px + var(--safe-b)); display: flex; flex-direction: column; gap: 5px; }
.quick-btn { display: flex; align-items: center; gap: 5px; padding: 4px 6px; border: 1px solid rgba(255,255,255,.08); background: rgba(4,11,17,.52); color: var(--muted); }
.quick-btn svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 1.5; }
.quick-btn span { font: 700 6.5px/1 var(--font); letter-spacing: .8px; }
.quick-btn:hover { color: var(--cyan); }
.spectate-banner { position: absolute; top: 72px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 10px; padding: 6px 12px; border: 1px solid rgba(183,139,255,.35); background: rgba(8,10,22,.78); }
.spectate-banner span { font: 700 8px/1 var(--font); letter-spacing: 2px; color: var(--violet); }
.spectate-banner b { font: 600 16px/1 var(--display); letter-spacing: 1px; }
.spectate-banner div { display: flex; gap: 4px; margin-left: 6px; }
.spectate-banner button { padding: 4px 7px; border: 1px solid var(--line); font: 700 7px/1 var(--font); letter-spacing: 1px; color: var(--muted); }
.spectate-banner button:hover { color: var(--ink); border-color: var(--line2); }

/* ══════════════════ TOUCH ══════════════════ */
.touch-controls { position: absolute; inset: 0; z-index: 14; pointer-events: none; }
.touch-controls .tbtn, .touch-controls .joystick { pointer-events: auto; }
.joystick { position: absolute; left: calc(24px + var(--safe-l)); bottom: calc(30px + var(--safe-b)); width: 124px; height: 124px; border-radius: 50%; background: radial-gradient(circle, rgba(99,220,255,.08), rgba(4,11,17,.38) 70%); border: 1px solid rgba(99,220,255,.28); box-shadow: inset 0 0 30px rgba(99,220,255,.08); touch-action: none; }
.joystick-ring { position: absolute; inset: 12px; border: 1px dashed rgba(99,220,255,.18); border-radius: 50%; }
.joystick-knob { position: absolute; left: 50%; top: 50%; width: 50px; height: 50px; border-radius: 50%; transform: translate(-50%, -50%); background: radial-gradient(circle at 40% 35%, rgba(180,240,255,.65), rgba(40,130,170,.5) 55%, rgba(8,30,44,.85)); border: 1px solid rgba(190,245,255,.55); box-shadow: 0 4px 18px rgba(0,0,0,.4); }
.joystick > span { position: absolute; left: 50%; bottom: -15px; transform: translateX(-50%); font: 700 6.5px/1 var(--font); letter-spacing: 1.5px; color: rgba(99,220,255,.55); }
.tbtn { position: absolute; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; border-radius: 50%; border: 1px solid rgba(255,255,255,.2); background: radial-gradient(circle at 40% 30%, rgba(40,70,90,.5), rgba(4,12,18,.62) 70%); color: rgba(230,246,255,.85); backdrop-filter: blur(2px); box-shadow: 0 3px 14px rgba(0,0,0,.25); touch-action: none; transition: transform .08s, background .12s, border-color .12s; }
.tbtn svg { width: 24px; height: 24px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; }
.tbtn span { font: 700 6px/1 var(--font); letter-spacing: .8px; }
.tbtn.active { background: radial-gradient(circle at 40% 30%, rgba(255,160,70,.6), rgba(120,50,10,.55) 70%); border-color: var(--orange2); transform: scale(.94); }
.tbtn-fire { right: calc(26px + var(--safe-r)); bottom: calc(96px + var(--safe-b)); width: 84px; height: 84px; border-color: rgba(255,138,43,.55); background: radial-gradient(circle at 40% 30%, rgba(255,150,60,.32), rgba(60,20,5,.6) 72%); }
.tbtn-fire svg { width: 32px; height: 32px; }
.tbtn-aim { right: calc(118px + var(--safe-r)); bottom: calc(152px + var(--safe-b)); width: 58px; height: 58px; }
.tbtn-jump { right: calc(118px + var(--safe-r)); bottom: calc(88px + var(--safe-b)); width: 54px; height: 54px; }
.tbtn-crouch { right: calc(188px + var(--safe-r)); bottom: calc(110px + var(--safe-b)); width: 50px; height: 50px; }
.tbtn-reload { right: calc(30px + var(--safe-r)); bottom: calc(192px + var(--safe-b)); width: 52px; height: 52px; }
.tbtn-swap { right: calc(94px + var(--safe-r)); bottom: calc(216px + var(--safe-b)); width: 48px; height: 48px; }
.tbtn-interact { right: calc(176px + var(--safe-r)); bottom: calc(180px + var(--safe-b)); width: 54px; height: 54px; border-color: rgba(255,179,71,.45); }
.tbtn-sprint { right: calc(246px + var(--safe-r)); bottom: calc(70px + var(--safe-b)); width: 48px; height: 48px; }
.tbtn-vehicle { right: calc(252px + var(--safe-r)); bottom: calc(136px + var(--safe-b)); width: 48px; height: 48px; }
.tbtn-vehicle { display: none; }
.vehicle-active .tbtn-vehicle { display: flex; }
.vehicle-active .tbtn-crouch, .vehicle-active .tbtn-jump, .vehicle-active .tbtn-sprint { display: none; }

.layout-editing .tbtn { border-style: dashed; border-color: var(--cyan); }
.layout-editing .joystick { border-color: var(--cyan); }
.layout-editing .tbtn::after { content: '✥'; position: absolute; top: -7px; right: -7px; width: 15px; height: 15px; display: grid; place-items: center; border-radius: 50%; background: var(--cyan); color: #001018; font-size: 9px; }
.layout-edit-banner { position: absolute; top: calc(10px + var(--safe-t)); left: 50%; transform: translateX(-50%); z-index: 60; display: flex; align-items: center; gap: 8px; padding: 6px 10px; background: rgba(4,12,18,.9); border: 1px solid var(--cyan); font: 700 8px/1 var(--font); letter-spacing: 1.2px; color: var(--cyan); }
.layout-edit-banner button { padding: 3px 6px; border: 1px solid var(--line2); font: 700 7px/1 var(--font); letter-spacing: 1px; }
.layout-edit-banner #btn-layout-save { background: var(--cyan); color: #001018; }

/* ══════════════════ OVERLAYS / PANELS ══════════════════ */
.overlay-root { position: absolute; inset: 0; z-index: 50; display: none; }
.overlay-root.open { display: block; }
.overlay-backdrop { position: absolute; inset: 0; background: rgba(1, 6, 10, .66); backdrop-filter: blur(4px); }
.panel { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: min(1000px, 92vw); max-height: 88vh; display: none; flex-direction: column; background: linear-gradient(160deg, rgba(12,28,41,.97), rgba(5,13,20,.98)); border: 1px solid var(--line2); box-shadow: var(--shadow); clip-path: polygon(16px 0, 100% 0, 100% calc(100% - 16px), calc(100% - 16px) 100%, 0 100%, 0 16px); }
.panel.open { display: flex; animation: panelIn .22s ease; }
.panel::before { content: ''; position: absolute; top: 0; left: 18px; right: 18px; height: 2px; background: linear-gradient(90deg, var(--orange), transparent 55%, var(--cyan)); opacity: .8; }
.panel-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 20px 12px; border-bottom: 1px solid var(--line); }
.panel-head > div:first-child { display: flex; flex-direction: column; gap: 1px; }
.panel-head span { font: 700 8px/1 var(--font); letter-spacing: 2.4px; color: var(--orange2); }
.panel-head h2 { margin: 0; font: 600 30px/.9 var(--display); letter-spacing: 2px; }
.close-btn { width: 32px; height: 32px; display: grid; place-items: center; border: 1px solid var(--line); color: var(--muted); font: 400 15px/1 var(--font); transition: .2s; }
.close-btn:hover { color: var(--ink); border-color: var(--orange2); }
.panel-foot { display: flex; justify-content: space-between; gap: 12px; padding: 9px 20px; border-top: 1px solid var(--line); font: 600 7.5px/1.2 var(--font); letter-spacing: 1px; color: var(--dim); }
.panel-foot b { color: var(--muted); }
.panel h3 { margin: 0 0 7px; font: 700 8px/1 var(--font); letter-spacing: 2px; color: var(--muted); }
.wide-btn { padding: 10px 14px; border: 1px solid var(--line2); background: rgba(255,255,255,.035); font: 700 10px/1 var(--font); letter-spacing: 1.5px; color: var(--muted); text-align: left; transition: .18s; }
.wide-btn:hover { color: var(--ink); border-color: var(--orange2); background: rgba(255,122,26,.08); }
.wide-btn.primary { background: linear-gradient(100deg, var(--orange2), var(--orange)); border: 0; color: #120801; text-align: center; font-weight: 700; }
.wide-btn.primary:hover { filter: brightness(1.1); }
.wide-btn.danger { color: #ff8a8a; border-color: rgba(255,75,75,.3); }
.wide-btn.danger:hover { background: rgba(255,75,75,.1); border-color: var(--red); }

/* Inventory */
.inv-grid { display: grid; grid-template-columns: 1fr 1.1fr; gap: 20px; padding: 16px 20px; overflow: auto; }
.inv-col { min-width: 0; }
.inv-weapons { display: flex; flex-direction: column; gap: 6px; margin-bottom: 15px; }
.inv-weapon { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border: 1px solid var(--line); background: rgba(255,255,255,.025); }
.inv-weapon.active { border-color: rgba(255,179,71,.55); background: rgba(255,122,26,.07); }
.inv-weapon .wicon { width: 46px; height: 30px; display: grid; place-items: center; color: var(--orange2); }
.inv-weapon .wicon svg { width: 44px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.4; }
.inv-weapon .wmeta { flex: 1; }
.inv-weapon .wmeta b { display: block; font: 600 14px/1 var(--display); letter-spacing: 1px; }
.inv-weapon .wmeta span { font: 600 8px/1 var(--font); color: var(--dim); letter-spacing: .8px; }
.inv-weapon .wammo { font: 600 18px/.9 var(--display); color: var(--muted); }
.inv-weapon .wammo small { font-size: 11px; color: var(--dim); }
.inv-weapon .wbtn { padding: 5px 7px; border: 1px solid var(--line); font: 700 7px/1 var(--font); letter-spacing: .8px; color: var(--muted); }
.inv-weapon .wbtn:hover { color: var(--orange2); border-color: var(--orange2); }
.inv-ammo { display: grid; grid-template-columns: repeat(2, 1fr); gap: 5px; }
.ammo-item { display: flex; justify-content: space-between; padding: 7px 9px; border: 1px solid var(--line); background: rgba(255,255,255,.02); }
.ammo-item span { font: 700 8px/1 var(--font); letter-spacing: 1px; color: var(--muted); }
.ammo-item b { font: 600 16px/.8 var(--display); color: var(--ink); }
.inv-items { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin-bottom: 15px; }
.inv-item { position: relative; min-height: 70px; display: flex; flex-direction: column; justify-content: space-between; padding: 7px; border: 1px solid var(--line); background: rgba(255,255,255,.025); text-align: left; }
.inv-item:hover { border-color: var(--line2); background: rgba(255,255,255,.05); }
.inv-item .item-icon { width: 22px; height: 22px; color: var(--cyan); }
.inv-item .item-icon svg { width: 100%; height: 100%; fill: none; stroke: currentColor; stroke-width: 1.4; }
.inv-item b { font: 600 10px/1 var(--display); letter-spacing: .8px; }
.inv-item span { font: 600 6.5px/1 var(--font); color: var(--dim); letter-spacing: .6px; }
.inv-item .qty { position: absolute; right: 5px; top: 5px; font: 600 11px/1 var(--display); color: var(--orange2); }
.inv-empty { padding: 14px; border: 1px dashed var(--line); font: 600 9px/1.4 var(--font); color: var(--dim); text-align: center; letter-spacing: 1px; }
.inv-ground { display: flex; flex-direction: column; gap: 4px; max-height: 130px; overflow: auto; }
.ground-item { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 6px 8px; border: 1px solid var(--line); background: rgba(255,255,255,.02); }
.ground-item span { font: 700 9px/1 var(--font); letter-spacing: .6px; }
.ground-item button { padding: 4px 7px; border: 1px solid rgba(255,179,71,.4); color: var(--orange2); font: 700 7px/1 var(--font); letter-spacing: .8px; }
.pack-cap { text-align: right; font: 600 16px/1 var(--display); color: var(--muted); }
.pack-cap b { color: var(--orange2); font-size: 24px; }
.pack-cap em { display: block; font: 700 7px/1 var(--font); letter-spacing: 1.4px; color: var(--dim); font-style: normal; }

/* Map */
.panel-map { width: min(860px, 94vw); }
.full-map-wrap { position: relative; margin: 14px auto; width: min(620px, 74vh, 76vw); aspect-ratio: 1; border: 1px solid var(--line2); background: #07141d; }
.full-map-wrap canvas { width: 100%; height: 100%; display: block; }
.map-legend { position: absolute; left: 8px; bottom: 8px; display: flex; flex-wrap: wrap; gap: 8px; padding: 5px 7px; background: rgba(3,9,14,.75); }
.map-legend span { display: flex; align-items: center; gap: 4px; font: 700 6.5px/1 var(--font); letter-spacing: .8px; color: var(--muted); }
.lg { width: 7px; height: 7px; display: inline-block; border-radius: 50%; }
.lg.you { background: var(--orange2); box-shadow: 0 0 6px var(--orange2); }
.lg.team { background: var(--cyan); }
.lg.zone { border: 1px solid #fff; background: transparent; }
.lg.next { border: 1px solid var(--amber); background: transparent; }
.lg.poi { background: var(--muted); border-radius: 1px; }
.map-coords { position: absolute; right: 8px; top: 8px; padding: 4px 6px; background: rgba(3,9,14,.75); font: 700 7px/1 var(--font); letter-spacing: 1px; color: var(--cyan); }

/* Settings */
.panel-settings { width: min(920px, 94vw); }
.settings-body { display: grid; grid-template-columns: 1fr 1fr; gap: 20px 28px; padding: 16px 20px; overflow: auto; }
.settings-group { display: flex; flex-direction: column; gap: 9px; }
.settings-group label { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 8px; font: 700 8px/1 var(--font); letter-spacing: 1.2px; color: var(--muted); }
.settings-group label input[type=range] { grid-column: 1; width: 100%; height: 3px; accent-color: var(--orange); background: rgba(255,255,255,.12); }
.settings-group label output { grid-column: 2; grid-row: 2; font: 600 12px/1 var(--display); color: var(--orange2); }
.settings-group select { grid-column: 1 / -1; padding: 7px 8px; border: 1px solid var(--line); background: #0a1a25; font: 700 9px/1 var(--font); letter-spacing: 1px; color: var(--ink); }
.switch-row { grid-template-columns: 1fr auto !important; cursor: pointer; }
.switch-row input { display: none; }
.switch { width: 30px; height: 16px; border-radius: 10px; background: rgba(255,255,255,.12); position: relative; transition: .2s; }
.switch::after { content: ''; position: absolute; left: 2px; top: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--muted); transition: .2s; }
.switch-row input:checked + .switch { background: rgba(255,122,26,.45); }
.switch-row input:checked + .switch::after { left: 16px; background: var(--orange2); box-shadow: 0 0 8px var(--orange); }
.settings-group .wide-btn { margin-top: 3px; }

/* Profile */
.profile-body { padding: 18px 20px; overflow: auto; }
.profile-hero { display: flex; align-items: center; gap: 16px; padding-bottom: 16px; border-bottom: 1px solid var(--line); }
.profile-badge { width: 72px; height: 72px; display: grid; place-items: center; border: 1px solid rgba(255,179,71,.45); background: radial-gradient(circle at 50% 30%, #31546b, #0c1c28 70%); font: 600 40px/1 var(--display); color: var(--orange2); }
.profile-hero h3 { margin: 0; font: 600 28px/.9 var(--display); letter-spacing: 2px; }
.profile-hero p { margin: 2px 0 7px; font: 700 8px/1 var(--font); letter-spacing: 1.6px; color: var(--muted); }
.xp-bar.big { width: 320px; max-width: 46vw; height: 5px; }
.profile-hero span { font: 600 7.5px/1 var(--font); letter-spacing: 1px; color: var(--dim); }
.stat-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; margin: 16px 0; background: var(--line); border: 1px solid var(--line); }
.stat-grid div { padding: 12px 13px; background: #081620; }
.stat-grid b { display: block; font: 600 28px/.9 var(--display); letter-spacing: 1px; color: var(--ink); }
.stat-grid span { font: 700 7px/1 var(--font); letter-spacing: 1.4px; color: var(--dim); }
.profile-skins h3 { margin-bottom: 9px; }
.skin-list { display: flex; flex-wrap: wrap; gap: 7px; }
.skin-card { width: 86px; padding: 6px; border: 1px solid var(--line); background: rgba(255,255,255,.025); text-align: left; position: relative; }
.skin-card.active { border-color: var(--orange2); }
.skin-card .skin-swatch { height: 38px; margin-bottom: 4px; position: relative; overflow: hidden; }
.skin-card .skin-swatch::after { content: ''; position: absolute; inset: 0; background: linear-gradient(135deg, transparent 40%, rgba(255,255,255,.22)); }
.skin-card b { display: block; font: 600 9px/1 var(--display); letter-spacing: .7px; }
.skin-card span { font: 600 6.5px/1 var(--font); color: var(--dim); letter-spacing: .6px; }
.skin-card.locked { opacity: .55; }
.skin-card.locked::after { content: 'LV ' attr(data-level); position: absolute; inset: 0; display: grid; place-items: center; background: rgba(0,0,0,.55); font: 700 8px/1 var(--font); color: var(--orange2); letter-spacing: 1px; }

/* Character */
.character-body { display: grid; grid-template-columns: 300px 1fr; gap: 20px; padding: 18px 20px; overflow: auto; }
.char-preview { position: relative; min-height: 330px; border: 1px solid var(--line); background: radial-gradient(ellipse at 50% 60%, rgba(99,220,255,.12), transparent 60%), linear-gradient(180deg, #0b1e2b, #061018); overflow: hidden; }
.char-preview::after { content: ''; position: absolute; left: 50%; bottom: 0; width: 70%; height: 40%; transform: translateX(-50%); background: radial-gradient(ellipse, rgba(99,220,255,.18), transparent 70%); }
.char-preview span { position: absolute; left: 8px; top: 8px; font: 700 7px/1 var(--font); letter-spacing: 1.4px; color: var(--cyan); }
.char-scan { position: absolute; inset: 0; background: repeating-linear-gradient(0deg, transparent 0 4px, rgba(99,220,255,.035) 4px 5px); }
.char-options { display: flex; flex-direction: column; gap: 14px; }
.text-label { display: flex; flex-direction: column; gap: 5px; font: 700 8px/1 var(--font); letter-spacing: 1.6px; color: var(--muted); }
.text-label input { padding: 8px 9px; border: 1px solid var(--line); background: rgba(255,255,255,.03); font: 600 16px/1 var(--display); letter-spacing: 1.5px; color: var(--ink); }
.swatch-group h3 { margin-bottom: 7px; }
.swatches { display: flex; flex-wrap: wrap; gap: 6px; }
.swatches button { width: 32px; height: 32px; border: 1px solid rgba(255,255,255,.14); position: relative; }
.swatches button.active { border-color: var(--orange2); box-shadow: 0 0 0 1px rgba(255,179,71,.4); }
.swatches.hair button { border-radius: 50%; }
.cosmetic-note { font: 500 9px/1.4 var(--font); color: var(--dim); letter-spacing: .5px; border-left: 2px solid var(--cyan); padding-left: 8px; }

/* Arsenal */
.arsenal-body { padding: 14px 20px 18px; overflow: auto; }
.arsenal-tabs { display: flex; flex-wrap: wrap; gap: 4px; margin-bottom: 12px; }
.arsenal-tabs button { padding: 5px 9px; border: 1px solid var(--line); font: 700 7.5px/1 var(--font); letter-spacing: 1px; color: var(--dim); }
.arsenal-tabs button.active { border-color: var(--orange2); color: var(--orange2); background: rgba(255,122,26,.08); }
.arsenal-list { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
.arsenal-card { display: grid; grid-template-columns: 100px 1fr; gap: 10px; padding: 9px; border: 1px solid var(--line); background: rgba(255,255,255,.02); }
.arsenal-art { height: 58px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 60%, rgba(255,122,26,.13), transparent 70%); border: 1px solid rgba(255,255,255,.05); color: var(--orange2); }
.arsenal-art svg { width: 86px; height: 34px; fill: none; stroke: currentColor; stroke-width: 1.2; }
.arsenal-info b { display: block; font: 600 16px/1 var(--display); letter-spacing: 1px; }
.arsenal-info .cat { font: 700 6.5px/1 var(--font); letter-spacing: 1.2px; color: var(--dim); }
.arsenal-bars { display: flex; flex-direction: column; gap: 3px; margin-top: 5px; }
.arsenal-bars div { display: flex; align-items: center; gap: 5px; }
.arsenal-bars span { width: 38px; font: 600 6px/1 var(--font); letter-spacing: .7px; color: var(--dim); }
.arsenal-bars i { flex: 1; height: 2px; background: rgba(255,255,255,.08); }
.arsenal-bars i b { display: block; height: 100%; background: var(--orange); }
.arsenal-desc { grid-column: 1 / -1; font: 500 8.5px/1.3 var(--font); color: var(--muted); }

/* Help */
.help-body { padding: 16px 20px; overflow: auto; }
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px 26px; }
.help-grid h3 { color: var(--orange2); margin-bottom: 5px; }
.help-grid p { margin: 0; font: 500 10.5px/1.45 var(--font); color: var(--muted); }

/* Pause */
.panel-pause { width: min(420px, 90vw); }
.pause-body { display: flex; flex-direction: column; gap: 7px; padding: 16px 20px 18px; }

/* Result */
.panel-result { width: min(700px, 92vw); overflow: hidden; }
.result-visual { height: 110px; background: radial-gradient(ellipse at 50% 120%, rgba(255,122,26,.4), transparent 65%), linear-gradient(180deg, rgba(255,179,71,.1), transparent); position: relative; }
.result-visual::after { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 30px, rgba(255,179,71,.05) 30px 31px); }
.result-content { padding: 4px 26px 22px; text-align: center; }
.result-content > span { font: 700 9px/1 var(--font); letter-spacing: 3px; color: var(--orange2); }
.result-content h2 { margin: 3px 0; font: 600 54px/.9 var(--display); letter-spacing: 4px; background: linear-gradient(180deg, #fff, var(--orange2)); -webkit-background-clip: text; background-clip: text; color: transparent; }
.result-content p { margin: 0 0 16px; font: 500 12px/1.3 var(--font); color: var(--muted); }
.result-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; background: var(--line); border: 1px solid var(--line); margin-bottom: 16px; }
.result-stats div { padding: 10px; background: #081620; }
.result-stats b { display: block; font: 600 26px/.9 var(--display); color: var(--ink); }
.result-stats span { font: 700 6.5px/1 var(--font); letter-spacing: 1.2px; color: var(--dim); }
.result-actions { display: flex; gap: 6px; }
.result-actions .wide-btn { flex: 1; text-align: center; }
.panel-result.defeat h2 { background: linear-gradient(180deg, #fff, #ff5a5a); -webkit-background-clip: text; background-clip: text; }
.panel-result.defeat .result-visual { background: radial-gradient(ellipse at 50% 120%, rgba(255,50,50,.3), transparent 65%), linear-gradient(180deg, rgba(255,80,80,.08), transparent); }

/* Matchmaking */
.panel-matchmaking { width: min(460px, 90vw); text-align: center; padding: 20px; }
.mm-head span { font: 700 8px/1 var(--font); letter-spacing: 2.4px; color: var(--cyan); }
.mm-head h2 { margin: 2px 0 12px; font: 600 30px/.9 var(--display); letter-spacing: 2px; }
.mm-radar { position: relative; width: 120px; height: 120px; margin: 0 auto 12px; border: 1px solid rgba(99,220,255,.3); border-radius: 50%; display: flex; flex-direction: column; align-items: center; justify-content: center; background: radial-gradient(circle, rgba(99,220,255,.08), transparent 70%); }
.mm-radar i { position: absolute; inset: 0; border: 1px solid rgba(99,220,255,.12); border-radius: 50%; animation: radar 2s linear infinite; }
.mm-radar i:nth-child(2) { animation-delay: .65s; } .mm-radar i:nth-child(3) { animation-delay: 1.3s; }
.mm-radar b { font: 600 38px/.9 var(--display); color: var(--cyan); }
.mm-radar span { font: 700 6px/1 var(--font); letter-spacing: 1px; color: var(--dim); }
.mm-status { font: 700 8px/1 var(--font); letter-spacing: 1.4px; color: var(--muted); margin-bottom: 8px; }
.mm-bar { height: 3px; background: rgba(255,255,255,.1); margin-bottom: 10px; }
.mm-bar i { display: block; height: 100%; width: 0; background: var(--cyan); transition: width .3s; }
.mm-note { font: 500 9px/1.4 var(--font); color: var(--dim); margin-bottom: 14px; }
.mm-actions { display: flex; flex-direction: column; gap: 6px; }

/* Layout */
.panel-layout { width: min(480px, 90vw); }
.layout-body { padding: 18px 20px; }
.layout-body p { margin: 0 0 12px; font: 500 11px/1.4 var(--font); color: var(--muted); }
.layout-demo { height: 160px; border: 1px dashed var(--line2); display: grid; place-items: center; background: radial-gradient(circle, rgba(99,220,255,.05), transparent 70%); margin-bottom: 14px; }
.demo-note { font: 700 8px/1 var(--font); letter-spacing: 2px; color: var(--cyan); }
.layout-actions { display: flex; gap: 6px; }
.layout-actions .wide-btn { flex: 1; text-align: center; }

/* Toasts */
.toast-root { position: absolute; left: 50%; bottom: calc(150px + var(--safe-b)); transform: translateX(-50%); z-index: 70; display: flex; flex-direction: column; align-items: center; gap: 5px; pointer-events: none; }
.toast { padding: 6px 13px; border: 1px solid var(--line2); background: rgba(4,12,18,.88); font: 700 9px/1 var(--font); letter-spacing: 1.2px; color: var(--ink); animation: toastIn .2s ease; clip-path: polygon(5px 0, 100% 0, calc(100% - 5px) 100%, 0 100%); }
.toast.good { border-color: rgba(84,230,165,.4); color: var(--green); }
.toast.warn { border-color: rgba(255,75,75,.4); color: #ff9c9c; }
.toast.loot { border-color: rgba(255,179,71,.45); color: var(--orange2); }

/* Fatal / rotate */
.fatal-error { position: absolute; inset: 0; z-index: 100; display: flex; flex-direction: column; align-items: center; justify-content: center; background: #04080d; text-align: center; }
.fatal-error b { font: 600 34px/1 var(--display); letter-spacing: 3px; color: var(--red); }
.fatal-error p { font: 500 13px/1.5 var(--font); color: var(--muted); }
.rotate-hint { position: absolute; inset: 0; z-index: 90; display: flex; flex-direction: column; align-items: center; justify-content: center; background: rgba(3,8,13,.94); text-align: center; }
.rotate-hint span { font-size: 42px; color: var(--orange2); animation: rotateHint 2s ease-in-out infinite; }
.rotate-hint b { font: 600 26px/1 var(--display); letter-spacing: 3px; margin-top: 8px; }
.rotate-hint p { font: 500 12px/1.4 var(--font); color: var(--muted); }

/* ══════════════════ ANIMATIONS ══════════════════ */
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes emblemPulse { 0%,100% { filter: drop-shadow(0 0 18px rgba(255,122,26,.35)); } 50% { filter: drop-shadow(0 0 34px rgba(255,122,26,.7)); } }
@keyframes scan { to { background-position: 0 100%; } }
@keyframes shine { 0%, 55% { transform: translateX(-130%); } 80%, 100% { transform: translateX(130%); } }
@keyframes feedIn { from { opacity: 0; transform: translateX(18px); } }
@keyframes panelIn { from { opacity: 0; transform: translate(-50%, -48%) scale(.985); } }
@keyframes bannerIn { from { opacity: 0; transform: translate(-50%, -50%) scale(.96); } }
@keyframes hitPulse { 0% { transform: scale(1.35); } 100% { transform: scale(1); } }
@keyframes lowHealth { 50% { filter: brightness(1.6); } }
@keyframes toastIn { from { opacity: 0; transform: translateY(7px); } }
@keyframes radar { from { transform: scale(.2); opacity: .8; } to { transform: scale(1); opacity: 0; } }
@keyframes rotateHint { 50% { transform: rotate(90deg); } }

/* ══════════════════ RESPONSIVE ══════════════════ */
@media (max-width: 1180px) {
  .menu-left { width: 430px; max-width: 52vw; }
  .menu-right { width: 290px; }
  .brand-type b { font-size: 26px; }
  .season-chip { display: none; }
  .minimap-wrap, .minimap-frame { width: 148px; }
  .minimap-frame { height: 148px; }
  .quick-actions { bottom: calc(170px + var(--safe-b)); }
}
@media (max-width: 900px) {
  .menu-screen { padding: calc(12px + var(--safe-t)) calc(14px + var(--safe-r)) calc(10px + var(--safe-b)) calc(14px + var(--safe-l)); }
  .menu-top { min-height: 48px; }
  .brand-mark { width: 38px; height: 38px; }
  .brand-type b { font-size: 22px; letter-spacing: 1.5px; }
  .brand-type em { font-size: 6.5px; letter-spacing: 3.5px; }
  .profile-chip { min-width: 0; padding: 4px; gap: 7px; }
  .profile-meta { display: none; }
  .avatar { width: 36px; height: 36px; font-size: 20px; }
  .icon-btn { width: 28px; height: 28px; }
  .menu-main { flex-direction: column; align-items: stretch; justify-content: flex-end; gap: 8px; padding-bottom: 4px; }
  .menu-left { width: 100%; max-width: none; gap: 8px; }
  .menu-right { display: none; }
  .mode-grid { grid-template-columns: repeat(4, 1fr); gap: 4px; }
  .mode-card { min-height: 58px; padding: 6px; }
  .mode-icon { width: 18px; height: 18px; }
  .mode-card b { font-size: 12px; letter-spacing: .8px; }
  .mode-card em { font-size: 6px; letter-spacing: .5px; }
