    timePlayed: 0,
    outfit: { skin: 'standard', primary: '#2f6f8f', hair: 'short', hairColor: '#22201f' },
    unlockedSkins: ['standard'],
    settings: { ...defaultSettings },
    createdAt: Date.now(),
  }
}

export function loadProfile() {
  let raw = null
  try { raw = JSON.parse(localStorage.getItem(KEY) || 'null') } catch { raw = null }
  const base = defaultProfile()
  if (!raw || typeof raw !== 'object') return base
  const p = {
    ...base, ...raw,
    outfit: { ...base.outfit, ...(raw.outfit || {}) },
    settings: { ...base.settings, ...(raw.settings || {}) },
    unlockedSkins: Array.isArray(raw.unlockedSkins) ? raw.unlockedSkins : base.unlockedSkins,
  }
  // Cosmetic unlocks are always re-derived from level so old saves stay valid.
  for (const skin of SKINS) if (p.level >= skin.level && !p.unlockedSkins.includes(skin.id)) p.unlockedSkins.push(skin.id)
  return p
}

export function saveProfile(profile) {
  try { localStorage.setItem(KEY, JSON.stringify(profile)) } catch { /* private mode */ }
}

export function resetProfile() {
  try { localStorage.removeItem(KEY) } catch { /* ignore */ }
  return defaultProfile()
}

export function addXP(profile, amount) {
  profile.xp += amount
  profile.xpTotal += amount
  const unlocked = []
  let levels = 0
  while (profile.xp >= xpForNext(profile.level)) {
    profile.xp -= xpForNext(profile.level)
    profile.level++
    levels++
    for (const skin of SKINS) {
      if (profile.level >= skin.level && !profile.unlockedSkins.includes(skin.id)) {
        profile.unlockedSkins.push(skin.id)
        unlocked.push(skin)
      }
    }
  }
  return { levels, unlocked }
}

export function recordMatch(profile, { placement, kills, damage, victory, time }) {
  profile.matches++
  profile.kills += kills
  profile.damage += damage
  profile.deaths += victory ? 0 : 1
  profile.timePlayed += time
  if (victory) profile.wins++
  if (!profile.bestPlace || placement < profile.bestPlace) profile.bestPlace = placement
  const placementBonus = victory ? 0 : Math.max(0, 30 - placement) * 8
  const xp = Math.round(70 + kills * 45 + damage * 0.32 + (victory ? 520 : 0) + placementBonus)
  const levelResult = addXP(profile, xp)
  saveProfile(profile)
  return { xp, ...levelResult }
}

export function skinById(id) {
  return SKINS.find(s => s.id === id) || SKINS[0]
}

export function currentOutfit(profile) {
  const skin = skinById(profile.outfit.skin)
  return {
    ...skin,
    primary: profile.outfit.primary || skin.primary,
    hair: profile.outfit.hair || 'short',
    hairColor: profile.outfit.hairColor || skin.hair,
    skinColor: skin.skin,
  }
}

import { clamp } from './utils.js'

export class AudioEngine {
  constructor(profile) {
    this.profile = profile
    this.ctx = null
    this.master = null
    this.sfx = null
    this.ambient = null
    this.ambientGain = null
    this.stepTimer = 0
    this.lastShot = 0
    this.enabled = true
  }

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    this.ctx = new AC()
    this.master = this.ctx.createGain()
    this.sfx = this.ctx.createGain()
    this.master.gain.value = clamp((this.profile?.settings?.volume ?? 80) / 100, 0, 1)
    this.sfx.gain.value = clamp((this.profile?.settings?.sfx ?? 100) / 100, 0, 1)
    this.sfx.connect(this.master)
    this.master.connect(this.ctx.destination)
    this.noise = this._makeNoise(2)
    this._startAmbient()
    if (this.ctx.state === 'suspended') this.ctx.resume()
  }

  setVolumes(volume, sfx) {
    if (this.master) this.master.gain.value = clamp(volume / 100, 0, 1)
    if (this.sfx) this.sfx.gain.value = clamp(sfx / 100, 0, 1)
  }

  _makeNoise(seconds = 1) {
    const len = Math.floor(this.ctx.sampleRate * seconds)
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1
    return buffer
  }

  _startAmbient() {
    if (!this.ctx || this.ambient) return
    const src = this.ctx.createBufferSource()
    src.buffer = this.noise
    src.loop = true
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 380
    filter.Q.value = 0.6
    const gain = this.ctx.createGain()
    gain.gain.value = 0.018
    src.connect(filter).connect(gain).connect(this.master)
    src.start()
    this.ambient = src
    this.ambientGain = gain
  }

  setAmbient(active) {
    if (!this.ambientGain) return
    const t = this.ctx.currentTime
    this.ambientGain.gain.cancelScheduledValues(t)
    this.ambientGain.gain.linearRampToValueAtTime(active ? 0.018 : 0.004, t + 0.6)
  }

  _noiseBurst({ duration = 0.15, gain = 0.2, freq = 1200, q = 1, type = 'lowpass', delay = 0, rate = 1 }) {
    if (!this.ctx) return
    const t = this.ctx.currentTime + delay
    const src = this.ctx.createBufferSource()
    src.buffer = this.noise
    src.playbackRate.value = rate
    const filter = this.ctx.createBiquadFilter()
    filter.type = type
    filter.frequency.setValueAtTime(freq, t)
    filter.frequency.exponentialRampToValueAtTime(Math.max(80, freq * 0.3), t + duration)
    filter.Q.value = q
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(gain, t)
    g.gain.exponentialRampToValueAtTime(0.0008, t + duration)
    src.connect(filter).connect(g).connect(this.sfx)
    src.start(t, Math.random() * 1.5)
    src.stop(t + duration + 0.02)
  }

  _tone({ freq = 440, end = 80, duration = 0.2, gain = 0.15, type = 'sine', delay = 0 }) {
    if (!this.ctx) return
    const t = this.ctx.currentTime + delay
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, end), t + duration)
    g.gain.setValueAtTime(gain, t)
    g.gain.exponentialRampToValueAtTime(0.0008, t + duration)
    osc.connect(g).connect(this.sfx)
    osc.start(t)
    osc.stop(t + duration + 0.02)
  }

  ui() { this._tone({ freq: 620, end: 900, duration: 0.05, gain: 0.05, type: 'square' }) }

  gunshot(category = 'ar', volume = 1) {
    if (!this.ctx) return
    const now = performance.now()
    if (now - this.lastShot < 24) return
    this.lastShot = now
    const v = clamp(volume, 0.08, 1)
    if (category === 'sniper') {
      this._noiseBurst({ duration: 0.45, gain: 0.42 * v, freq: 2600, q: 0.7 })
      this._tone({ freq: 140, end: 38, duration: 0.38, gain: 0.35 * v, type: 'sine' })
      this._noiseBurst({ duration: 0.7, gain: 0.08 * v, freq: 700, q: 0.4, delay: 0.05 })
    } else if (category === 'shotgun') {
      this._noiseBurst({ duration: 0.34, gain: 0.38 * v, freq: 1500, q: 0.5 })
      this._tone({ freq: 110, end: 34, duration: 0.3, gain: 0.28 * v })
    } else if (category === 'smg') {
      this._noiseBurst({ duration: 0.1, gain: 0.16 * v, freq: 2200, q: 0.8 })
      this._tone({ freq: 190, end: 70, duration: 0.07, gain: 0.1 * v, type: 'square' })
    } else if (category === 'pistol') {
      this._noiseBurst({ duration: 0.14, gain: 0.2 * v, freq: 1900, q: 0.8 })
      this._tone({ freq: 210, end: 60, duration: 0.1, gain: 0.13 * v })
    } else if (category === 'lmg') {
      this._noiseBurst({ duration: 0.16, gain: 0.24 * v, freq: 1500, q: 0.6 })
      this._tone({ freq: 120, end: 45, duration: 0.14, gain: 0.18 * v })
    } else {
      this._noiseBurst({ duration: 0.18, gain: 0.26 * v, freq: 1900, q: 0.7 })
      this._tone({ freq: 150, end: 48, duration: 0.13, gain: 0.15 * v })
    }
  }

  dryFire() { this._tone({ freq: 300, end: 120, duration: 0.04, gain: 0.07, type: 'square' }) }

  reload() {
    this._tone({ freq: 420, end: 260, duration: 0.05, gain: 0.07, type: 'square' })
    this._tone({ freq: 240, end: 180, duration: 0.05, gain: 0.06, type: 'square', delay: 0.16 })
    this._tone({ freq: 520, end: 300, duration: 0.06, gain: 0.08, type: 'square', delay: 0.42 })
  }

  hit(headshot = false) {
    if (headshot) {
      this._tone({ freq: 1500, end: 900, duration: 0.12, gain: 0.14, type: 'triangle' })
      this._tone({ freq: 2200, end: 1400, duration: 0.1, gain: 0.08, type: 'sine', delay: 0.03 })
    } else {
      this._tone({ freq: 780, end: 500, duration: 0.07, gain: 0.1, type: 'triangle' })
    }
  }

  kill() {
    this._tone({ freq: 880, end: 1320, duration: 0.12, gain: 0.12, type: 'triangle' })
    this._tone({ freq: 1320, end: 1760, duration: 0.14, gain: 0.1, type: 'triangle', delay: 0.09 })
  }

  damage() {
    this._noiseBurst({ duration: 0.22, gain: 0.18, freq: 500, q: 0.4 })
    this._tone({ freq: 90, end: 45, duration: 0.25, gain: 0.2 })
  }

  explosion() {
    this._noiseBurst({ duration: 0.9, gain: 0.5, freq: 900, q: 0.3 })
    this._tone({ freq: 75, end: 24, duration: 0.7, gain: 0.45 })
    this._noiseBurst({ duration: 1.2, gain: 0.12, freq: 300, q: 0.4, delay: 0.08 })
  }

  pickup(rarity = 'common') {
    const base = rarity === 'legendary' ? 660 : rarity === 'epic' ? 560 : rarity === 'rare' ? 500 : 430
    this._tone({ freq: base, end: base * 1.35, duration: 0.07, gain: 0.08, type: 'triangle' })
    this._tone({ freq: base * 1.35, end: base * 1.7, duration: 0.09, gain: 0.06, type: 'triangle', delay: 0.05 })
  }

  heal() {
    this._tone({ freq: 300, end: 700, duration: 0.35, gain: 0.07, type: 'sine' })
    this._tone({ freq: 450, end: 900, duration: 0.4, gain: 0.05, type: 'sine', delay: 0.12 })
  }

  footstep(surface = 'grass') {
    const now = performance.now()
    if (now - this.stepTimer < 260) return
    this.stepTimer = now
    const freq = surface === 'metal' ? 900 : surface === 'water' ? 500 : 320
    this._noiseBurst({ duration: 0.055, gain: 0.035, freq, q: 0.8 })
  }

  throwGrenade() {
    this._noiseBurst({ duration: 0.12, gain: 0.08, freq: 700, q: 0.6 })
  }

  zoneWarning() {
    this._tone({ freq: 420, end: 420, duration: 0.18, gain: 0.07, type: 'square' })
    this._tone({ freq: 520, end: 520, duration: 0.18, gain: 0.06, type: 'square', delay: 0.24 })
  }

  victory() {
    const notes = [523, 659, 784, 1046, 1318]
    notes.forEach((f, i) => this._tone({ freq: f, end: f * 1.01, duration: 0.5, gain: 0.11, type: 'triangle', delay: i * 0.12 }))
  }

  defeat() {
    const notes = [392, 330, 262, 196]
    notes.forEach((f, i) => this._tone({ freq: f, end: f * 0.98, duration: 0.55, gain: 0.09, type: 'sine', delay: i * 0.16 }))
  }

  levelUp() {
    const notes = [660, 880, 1100, 1320]
    notes.forEach((f, i) => this._tone({ freq: f, end: f, duration: 0.22, gain: 0.09, type: 'triangle', delay: i * 0.09 }))
  }
}

import { clamp } from './utils.js'

const KEY_MAP = {
  KeyW: 'forward', ArrowUp: 'forward',
  KeyS: 'back', ArrowDown: 'back',
  KeyA: 'left', ArrowLeft: 'left',
  KeyD: 'right', ArrowRight: 'right',
  ShiftLeft: 'sprint', ShiftRight: 'sprint',
}

const PRESS_MAP = {
  Space: 'jump',
  KeyC: 'crouch',
  ControlLeft: 'crouch',
  KeyR: 'reload',
  KeyE: 'interact',
  KeyF: 'interact',
  KeyQ: 'swap',
  Digit1: 'weapon1',
  Digit2: 'weapon2',
  Digit3: 'weapon3',
  KeyG: 'grenade',
  KeyH: 'med',
  Tab: 'inventory',
  KeyM: 'map',
  Escape: 'pause',
  KeyV: 'vehicle',
}

export class InputManager {
  constructor(canvas, profile) {
    this.canvas = canvas
    this.profile = profile
    this.keys = new Set()
    this.down = new Set()
    this.pressed = new Set()
    this.released = new Set()
    this.look = { x: 0, y: 0 }
    this.move = { x: 0, y: 0 }
    this.joystick = { x: 0, y: 0 }
    this.joystickPointer = null
    this.lookPointer = null
    this.lastLook = { x: 0, y: 0 }
    this.touchMode = window.matchMedia('(pointer: coarse)').matches || window.innerWidth < 900
    this.blocked = false
    this.playing = false
    this.pointerLocked = false
    this.enabled = true
    this._bind()
    this.applyLayout(profile?.settings?.touchLayout || {})
  }

  get sensitivity() { return clamp((this.profile?.settings?.sensitivity ?? 100) / 100, 0.2, 2) }

  _bind() {
    window.addEventListener('keydown', e => {
      if (e.code === 'Tab' || e.code === 'Space') e.preventDefault()
      if (this.blocked && e.code !== 'Escape') return
      const move = KEY_MAP[e.code]
      if (move) { this.keys.add(move); this._updateMove(); return }
      const press = PRESS_MAP[e.code]
      if (press) {
        if (e.repeat) return
        this.press(press)
        if (press === 'pause') e.preventDefault()
      }
      if (e.code === 'KeyP') this.press('pause')
    }, { passive: false })
    window.addEventListener('keyup', e => {
      const move = KEY_MAP[e.code]
      if (move) { this.keys.delete(move); this._updateMove() }
      const press = PRESS_MAP[e.code]
      if (press) this.release(press)
    })
    window.addEventListener('blur', () => { this.keys.clear(); this.down.clear(); this._updateMove(); this._resetJoystick() })

    // Desktop pointer lock + mouse look.
    this.canvas.addEventListener('mousedown', e => {
      if (this.touchMode || !this.playing || this.blocked) return
      if (e.button === 0) this.press('fire')
      if (e.button === 2) this.press('aim')
      if (document.pointerLockElement !== this.canvas) this.canvas.requestPointerLock?.()
    })
    window.addEventListener('mouseup', e => {
      if (e.button === 0) this.release('fire')
      if (e.button === 2) this.release('aim')
    })
    document.addEventListener('mousemove', e => {
      if (document.pointerLockElement === this.canvas && this.playing && !this.blocked) {
        this.look.x += e.movementX * 0.0024 * this.sensitivity
        this.look.y += e.movementY * 0.0024 * this.sensitivity
      }
    })
    document.addEventListener('pointerlockchange', () => {
      this.pointerLocked = document.pointerLockElement === this.canvas
    })
    this.canvas.addEventListener('contextmenu', e => e.preventDefault())
    this.canvas.addEventListener('wheel', e => {
      if (!this.playing || this.blocked) return
      this.press('swap')
      e.preventDefault()
    }, { passive: false })

    // Touch look anywhere on the canvas (controls capture their own pointers).
    this.canvas.addEventListener('pointerdown', e => {
      if (e.pointerType === 'mouse' && !this.touchMode) return
      if (!this.playing || this.blocked) return
      if (this.lookPointer !== null) return
      this.lookPointer = e.pointerId
      this.lastLook.x = e.clientX
      this.lastLook.y = e.clientY
      this.canvas.setPointerCapture?.(e.pointerId)
    })
    this.canvas.addEventListener('pointermove', e => {
      if (e.pointerId !== this.lookPointer) return
      const dx = e.clientX - this.lastLook.x
      const dy = e.clientY - this.lastLook.y
      this.lastLook.x = e.clientX
      this.lastLook.y = e.clientY
      this.look.x += dx * 0.0042 * this.sensitivity
      this.look.y += dy * 0.0042 * this.sensitivity
    })
    const endLook = e => {
      if (e.pointerId === this.lookPointer) {
        this.lookPointer = null
        try { this.canvas.releasePointerCapture?.(e.pointerId) } catch { /* ignore */ }
      }
    }
    this.canvas.addEventListener('pointerup', endLook)
    this.canvas.addEventListener('pointercancel', endLook)
    this.canvas.addEventListener('lostpointercapture', endLook)

    this._bindJoystick()
    this._bindTouchButtons()
  }

  _bindJoystick() {
    this.joystickEl = document.getElementById('joystick')
    this.joystickKnob = document.getElementById('joystick-knob')
    if (!this.joystickEl) return
    const update = (e) => {
      if (e.pointerId !== this.joystickPointer) return
      const rect = this.joystickEl.getBoundingClientRect()
      const cx = rect.left + rect.width / 2
      const cy = rect.top + rect.height / 2
      const max = rect.width * 0.34
      let dx = e.clientX - cx
      let dy = e.clientY - cy
      const len = Math.hypot(dx, dy)
      if (len > max) { dx = dx / len * max; dy = dy / len * max }
      const nx = dx / max, ny = dy / max
      const dead = 0.12
      const mag = Math.hypot(nx, ny)
      if (mag < dead) { this.joystick.x = 0; this.joystick.y = 0 }
      else {
        const scale = (mag - dead) / (1 - dead) / mag
        this.joystick.x = nx * scale
        this.joystick.y = ny * scale
      }
      if (this.joystickKnob) this.joystickKnob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`
      this._updateMove()
    }
    this.joystickEl.addEventListener('pointerdown', e => {
      if (!this.playing || this.blocked) return
      this.joystickPointer = e.pointerId
      this.joystickEl.setPointerCapture?.(e.pointerId)
      update(e)
      e.preventDefault()
    })
    const end = e => {
      if (e.pointerId !== this.joystickPointer) return
      this._resetJoystick()
    }
    this.joystickEl.addEventListener('pointermove', update)
    this.joystickEl.addEventListener('pointerup', end)
    this.joystickEl.addEventListener('pointercancel', end)
    this.joystickEl.addEventListener('lostpointercapture', end)
  }

  _resetJoystick() {
    this.joystickPointer = null
    this.joystick.x = 0
    this.joystick.y = 0
    if (this.joystickKnob) this.joystickKnob.style.transform = 'translate(-50%, -50%)'
    this._updateMove()
  }

  _bindTouchButtons() {
    this.buttons = [...document.querySelectorAll('#touch-controls [data-action]')].filter(el => el.dataset.action !== 'joystick')
    for (const el of this.buttons) {
      const action = el.dataset.action
      el.addEventListener('pointerdown', e => {
        if (!this.playing || this.blocked) return
        el.setPointerCapture?.(e.pointerId)
        el.classList.add('active')
        this.press(action)
        e.preventDefault()
        e.stopPropagation()
      })
      const up = e => {
        el.classList.remove('active')
        this.release(action)
        try { el.releasePointerCapture?.(e.pointerId) } catch { /* ignore */ }
      }
      el.addEventListener('pointerup', up)
      el.addEventListener('pointercancel', up)
      el.addEventListener('lostpointercapture', up)
    }
  }

  _updateMove() {
    let x = 0, y = 0
    if (this.keys.has('right')) x += 1
    if (this.keys.has('left')) x -= 1
    if (this.keys.has('back')) y += 1
    if (this.keys.has('forward')) y -= 1
    const kLen = Math.hypot(x, y)
    if (kLen > 1) { x /= kLen; y /= kLen }
    const jx = this.joystick.x, jy = this.joystick.y
    x = clamp(x + jx, -1, 1)
    y = clamp(y + jy, -1, 1)
    const len = Math.hypot(x, y)
    if (len > 1) { x /= len; y /= len }
    this.move.x = x
    this.move.y = y
  }

  press(action) {
    if (!action) return
    if (!this.down.has(action)) this.pressed.add(action)
    this.down.add(action)
  }

  release(action) {
    if (!action) return
    this.down.delete(action)
    this.released.add(action)
  }

  isDown(action) { return this.down.has(action) || this.keys.has(action) }
  wasPressed(action) { return this.pressed.has(action) }
  wasReleased(action) { return this.released.has(action) }

  consumeLook() {
    const out = { x: this.look.x, y: this.look.y }
    this.look.x = 0
    this.look.y = 0
    return out
  }

  setBlocked(blocked) {
    this.blocked = blocked
    if (blocked) {
      this.down.clear()
      this.keys.clear()
      this._updateMove()
      if (document.pointerLockElement) document.exitPointerLock?.()
    }
  }

  setPlaying(playing) {
    this.playing = playing
    if (!playing) {
      this.down.clear()
      this.keys.clear()
      this._resetJoystick()
      if (document.pointerLockElement) document.exitPointerLock?.()
    }
  }

  endFrame() {
    this.pressed.clear()
    this.released.clear()
  }

  // ── touch layout ─────────────────────────────────────────────
  getButtonElements() {
    const els = [...document.querySelectorAll('#touch-controls [data-action]')]
    return els.map(el => ({ el, action: el.dataset.action }))
  }

  captureLayout() {
    const out = {}
    const w = window.innerWidth, h = window.innerHeight
    for (const { el, action } of this.getButtonElements()) {
      const r = el.getBoundingClientRect()
      if (!r.width) continue
      out[action] = { x: +((r.left + r.width / 2) / w * 100).toFixed(2), y: +((r.top + r.height / 2) / h * 100).toFixed(2) }
    }
    return out
  }

  applyLayout(layout) {
    if (!layout) return
    for (const { el, action } of this.getButtonElements()) {
      const pos = layout[action]
      if (!pos) { el.style.left = ''; el.style.top = ''; el.style.right = ''; el.style.bottom = ''; continue }
      el.style.left = pos.x + '%'
      el.style.top = pos.y + '%'
      el.style.right = 'auto'
      el.style.bottom = 'auto'
      el.style.transform = 'translate(-50%, -50%)'
    }
  }

  applyButtonScale(scale) {
    const s = clamp(scale / 100, 0.6, 1.5)
    document.documentElement.style.setProperty('--btn-scale', s)
    const layer = document.getElementById('touch-controls')
    if (layer) layer.style.zoom = s === 1 ? '' : String(s)
  }
}

import * as THREE from 'three'
import { clamp, lerp, smoothstep, fbm, mulberry32, randRange, makeCanvas } from '../core/utils.js'

export const WATER_LEVEL = 0
export const WORLD_SIZE = 1500
export const WORLD_HALF = WORLD_SIZE / 2
export const PLAY_RADIUS = 622

export const PAD_DEFS = [
  { id: 'city', name: 'NEON CITY', x: -300, z: -245, r: 112, h: 13, type: 'city', map: '#63dcff', label: 'URBAN' },
  { id: 'base', name: 'IRONHOLD BASE', x: 275, z: -292, r: 100, h: 11, type: 'military', map: '#ff8a2b', label: 'MILITARY' },
  { id: 'airport', name: 'KESTREL AIRPORT', x: 342, z: 238, r: 128, h: 8, type: 'airport', map: '#ffd166', label: 'AIRFIELD' },
  { id: 'harbor', name: 'DOCKSIDE HARBOR', x: -395, z: 300, r: 96, h: 4.5, type: 'harbor', map: '#54e6a5', label: 'HARBOR' },
  { id: 'village', name: 'OLD MILL VILLAGE', x: 0, z: 92, r: 86, h: 16, type: 'village', map: '#e8c79a', label: 'VILLAGE' },
  { id: 'foundry', name: 'FOUNDRY WORKS', x: 138, z: -42, r: 90, h: 12, type: 'industrial', map: '#ff7a1a', label: 'INDUSTRIAL' },
  { id: 'bunker', name: 'BUNKER 7', x: -82, z: -468, r: 56, h: 27, type: 'bunker', map: '#b78bff', label: 'BUNKER' },
  { id: 'ridge', name: 'WATCHTOWER RIDGE', x: 72, z: -390, r: 42, h: 34, type: 'ridge', map: '#9fdcff', label: 'RIDGE' },
  { id: 'beach', name: 'SUNSET BEACH', x: 432, z: 450, r: 62, h: 3, type: 'beach', map: '#ffd9a0', label: 'BEACH' },
  { id: 'lake', name: 'MIRROR LAKE', x: -122, z: 246, r: 56, h: 8, type: 'lake', map: '#63dcff', label: 'LAKE' },
  { id: 'aurora', name: 'MOUNT AURORA', x: 18, z: 408, r: 86, h: 66, type: 'mountain', map: '#eaf6ff', label: 'MOUNTAIN' },
]

const PAD_MAP = new Map(PAD_DEFS.map(p => [p.id, p]))

export function padById(id) { return PAD_MAP.get(id) }

export function getHeight(x, z, seed = 1337) {
  const d = Math.hypot(x, z)
  const land = smoothstep(705, 545, d)
  const n1 = fbm(x * 0.0032 + 11.3, z * 0.0032 - 7.1, 4, seed)
  const n2 = fbm(x * 0.0125, z * 0.0125, 3, seed + 17)
  let h = (3.2 + n1 * 29 + n2 * 6.5) * land - 8.5 * (1 - land)

  // Signature highlands and the northern ridge line.
  h += 54 * Math.exp(-(((x - 18) ** 2) + ((z - 408) ** 2)) / (2 * 108 * 108))
  h += 17 * Math.exp(-(((x + 382) ** 2) + ((z + 82) ** 2)) / (2 * 104 * 104))
  h += 11 * Math.exp(-(((x + 52) ** 2) + ((z - 44) ** 2)) / (2 * 168 * 168))
  h += 9 * Math.exp(-(((x - 72) ** 2) + ((z + 390) ** 2)) / (2 * 80 * 80))

  // Mirror Lake — a shallow inland basin with a road bridge.
  const lakeD = Math.hypot(x + 122, z - 246)
  h -= 15 * smoothstep(84, 22, lakeD)

  // Flatten landmark pads so buildings, roads and loot sit cleanly.
  for (const pad of PAD_DEFS) {
    if (pad.type === 'mountain' || pad.type === 'lake') continue
    const pd = Math.hypot(x - pad.x, z - pad.z)
    if (pd < pad.r + 55) {
      const t = smoothstep(pad.r + 52, pad.r, pd)
      h = lerp(h, pad.h, t)
    }
  }
  return h
}

export function isWater(x, z, seed = 1337) {
  return getHeight(x, z, seed) < WATER_LEVEL - 0.15
}

export function createSky(scene) {
  const sunDir = new THREE.Vector3(0.44, 0.58, 0.32).normalize()
  const skyGeo = new THREE.SphereGeometry(2700, 36, 20)
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      sunDir: { value: sunDir },
      zenith: { value: new THREE.Color(0x2b6f9f) },
      horizon: { value: new THREE.Color(0xc7dbe0) },
      sunColor: { value: new THREE.Color(0xffd9a0) },
    },
    vertexShader: `
      varying vec3 vWorld;
      void main() {
        vWorld = (modelMatrix * vec4(position, 1.0)).xyz;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      varying vec3 vWorld;
      uniform vec3 sunDir;
      uniform vec3 zenith;
      uniform vec3 horizon;
      uniform vec3 sunColor;
      void main() {
        vec3 dir = normalize(vWorld);
        float y = clamp(dir.y, 0.0, 1.0);
        vec3 col = mix(horizon, zenith, pow(y, 0.52));
        float sun = max(dot(dir, sunDir), 0.0);
        col += sunColor * pow(sun, 96.0) * 1.4;
        col += sunColor * pow(sun, 7.0) * 0.16;
        float haze = exp(-max(dir.y, 0.0) * 5.5);
        col = mix(col, horizon * 1.04, haze * 0.45);
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  })
  const sky = new THREE.Mesh(skyGeo, skyMat)
  sky.frustumCulled = false
  scene.add(sky)

  // Sun disc
  const sunCanvas = makeCanvas(256, 256)
  const sctx = sunCanvas.getContext('2d')
  const grd = sctx.createRadialGradient(128, 128, 4, 128, 128, 120)
  grd.addColorStop(0, 'rgba(255,252,235,1)')
  grd.addColorStop(0.12, 'rgba(255,228,170,.95)')
  grd.addColorStop(0.38, 'rgba(255,180,90,.28)')
  grd.addColorStop(1, 'rgba(255,150,60,0)')
  sctx.fillStyle = grd
  sctx.fillRect(0, 0, 256, 256)
  const sunTex = new THREE.CanvasTexture(sunCanvas)
  sunTex.colorSpace = THREE.SRGBColorSpace
  const sunSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: sunTex, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, fog: false }))
  sunSprite.position.copy(sunDir.clone().multiplyScalar(2200))
  sunSprite.scale.set(430, 430, 1)
  scene.add(sunSprite)

  // Soft cloud banks
  const clouds = []
  const cloudCanvas = makeCanvas(512, 256)
  const cctx = cloudCanvas.getContext('2d')
  for (let i = 0; i < 22; i++) {
    const x = 60 + Math.random() * 392
    const y = 90 + Math.random() * 90
    const r = 30 + Math.random() * 72
    const cg = cctx.createRadialGradient(x, y, 0, x, y, r)
    cg.addColorStop(0, 'rgba(255,255,255,.8)')
    cg.addColorStop(0.55, 'rgba(244,250,255,.42)')
    cg.addColorStop(1, 'rgba(230,244,255,0)')
    cctx.fillStyle = cg
    cctx.beginPath(); cctx.arc(x, y, r, 0, Math.PI * 2); cctx.fill()
  }
  const cloudTex = new THREE.CanvasTexture(cloudCanvas)
  cloudTex.colorSpace = THREE.SRGBColorSpace
  for (let i = 0; i < 9; i++) {
    const mat = new THREE.SpriteMaterial({ map: cloudTex, transparent: true, opacity: 0.5 + Math.random() * 0.22, depthWrite: false, fog: false, color: 0xe8f4ff })
    const s = new THREE.Sprite(mat)
    const a = (i / 9) * Math.PI * 2 + Math.random() * 0.5
    const r = 700 + Math.random() * 1100
    s.position.set(Math.cos(a) * r, 220 + Math.random() * 170, Math.sin(a) * r)
    s.scale.set(430 + Math.random() * 380, 150 + Math.random() * 130, 1)
    s.userData.speed = 0.7 + Math.random() * 0.9
    scene.add(s)
    clouds.push(s)
  }

  const hemi = new THREE.HemisphereLight(0xcfeaff, 0x5f5744, 1.25)
  scene.add(hemi)
  const sun = new THREE.DirectionalLight(0xffe0b6, 2.35)
  sun.position.copy(sunDir.clone().multiplyScalar(360))
  sun.castShadow = true
  sun.shadow.mapSize.set(2048, 2048)
  sun.shadow.camera.left = -210
  sun.shadow.camera.right = 210
  sun.shadow.camera.top = 210
  sun.shadow.camera.bottom = -210
  sun.shadow.camera.near = 10
  sun.shadow.camera.far = 800
  sun.shadow.bias = -0.0006
  sun.shadow.normalBias = 0.04
  scene.add(sun)
  scene.add(sun.target)
  const ambient = new THREE.AmbientLight(0x8fb6ca, 0.28)
  scene.add(ambient)

  scene.fog = new THREE.Fog(0xb8d2da, 520, 1560)
  return { sky, sun, sunDir, clouds, hemi, ambient, sunSprite }
}

export function createTerrain(scene, seed = 1337) {
  const segments = 220
  const geo = new THREE.PlaneGeometry(WORLD_SIZE, WORLD_SIZE, segments, segments)
  geo.rotateX(-Math.PI / 2)
  const pos = geo.attributes.position
  const colors = new Float32Array(pos.count * 3)
  const c = new THREE.Color()
  const sand = new THREE.Color(0xc8b78d)
  const wetSand = new THREE.Color(0x9f9270)
  const grass = new THREE.Color(0x63834a)
  const grassDark = new THREE.Color(0x435f38)
  const rock = new THREE.Color(0x77746a)
  const rockDark = new THREE.Color(0x55544e)
  const snow = new THREE.Color(0xe4ecef)
  const rng = mulberry32(seed)
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i)
    const h = getHeight(x, z, seed)
    pos.setY(i, h)
    const hx = getHeight(x + 2.5, z, seed) - getHeight(x - 2.5, z, seed)
    const hz = getHeight(x, z + 2.5, seed) - getHeight(x, z - 2.5, seed)
    const slope = Math.min(1, Math.hypot(hx, hz) / 4.6)
    const n = fbm(x * 0.06, z * 0.06, 2, seed + 31)
    if (h < 0.6) c.copy(wetSand).lerp(sand, clamp((h + 4) / 5, 0, 1))
    else if (h < 3.6) c.copy(sand).lerp(grass, smoothstep(2.0, 3.8, h) * 0.55)
    else if (h < 34) c.copy(grass).lerp(grassDark, n * 0.55)
    else if (h < 48) c.copy(grass).lerp(rock, smoothstep(34, 48, h))
    else if (h < 62) c.copy(rock).lerp(rockDark, n * 0.5)
    else c.copy(rock).lerp(snow, smoothstep(62, 72, h))
    if (slope > 0.5) c.lerp(rock, (slope - 0.5) * 1.1)
    c.offsetHSL(0, 0, (n - 0.5) * 0.07)
    colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3))
  geo.computeVertexNormals()

  // Fine ground detail so close-up terrain never looks flat.
  const detailCanvas = makeCanvas(256, 256)
  const dctx = detailCanvas.getContext('2d')
  const img = dctx.createImageData(256, 256)
  const drng = mulberry32(seed + 99)
  for (let i = 0; i < img.data.length; i += 4) {
    const v = 205 + drng() * 50
    img.data[i] = v; img.data[i + 1] = v; img.data[i + 2] = v; img.data[i + 3] = 255
  }
  dctx.putImageData(img, 0, 0)
  const detail = new THREE.CanvasTexture(detailCanvas)
  detail.wrapS = detail.wrapT = THREE.RepeatWrapping
  detail.repeat.set(160, 160)
  detail.anisotropy = 8

  const mat = new THREE.MeshStandardMaterial({
    vertexColors: true,
    map: detail,
    roughness: 0.97,
    metalness: 0,
  })
  const mesh = new THREE.Mesh(geo, mat)
  mesh.receiveShadow = true
  mesh.castShadow = false
  scene.add(mesh)
  return { mesh, geo, detail }
}

export function createWater(scene) {
  const geo = new THREE.PlaneGeometry(4300, 4300, 170, 170)
  geo.rotateX(-Math.PI / 2)
  const mat = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: true,
    uniforms: {
      uTime: { value: 0 },
      uDeep: { value: new THREE.Color(0x0c4a61) },
      uShallow: { value: new THREE.Color(0x2aa2b8) },
      uSky: { value: new THREE.Color(0xb8d2da) },
      uSun: { value: new THREE.Vector3(0.44, 0.58, 0.32).normalize() },
    },
    vertexShader: `
      uniform float uTime;
      varying vec3 vWorld;
      varying vec3 vNormalW;
      varying vec2 vUv;
      void main() {
        vec3 p = position;
        float w1 = sin(p.x * 0.045 + uTime * 0.9) * 0.28;
        float w2 = cos(p.z * 0.061 - uTime * 1.15) * 0.22;
        float w3 = sin((p.x + p.z) * 0.021 + uTime * 0.55) * 0.3;
        p.y += w1 + w2 + w3;
        vWorld = (modelMatrix * vec4(p, 1.0)).xyz;
        float dx = cos(p.x * 0.045 + uTime * 0.9) * 0.045 * 0.28 + cos((p.x + p.z) * 0.021 + uTime * 0.55) * 0.021 * 0.3;
        float dz = -sin(p.z * 0.061 - uTime * 1.15) * 0.061 * 0.22 + cos((p.x + p.z) * 0.021 + uTime * 0.55) * 0.021 * 0.3;
        vNormalW = normalize(vec3(-dx, 1.0, -dz));
        vUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
      }
    `,
    fragmentShader: `
      uniform float uTime;
      uniform vec3 uDeep;
      uniform vec3 uShallow;
      uniform vec3 uSky;
      uniform vec3 uSun;
      varying vec3 vWorld;
      varying vec3 vNormalW;
      varying vec2 vUv;
      void main() {
        vec3 viewDir = normalize(cameraPosition - vWorld);
        vec3 n = normalize(vNormalW);
        float fres = pow(1.0 - max(dot(n, viewDir), 0.0), 2.4);
        float ripple = sin(vWorld.x * 0.15 + uTime * 1.8) * sin(vWorld.z * 0.13 - uTime * 1.4) * 0.5 + 0.5;
        vec3 col = mix(uDeep, uShallow, 0.28 + fres * 0.55 + ripple * 0.1);
        col = mix(col, uSky, fres * 0.45);
        vec3 h = normalize(viewDir + uSun);
        float spec = pow(max(dot(n, h), 0.0), 110.0);
        col += vec3(1.0, 0.86, 0.62) * spec * 1.2;
        float glint = pow(max(dot(n, uSun), 0.0), 20.0) * 0.15;
        col += vec3(1.0, 0.8, 0.5) * glint;
        gl_FragColor = vec4(col, 0.93);
      }
    `,
  })
  const mesh = new THREE.Mesh(geo, mat)
  mesh.position.y = WATER_LEVEL
  mesh.receiveShadow = false
  mesh.renderOrder = 1
  scene.add(mesh)
  return { mesh, mat }
}

export function makeAsphaltTexture(seed = 5, base = '#30363b') {
  const canvas = makeCanvas(256, 256)
  const ctx = canvas.getContext('2d')
  ctx.fillStyle = base
  ctx.fillRect(0, 0, 256, 256)
  const rng = mulberry32(seed)
  for (let i = 0; i < 2400; i++) {
    const v = Math.floor(35 + rng() * 45)
    ctx.fillStyle = `rgba(${v},${v + 2},${v + 3},${0.08 + rng() * 0.2})`
    ctx.fillRect(rng() * 256, rng() * 256, 1 + rng() * 2, 1 + rng() * 2)
  }
  for (let i = 0; i < 8; i++) {
    ctx.strokeStyle = `rgba(15,18,20,${0.1 + rng() * 0.2})`
    ctx.lineWidth = 1
    ctx.beginPath()
    let x = rng() * 256, y = rng() * 256
    ctx.moveTo(x, y)
    for (let j = 0; j < 4; j++) { x += (rng() - 0.5) * 40; y += (rng() - 0.5) * 40; ctx.lineTo(x, y) }
    ctx.stroke()
  }
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.anisotropy = 8
  return tex
}

export function makeConcreteTexture(seed = 7, base = '#8a8c83') {
  const canvas = makeCanvas(256, 256)
  const ctx = canvas.getContext('2d')
  ctx.fillStyle = base
  ctx.fillRect(0, 0, 256, 256)
  const rng = mulberry32(seed)
  for (let i = 0; i < 1800; i++) {
    const v = Math.floor(80 + rng() * 80)
    ctx.fillStyle = `rgba(${v},${v},${v - 4},${0.06 + rng() * 0.16})`
    ctx.fillRect(rng() * 256, rng() * 256, 1 + rng() * 3, 1 + rng() * 2)
  }
  ctx.strokeStyle = 'rgba(50,52,50,.24)'
  ctx.lineWidth = 1
  for (let i = 1; i < 4; i++) {
    ctx.beginPath(); ctx.moveTo(i * 64, 0); ctx.lineTo(i * 64, 256); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(0, i * 64); ctx.lineTo(256, i * 64); ctx.stroke()
  }
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.anisotropy = 8
  return tex
}

export function makeWindowTexture(seed = 1, warm = false) {
  const canvas = makeCanvas(256, 512)
  const ctx = canvas.getContext('2d')
  const rng = mulberry32(seed)
  const base = warm ? '#3c3a36' : '#293641'
  ctx.fillStyle = base
  ctx.fillRect(0, 0, 256, 512)
  // Facade panel seams
  ctx.strokeStyle = 'rgba(0,0,0,.28)'
  ctx.lineWidth = 2
  for (let y = 0; y < 512; y += 64) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(256, y); ctx.stroke() }
  for (let x = 0; x < 256; x += 64) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, 512); ctx.stroke() }
  for (let y = 10; y < 500; y += 32) {
    for (let x = 10; x < 246; x += 32) {
      const lit = rng() > (warm ? 0.62 : 0.54)
      if (lit) {
        const v = 180 + rng() * 70
        ctx.fillStyle = warm ? `rgba(255,${Math.floor(v * 0.78)},${Math.floor(v * 0.42)},${0.55 + rng() * 0.4})` : `rgba(${Math.floor(v * 0.55)},${Math.floor(v * 0.8)},${v},${0.5 + rng() * 0.45})`
      } else {
        ctx.fillStyle = `rgba(10,18,24,${0.45 + rng() * 0.35})`
      }
      ctx.fillRect(x, y, 18, 16)
      ctx.fillStyle = 'rgba(255,255,255,.05)'
      ctx.fillRect(x + 2, y + 2, 14, 3)
    }
  }
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.anisotropy = 8
  return tex
}

export function makeTextTexture(lines, opts = {}) {
  const {
    width = 512, height = 256, bg = 'rgba(4,10,16,.86)', fg = '#eaf6ff',
    accent = '#ff8a2b', font = '700 46px sans-serif', sub = '', subFont = '600 22px sans-serif',
    border = true,
  } = opts
  const canvas = makeCanvas(width, height)
  const ctx = canvas.getContext('2d')
  ctx.fillStyle = bg
  ctx.fillRect(0, 0, width, height)
  if (border) {
    ctx.strokeStyle = accent
    ctx.lineWidth = 6
    ctx.strokeRect(8, 8, width - 16, height - 16)
    ctx.fillStyle = accent
    ctx.fillRect(24, height - 34, 80, 4)
  }
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  ctx.fillStyle = fg
  ctx.font = font
  const arr = Array.isArray(lines) ? lines : [lines]
  const lineH = height / (arr.length + (sub ? 1.4 : 0.7))
  arr.forEach((line, i) => ctx.fillText(line, width / 2, height * 0.34 + i * lineH))
  if (sub) {
    ctx.fillStyle = accent
    ctx.font = subFont
    ctx.fillText(sub, width / 2, height * 0.72)
  }
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.anisotropy = 8
  return tex
}

export function createRoad(points, width, material, seed = 1, yOffset = 0.12) {
  const positions = []
  const uvs = []
  const indices = []
  let dist = 0
  for (let i = 0; i < points.length; i++) {
    const [x, z] = points[i]
    const prev = points[Math.max(0, i - 1)]
    const next = points[Math.min(points.length - 1, i + 1)]
    let dx = next[0] - prev[0], dz = next[1] - prev[1]
    const len = Math.hypot(dx, dz) || 1
    dx /= len; dz /= len
    const px = -dz, pz = dx
    const half = width / 2
    const lx = x + px * half, lz = z + pz * half
    const rx = x - px * half, rz = z - pz * half
    const ly = getHeight(lx, lz, seed) + yOffset
    const ry = getHeight(rx, rz, seed) + yOffset
    positions.push(lx, ly, lz, rx, ry, rz)
    if (i > 0) {
      const p = points[i - 1]
      dist += Math.hypot(x - p[0], z - p[1])
    }
    uvs.push(0, dist / 8, 1, dist / 8)
  }
  for (let i = 0; i < points.length - 1; i++) {
    const a = i * 2
    indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2)
  }
  const geo = new THREE.BufferGeometry()
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2))
  geo.setIndex(indices)
  geo.computeVertexNormals()
  const mesh = new THREE.Mesh(geo, material)
  mesh.receiveShadow = true
  return mesh
}

export function scatterPoints(rng, count, centerX, centerZ, radius, minDist = 4) {
  const out = []
  let guard = 0
  while (out.length < count && guard++ < count * 40) {
    const a = rng() * Math.PI * 2
    const r = Math.sqrt(rng()) * radius
    const x = centerX + Math.cos(a) * r
    const z = centerZ + Math.sin(a) * r
    if (out.some(p => Math.hypot(p[0] - x, p[1] - z) < minDist)) continue
    out.push([x, z])
  }
  return out
}

export function createLootSpots(seed = 1337) {
  const rng = mulberry32(seed + 404)
  const spots = []
  for (const pad of PAD_DEFS) {
    if (pad.type === 'mountain') continue
    const count = pad.type === 'lake' ? 3 : pad.type === 'beach' ? 6 : 14
    for (let i = 0; i < count; i++) {
      const a = rng() * Math.PI * 2
      const r = Math.sqrt(rng()) * pad.r * 0.78
      const x = pad.x + Math.cos(a) * r
      const z = pad.z + Math.sin(a) * r
      spots.push({ x, z, y: getHeight(x, z, seed), poi: pad.id, hidden: rng() > 0.78 })
    }
  }
  // Hidden wilderness caches and bunker-style caches.
  for (let i = 0; i < 46; i++) {
    const a = rng() * Math.PI * 2
    const r = 120 + rng() * 400
    const x = Math.cos(a) * r
    const z = Math.sin(a) * r
    if (isWater(x, z, seed)) continue
    spots.push({ x, z, y: getHeight(x, z, seed), poi: 'wild', hidden: true })
  }
  return spots
}

import * as THREE from 'three'
import {
  makeTextTexture, makeWindowTexture, makeAsphaltTexture, makeConcreteTexture,
  createRoad, getHeight, isWater, PAD_DEFS, WATER_LEVEL,
} from './terrain.js'
import { mulberry32, randRange, randInt, pick, smoothstep, clamp } from '../core/utils.js'

// ─────────────────────────────────────────────────────────────────────────────
//  Shared architectural helpers
// ─────────────────────────────────────────────────────────────────────────────

function gableGeometry(w, d, h) {
  const shape = new THREE.Shape()
  shape.moveTo(-w / 2, 0)
  shape.lineTo(w / 2, 0)
  shape.lineTo(0, h)
  shape.closePath()
  const geo = new THREE.ExtrudeGeometry(shape, { depth: d, bevelEnabled: false, curveSegments: 2 })
  geo.translate(0, 0, -d / 2)
  return geo
}

function archGeometry(radius, length) {
  const shape = new THREE.Shape()
  shape.moveTo(-radius, 0)
  shape.absarc(0, 0, radius, Math.PI, 0, true)
  shape.lineTo(-radius, 0)
  const geo = new THREE.ExtrudeGeometry(shape, { depth: length, bevelEnabled: false, curveSegments: 14 })
  geo.translate(0, 0, -length / 2)
  return geo
}

function makeCorrugatedTexture(base = '#59636b', seed = 2) {
  const c = document.createElement('canvas')
  c.width = 128; c.height = 128
  const ctx = c.getContext('2d')
  ctx.fillStyle = base
  ctx.fillRect(0, 0, 128, 128)
  for (let x = 0; x < 128; x += 8) {
    ctx.fillStyle = x % 16 === 0 ? 'rgba(255,255,255,.09)' : 'rgba(0,0,0,.13)'
    ctx.fillRect(x, 0, 3, 128)
  }
  const rng = mulberry32(seed)
  for (let i = 0; i < 70; i++) {
    ctx.fillStyle = `rgba(30,20,15,${0.05 + rng() * 0.12})`
    ctx.fillRect(rng() * 128, rng() * 128, 2 + rng() * 9, 1 + rng() * 3)
  }
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  return tex
}

function makeCrateTexture(seed = 3) {
  const c = document.createElement('canvas')
  c.width = 128; c.height = 128
  const ctx = c.getContext('2d')
  ctx.fillStyle = '#7d603c'
  ctx.fillRect(0, 0, 128, 128)
  ctx.strokeStyle = 'rgba(40,26,14,.5)'
  ctx.lineWidth = 4
  ctx.strokeRect(4, 4, 120, 120)
  ctx.beginPath(); ctx.moveTo(8, 8); ctx.lineTo(120, 120); ctx.moveTo(120, 8); ctx.lineTo(8, 120); ctx.stroke()
  ctx.strokeStyle = 'rgba(255,220,160,.12)'
  ctx.lineWidth = 2
  for (let y = 20; y < 128; y += 24) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(128, y); ctx.stroke() }
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  return tex
}

function addWindowTower(world, x, z, w, d, h, baseY, style = 0, opts = {}) {
  const tex = world.windowTextures[style % world.windowTextures.length].clone()
  tex.needsUpdate = true
  tex.repeat.set(Math.max(2, w / 6.5), Math.max(3, h / 7.5))
  const side = new THREE.MeshStandardMaterial({
    map: tex,
    emissiveMap: tex,
    emissive: 0xffffff,
    emissiveIntensity: 0.5,
    roughness: 0.74,
    metalness: 0.18,
  })
  const roof = world.mat.roofGray
  const mesh = new THREE.Mesh(world.unitBox, [side, side, roof, roof, side, side])
  mesh.position.set(x, baseY + h / 2, z)
  mesh.scale.set(w, h, d)
  mesh.castShadow = true
  mesh.receiveShadow = true
  world.scene.add(mesh)
  world.addCollider(x, z, w, d, baseY, baseY + h)
  // Rooftop slab and mechanical penthouse
  world.addBox(x, baseY + h, z, w + 1.2, 0.7, d + 1.2, world.mat.concreteDark, { collide: false })
  const mw = Math.min(w * 0.38, 12), md = Math.min(d * 0.38, 12)
  world.addBox(x + w * 0.12, baseY + h + 0.7, z - d * 0.1, mw, 3.4, md, world.mat.metal, { collide: false })
  world.addBox(x - w * 0.28, baseY + h + 0.7, z + d * 0.2, 2.4, 1.2, 2.4, world.mat.darkMetal, { collide: false })
  // Antenna
  if (h > 70) {
    world.addCylinder(x - w * 0.2, baseY + h + 4, z - d * 0.2, 0.12, 8, world.mat.metal, { collide: false })
    const light = world.addBox(x - w * 0.2, baseY + h + 11.8, z - d * 0.2, 0.5, 0.5, 0.5, world.mat.redGlow, { collide: false })
    light.material = world.mat.redGlow
  }
  // Facade bands and balconies
  const bandY = baseY + h * 0.55
  world.addBox(x, bandY, z, w + 0.8, 0.35, d + 0.8, world.mat.darkMetal, { collide: false })
  if (opts.neon) {
    const texSign = makeTextTexture(opts.neon, { width: 512, height: 160, bg: 'rgba(3,8,14,.9)', fg: '#eaf6ff', accent: opts.neonColor || '#ff8a2b', font: '700 54px sans-serif' })
    const signMat = new THREE.MeshBasicMaterial({ map: texSign, transparent: true, side: THREE.DoubleSide })
    const sign = new THREE.Mesh(new THREE.PlaneGeometry(w * 0.55, 4.4), signMat)
    sign.position.set(x, baseY + h * 0.72, z + d / 2 + 0.06)
    world.scene.add(sign)
  }
  // Entrance canopy
  world.addBox(x, baseY + 2.5, z + d / 2 + 1.5, 5.5, 0.4, 3.2, world.mat.darkMetal, { collide: false })
  return mesh
}

function addHouse(world, x, z, baseY, rot = 0, scale = 1, color = 0xd4c3a4) {
  const w = 11 * scale, d = 9 * scale, h = 4.2 * scale
  const wall = new THREE.MeshStandardMaterial({ color, roughness: 0.9, metalness: 0.02 })
  world.addBox(x, baseY, z, w, h, d, wall, { rotY: rot, collide: true })
  const roofGeo = gableGeometry(w + 1.2, d + 1.4, 3.6 * scale)
  const roof = new THREE.Mesh(roofGeo, world.mat.roofRed)
  roof.position.set(x, baseY + h, z)
  roof.rotation.y = rot
  roof.castShadow = true
  world.scene.add(roof)
  // Chimney
  world.addBox(x + w * 0.26, baseY + h + 2.2, z - d * 0.2, 0.8, 3.2, 0.8, world.mat.brick, { collide: false })
  // Door and windows
  const doorMat = world.mat.woodDark
  world.addBox(x + Math.sin(rot) * (d / 2 + 0.04), baseY, z + Math.cos(rot) * (d / 2 + 0.04), 1.4, 2.4, 0.12, doorMat, { rotY: rot, collide: false })
  const winMat = world.mat.windowWarm
  for (const side of [-1, 1]) {
    const wx = x + Math.cos(rot) * side * w * 0.27 + Math.sin(rot) * (d / 2 + 0.04)
    const wz = z - Math.sin(rot) * side * w * 0.27 + Math.cos(rot) * (d / 2 + 0.04)
    world.addBox(wx, baseY + 2.1, wz, 1.6, 1.3, 0.1, winMat, { rotY: rot, collide: false })
  }
  // Side windows
  for (const side of [-1, 1]) {
    const wx = x + Math.cos(rot) * (w / 2 + 0.04) * side
    const wz = z - Math.sin(rot) * (w / 2 + 0.04) * side
    world.addBox(wx, baseY + 2.2, wz, 0.1, 1.2, 1.6, winMat, { rotY: rot, collide: false })
  }
  return { x, z, w, d, h }
}

function addBarracks(world, x, z, baseY, rot = 0, w = 42, d = 13) {
  const wall = world.mat.concrete
  world.addBox(x, baseY, z, w, 5.2, d, wall, { rotY: rot, collide: true })
  world.addBox(x, baseY + 5.2, z, w + 1, 0.5, d + 1, world.mat.roofGray, { rotY: rot, collide: false })
  for (let i = -2; i <= 2; i++) {
    const wx = x + Math.cos(rot) * i * 7
    const wz = z - Math.sin(rot) * i * 7
    world.addBox(wx, baseY + 2.2, wz + Math.cos(rot) * (d / 2 + 0.04), 1.7, 1.2, 0.12, world.mat.windowWarm, { rotY: rot, collide: false })
  }
  world.addBox(x, baseY + 3.6, z + Math.cos(rot) * (d / 2 + 0.5), 3, 0.3, 1.2, world.mat.darkMetal, { rotY: rot, collide: false })
}

function addWatchtower(world, x, z, baseY, height = 9, rot = 0) {
  const legMat = world.mat.darkMetal
  const half = 2.1
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    world.addBox(x + sx * half, baseY, z + sz * half, 0.4, height, 0.4, legMat, { rotY: rot, collide: false })
  }
  world.addBox(x, baseY + height, z, 6.2, 0.45, 6.2, world.mat.metal, { rotY: rot, collide: false })
  world.addBox(x, baseY + height + 3.2, z, 7.2, 0.4, 7.2, world.mat.roofGray, { rotY: rot, collide: false })
  // Railings
  for (const s of [-1, 1]) {
    world.addBox(x + s * 3, baseY + height + 1.3, z, 0.12, 1.3, 6, world.mat.darkMetal, { rotY: rot, collide: false })
    world.addBox(x, baseY + height + 1.3, z + s * 3, 6, 1.3, 0.12, world.mat.darkMetal, { rotY: rot, collide: false })
  }
  // Ladder on the east face
  const lx = x + 3.55, lz = z
  for (const s of [-0.5, 0.5]) world.addBox(lx, baseY, lz + s, 0.1, height + 0.4, 0.1, world.mat.metal, { collide: false })
  for (let i = 0; i < height; i += 0.55) world.addBox(lx, baseY + i, lz, 0.12, 0.08, 1.05, world.mat.metal, { collide: false })
  world.addWalkable(x, z, 6.2, 6.2, baseY + height + 0.45)
  world.addLadder(lx, lz, baseY, baseY + height + 0.45)
  return { top: baseY + height }
}

function addContainer(world, x, z, baseY, color = '#3f6f78', rot = 0, stack = 1) {
  const tex = world.containerTextures[color] || world.containerTextures['#3f6f78']
  const mat = new THREE.MeshStandardMaterial({ map: tex, color: 0xffffff, roughness: 0.72, metalness: 0.35 })
  for (let i = 0; i < stack; i++) {
    world.addBox(x, baseY + i * 2.65, z, 6.1, 2.55, 2.45, mat, { rotY: rot, collide: true })
  }
}

function addCrate(world, x, z, baseY, scale = 1, rot = 0) {
  world.addBox(x, baseY, z, 1.6 * scale, 1.5 * scale, 1.6 * scale, world.mat.crate, { rotY: rot, collide: true })
}

function addSandbagWall(world, x, z, baseY, length = 6, rot = 0) {
  const n = Math.max(2, Math.floor(length / 0.9))
  for (let i = 0; i < n; i++) {
    const ox = (i - (n - 1) / 2) * 0.9
    const px = x + Math.cos(rot) * ox
    const pz = z - Math.sin(rot) * ox
    const bag = world.addBox(px, baseY + (i % 2) * 0.35, pz, 0.95, 0.42, 0.55, world.mat.sandbag, { rotY: rot, collide: false })
    bag.rotation.z = (i % 2 ? 1 : -1) * 0.04
  }
  world.addCollider(x, z, Math.abs(Math.cos(rot)) * length + Math.abs(Math.sin(rot)) * 0.6, Math.abs(Math.sin(rot)) * length + Math.abs(Math.cos(rot)) * 0.6, baseY, baseY + 1)
}

function addStreetlight(world, x, z, baseY) {
  world.addCylinder(x, baseY, z, 0.09, 5.5, world.mat.darkMetal, { collide: false })
  const lamp = world.addBox(x, baseY + 5.5, z, 1.3, 0.16, 0.34, world.mat.orangeGlow, { collide: false })
  lamp.material = world.mat.orangeGlow
  world.addBox(x, baseY + 5.62, z, 1.7, 0.1, 0.5, world.mat.darkMetal, { collide: false })
}

function addNeonBillboard(world, x, y, z, rot, text, sub, color = '#ff8a2b') {
  const tex = makeTextTexture(text, { width: 512, height: 240, bg: 'rgba(4,9,14,.92)', fg: '#eaf6ff', accent: color, font: '700 62px sans-serif', sub, subFont: '600 24px sans-serif' })
  const mat = new THREE.MeshBasicMaterial({ map: tex, transparent: true, side: THREE.DoubleSide })
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(11, 5.2), mat)
  mesh.position.set(x, y, z)
  mesh.rotation.y = rot
  world.scene.add(mesh)
  // Frame
  const frame = world.addBox(x, y - 2.9, z, 11.6, 0.3, 0.4, world.mat.darkMetal, { rotY: rot, collide: false })
  return mesh
}

function addRadarDish(world, x, z, baseY) {
  world.addCylinder(x, baseY, z, 0.5, 4.5, world.mat.metal, { collide: false })
  const dish = new THREE.Mesh(new THREE.CircleGeometry(3.4, 24, 0, Math.PI * 2), world.mat.radar)
  dish.position.set(x, baseY + 5.2, z)
  dish.rotation.set(-0.55, 0.3, 0.1)
  dish.material.side = THREE.DoubleSide
  world.scene.add(dish)
  const strut = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 3.6, 6), world.mat.metal)
  strut.position.set(x, baseY + 4.8, z)
  strut.rotation.z = 0.5
  world.scene.add(strut)
  world.animated.push((t) => { dish.rotation.y = 0.3 + Math.sin(t * 0.28) * 0.8 })
}

function addHelipad(world, x, z, baseY, r = 12) {
  const tex = makeTextTexture('H', { width: 256, height: 256, bg: 'rgba(24,29,30,1)', fg: '#e9d8a6', accent: '#e9d8a6', font: '700 150px sans-serif', border: true })
  const mat = new THREE.MeshStandardMaterial({ map: tex, roughness: 0.9 })
  const disc = new THREE.Mesh(new THREE.CircleGeometry(r, 32), mat)
  disc.rotation.x = -Math.PI / 2
  disc.position.set(x, baseY + 0.12, z)
  world.scene.add(disc)
  const ring = new THREE.Mesh(new THREE.RingGeometry(r - 0.7, r, 40), world.mat.yellowGlow)
  ring.rotation.x = -Math.PI / 2
  ring.position.set(x, baseY + 0.13, z)
  world.scene.add(ring)
}

function addStaticPlane(world, x, z, baseY, rot = 0) {
  const bodyMat = world.mat.aircraft
  const body = new THREE.Mesh(new THREE.CylinderGeometry(2.2, 1.8, 32, 12), bodyMat)
  body.rotation.z = Math.PI / 2
  body.rotation.y = rot
  body.position.set(x, baseY + 4.2, z)
  body.castShadow = true
  world.scene.add(body)
  const nose = new THREE.Mesh(new THREE.ConeGeometry(1.8, 4, 12), bodyMat)
  nose.rotation.z = -Math.PI / 2
  nose.rotation.y = rot
  nose.position.set(x + Math.cos(rot) * 17, baseY + 4.2, z - Math.sin(rot) * 17)
  world.scene.add(nose)
  world.addBox(x, baseY + 4, z, 36, 0.55, 7.5, bodyMat, { rotY: rot, collide: false })
  world.addBox(x - 12 * Math.cos(rot), baseY + 5.2, z + 12 * Math.sin(rot), 0.5, 5.5, 9, bodyMat, { rotY: rot, collide: false })
  world.addBox(x - 12 * Math.cos(rot), baseY + 7.5, z + 12 * Math.sin(rot), 0.5, 0.5, 4.5, bodyMat, { rotY: rot, collide: false })
  world.addCollider(x, z, Math.abs(Math.cos(rot)) * 34 + Math.abs(Math.sin(rot)) * 8, Math.abs(Math.sin(rot)) * 34 + Math.abs(Math.cos(rot)) * 8, baseY, baseY + 7)
}

function addHelicopter(world, x, z, baseY, rot = 0) {
  const mat = world.mat.aircraft
  const body = world.addBox(x, baseY + 1.4, z, 5.2, 2.2, 2.4, mat, { rotY: rot, collide: false })
  body.scale.set(5.2, 2.2, 2.4)
  world.addBox(x - 4.2 * Math.cos(rot), baseY + 1.9, z + 4.2 * Math.sin(rot), 6.5, 0.6, 0.7, mat, { rotY: rot, collide: false })
  world.addBox(x - 7.4 * Math.cos(rot), baseY + 3.1, z + 7.4 * Math.sin(rot), 0.4, 3, 2.6, mat, { rotY: rot, collide: false })
  world.addCylinder(x, baseY + 2.8, z, 0.22, 0.8, world.mat.darkMetal, { collide: false })
  const rotor = new THREE.Mesh(new THREE.BoxGeometry(10, 0.08, 0.35), world.mat.darkMetal)
  rotor.position.set(x, baseY + 3.35, z)
  rotor.rotation.y = rot
  world.scene.add(rotor)
  world.animated.push((t) => { rotor.rotation.y = rot + t * 18 })
  world.addBox(x + Math.cos(rot) * 1.2, baseY + 1.2, z - Math.sin(rot) * 1.2, 4.5, 0.12, 0.12, world.mat.darkMetal, { rotY: rot, collide: false })
  world.addBox(x, baseY + 0.5, z, 4.2, 0.12, 2.4, world.mat.darkMetal, { rotY: rot, collide: false })
}

