}

function mat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.82, metalness: 0.05, ...opts })
}

function box(parent, material, x, y, z, w, h, d) {
  const m = new THREE.Mesh(G.box, material)
