import * as THREE from 'three'
import { makeCanvas, clamp, randRange } from '../core/utils.js'

function glowTexture() {
  const c = makeCanvas(128, 128)
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64)
  g.addColorStop(0, 'rgba(255,255,255,1)')
  g.addColorStop(0.22, 'rgba(255,230,180,.9)')
  g.addColorStop(0.55, 'rgba(255,150,60,.35)')
  g.addColorStop(1, 'rgba(255,120,20,0)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, 128, 128)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

function smokeTexture() {
  const c = makeCanvas(128, 128)
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(64, 64, 4, 64, 64, 62)
  g.addColorStop(0, 'rgba(255,255,255,.85)')
  g.addColorStop(0.5, 'rgba(230,230,230,.35)')
  g.addColorStop(1, 'rgba(220,220,220,0)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, 128, 128)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

const numberCache = new Map()
function numberTexture(value, color) {
  const key = value + color
  if (numberCache.has(key)) return numberCache.get(key)
  const c = makeCanvas(192, 96)
  const ctx = c.getContext('2d')
  ctx.font = '700 64px Rajdhani, sans-serif'
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  ctx.lineWidth = 8
  ctx.strokeStyle = 'rgba(0,0,0,.65)'
  ctx.strokeText(value, 96, 50)
  ctx.fillStyle = color
  ctx.fillText(value, 96, 50)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  numberCache.set(key, t)
  return t
}

export class Effects {
  constructor(scene, quality = 'high') {
    this.scene = scene
    this.quality = quality
    this.glowTex = glowTexture()
    this.smokeTex = smokeTexture()
    this.active = []
    this.tracerGeo = new THREE.BoxGeometry(1, 1, 1)
    this.tracerMat = new THREE.MeshBasicMaterial({ color: 0xffe2a8, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, fog: false })
    this.ringGeo = new THREE.RingGeometry(0.9, 1, 40)
    this.pool = { tracer: [], flash: [], puff: [], ring: [], text: [] }
  }

  _take(kind, factory) {
    const list = this.pool[kind]
    const obj = list.pop()
    if (obj) { obj.visible = true; return obj }
    return factory()
  }

  _release(kind, obj) {
    obj.visible = false
    if (obj.parent) obj.parent.remove(obj)
    if (this.pool[kind].length < 90) this.pool[kind].push(obj)
  }

  tracer(from, to, color = 0xffe2a8) {
    const len = from.distanceTo(to)
    if (len < 0.2) return
    const mesh = this._take('tracer', () => {
      const m = new THREE.Mesh(this.tracerGeo, this.tracerMat.clone())
      m.frustumCulled = false
      return m
    })
    mesh.material.color.setHex(color)
    mesh.material.opacity = 0.85
    mesh.position.copy(from).add(to).multiplyScalar(0.5)
    mesh.scale.set(0.035, 0.035, len)
    mesh.lookAt(to)
    mesh.renderOrder = 3
    this.scene.add(mesh)
    this.active.push({ kind: 'tracer', obj: mesh, life: 0.055, max: 0.055 })
  }

  muzzle(pos, scale = 1) {
    const sprite = this._take('flash', () => {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, fog: false }))
      return s
    })
    sprite.position.copy(pos)
    sprite.scale.setScalar(0.85 * scale)
    sprite.material.opacity = 1
    sprite.material.color.setHex(0xffd9a0)
    this.scene.add(sprite)
    this.active.push({ kind: 'flash', obj: sprite, life: 0.06, max: 0.06, scale: scale })
  }

  impact(pos, normal = null, color = 0xffcf8a, count = 3) {
    for (let i = 0; i < count; i++) {
      const sprite = this._take('puff', () => new THREE.Sprite(new THREE.SpriteMaterial({ map: this.smokeTex, transparent: true, depthWrite: false, fog: false })))
      sprite.position.copy(pos)
      if (normal) sprite.position.addScaledVector(normal, 0.06)
      sprite.material.color.setHex(color)
      sprite.material.opacity = 0.85
      const size = randRange(Math.random, 0.16, 0.36)
      sprite.scale.setScalar(size)
      this.scene.add(sprite)
      this.active.push({
        kind: 'puff', obj: sprite, life: 0.42, max: 0.42,
        vel: new THREE.Vector3((Math.random() - 0.5) * 2.4, Math.random() * 2.2, (Math.random() - 0.5) * 2.4),
        grow: 1.6, base: size,
      })
    }
  }

  blood(pos) { this.impact(pos, null, 0xff5a5a, 4) }

  explosion(pos, scale = 1) {
    const flash = this._take('flash', () => new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, fog: false })))
    flash.position.copy(pos)
    flash.scale.setScalar(2.4 * scale)
    flash.material.opacity = 1
    flash.material.color.setHex(0xffb060)
    this.scene.add(flash)
    this.active.push({ kind: 'flash', obj: flash, life: 0.22, max: 0.22, scale: 2.4 * scale })

    for (let i = 0; i < (this.quality === 'low' ? 6 : 12); i++) {
      const sprite = this._take('puff', () => new THREE.Sprite(new THREE.SpriteMaterial({ map: this.smokeTex, transparent: true, depthWrite: false, fog: false })))
      sprite.position.copy(pos)
      sprite.material.color.setHex(i % 3 === 0 ? 0xff9a40 : 0x8a8580)
      sprite.material.opacity = 0.8
      const size = randRange(Math.random, 0.5, 1.2) * scale
      sprite.scale.setScalar(size)
      this.scene.add(sprite)
      this.active.push({
        kind: 'puff', obj: sprite, life: randRange(Math.random, 0.7, 1.3), max: 1.3,
        vel: new THREE.Vector3((Math.random() - 0.5) * 9, Math.random() * 7, (Math.random() - 0.5) * 9),
        grow: 4 * scale, base: size,
      })
    }
    const ring = this._take('ring', () => new THREE.Mesh(this.ringGeo, new THREE.MeshBasicMaterial({ color: 0xffa050, transparent: true, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending })))
    ring.position.copy(pos)
    ring.rotation.x = -Math.PI / 2
    ring.scale.setScalar(0.6)
    ring.material.opacity = 0.85
    this.scene.add(ring)
    this.active.push({ kind: 'ring', obj: ring, life: 0.5, max: 0.5, grow: 12 * scale })
  }

  damageNumber(pos, amount, color = '#ffe2a8') {
    const value = Math.max(1, Math.round(amount))
    const sprite = this._take('text', () => new THREE.Sprite(new THREE.SpriteMaterial({ transparent: true, depthWrite: false, depthTest: false, fog: false })))
    sprite.material.map = numberTexture(value, color)
    sprite.material.needsUpdate = true
    sprite.position.copy(pos)
    sprite.position.y += 0.35
    sprite.scale.set(1.1, 0.55, 1)
    sprite.material.opacity = 1
    sprite.renderOrder = 5
    this.scene.add(sprite)
    this.active.push({
      kind: 'text', obj: sprite, life: 0.75, max: 0.75,
      vel: new THREE.Vector3((Math.random() - 0.5) * 0.7, 2.1, (Math.random() - 0.5) * 0.7),
    })
  }

  pickup(pos, color = 0xffb347) {
    const ring = this._take('ring', () => new THREE.Mesh(this.ringGeo, new THREE.MeshBasicMaterial({ color: 0xffa050, transparent: true, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending })))
    ring.position.copy(pos)
    ring.rotation.x = -Math.PI / 2
    ring.scale.setScalar(0.35)
    ring.material.color.setHex(color)
    ring.material.opacity = 0.9
    this.scene.add(ring)
    this.active.push({ kind: 'ring', obj: ring, life: 0.42, max: 0.42, grow: 2.6 })
  }

  update(dt) {
    for (let i = this.active.length - 1; i >= 0; i--) {
      const e = this.active[i]
      e.life -= dt
      const t = clamp(e.life / e.max, 0, 1)
      if (e.kind === 'tracer') {
        e.obj.material.opacity = t * 0.9
      } else if (e.kind === 'flash') {
        e.obj.material.opacity = t
        const s = e.scale * (0.7 + (1 - t) * 0.6)
        e.obj.scale.setScalar(s)
      } else if (e.kind === 'puff') {
        e.obj.position.addScaledVector(e.vel, dt)
        e.vel.multiplyScalar(1 - dt * 3.2)
        e.obj.material.opacity = t * 0.75
        e.obj.scale.setScalar(e.base + (1 - t) * e.grow)
      } else if (e.kind === 'ring') {
        e.obj.scale.setScalar(0.4 + (1 - t) * e.grow)
        e.obj.material.opacity = t * 0.8
      } else if (e.kind === 'text') {
        e.obj.position.addScaledVector(e.vel, dt)
        e.vel.y -= dt * 1.8
        e.obj.material.opacity = t
      }
      if (e.life <= 0) {
        this._release(e.kind, e.obj)
        this.active.splice(i, 1)
      }
    }
  }

  clear() {
    for (const e of this.active) this._release(e.kind, e.obj)
    this.active.length = 0
  }
}

import * as THREE from 'three'
import { WEAPONS, SPAWN_WEAPONS, RARITY, weaponById, attachmentLabel } from './weapons.js'
import { mulberry32, pick, randInt, clamp } from '../core/utils.js'
import { PAD_DEFS } from '../world/terrain.js'

export const AMMO_TYPES = ['light', 'heavy', 'shells', 'sniper', 'pistol']
const AMMO_COLOR = { light: '#c8b48a', heavy: '#b9a06e', shells: '#c96b4a', sniper: '#d9c25a', pistol: '#a8b8c2' }
const TYPE_COLOR = {
  weapon: '#ffb347', ammo: '#c8b48a', armor: '#63dcff', helmet: '#8fb8ff',
  backpack: '#54e6a5', med: '#ff6b6b', grenade: '#9ad66b', attachment: '#b78bff',
}

export function lootLabel(data) {
  switch (data.type) {
    case 'weapon': {
      const w = weaponById(data.weapon)
      return w.name + (data.attachments?.length ? ' + ' + data.attachments.map(attachmentLabel).join(', ') : '')
    }
    case 'ammo': return `${data.ammo.toUpperCase()} AMMO ×${data.amount}`
    case 'armor': return `BODY ARMOR LV${data.level}`
    case 'helmet': return `HELMET LV${data.level}`
    case 'backpack': return `BACKPACK LV${data.level}`
    case 'med': return data.item === 'medkit' ? 'MEDKIT' : 'BANDAGE'
    case 'grenade': return `FRAG GRENADE ×${data.amount}`
    case 'attachment': return attachmentLabel(data.attachment)
    default: return 'SUPPLY'
  }
}

export function lootColor(data) {
  if (data.type === 'weapon') return RARITY[data.rarity || 'common'].color
  if (data.type === 'ammo') return AMMO_COLOR[data.ammo] || '#c8b48a'
  return TYPE_COLOR[data.type] || '#ffb347'
}

function rarityRoll(rng, bonus = 0) {
  const roll = rng() * 100 - bonus * 8
  if (roll < 8) return 'legendary'
  if (roll < 26) return 'epic'
  if (roll < 58) return 'rare'
  return 'common'
}

function randomAttachments(rng, rarity) {
  const pool = ['ext_mag', 'grip', 'suppressor', 'scope_2x', 'scope_4x']
  const out = []
  const n = rarity === 'legendary' ? 2 : rarity === 'epic' ? randInt(rng, 1, 2) : rarity === 'rare' ? (rng() > 0.6 ? 1 : 0) : 0
  while (out.length < n) {
    const a = pick(rng, pool)
    if (!out.includes(a)) out.push(a)
  }
  return out
}

export function makeLootData(rng, poi = 'wild') {
  const bonus = poi === 'bunker' || poi === 'base' ? 1.4 : poi === 'wild' ? 0.4 : 0
  const roll = rng() * 100
  if (roll < 36) {
    const rarity = rarityRoll(rng, bonus)
    let pool = SPAWN_WEAPONS.filter(w => w.rarity === rarity)
    if (!pool.length) pool = SPAWN_WEAPONS
    const weapon = pick(rng, pool)
    return { type: 'weapon', weapon: weapon.id, rarity: weapon.rarity, attachments: randomAttachments(rng, weapon.rarity) }
  }
  if (roll < 58) {
    const ammo = pick(rng, AMMO_TYPES)
    return { type: 'ammo', ammo, amount: ammo === 'sniper' ? randInt(rng, 5, 12) : ammo === 'shells' ? randInt(rng, 8, 20) : randInt(rng, 20, 45) }
  }
  if (roll < 69) return { type: 'armor', level: rng() > 0.82 ? 3 : rng() > 0.5 ? 2 : 1 }
  if (roll < 77) return { type: 'helmet', level: rng() > 0.85 ? 3 : rng() > 0.55 ? 2 : 1 }
  if (roll < 84) return { type: 'backpack', level: rng() > 0.85 ? 3 : rng() > 0.55 ? 2 : 1 }
  if (roll < 94) return { type: 'med', item: rng() > 0.55 ? 'medkit' : 'bandage' }
  if (roll < 98) return { type: 'grenade', amount: 1 }
  return { type: 'attachment', attachment: pick(rng, ['ext_mag', 'grip', 'suppressor', 'scope_2x', 'scope_4x']) }
}

export class LootManager {
  constructor(scene, world, seed = 1337) {
    this.scene = scene
    this.world = world
    this.seed = seed
    this.items = []
    this.capacity = 320
    this.nextId = 1
    this.time = 0
    this.dirty = true

    const boxGeo = new THREE.BoxGeometry(0.46, 0.46, 0.46)
    boxGeo.rotateY(Math.PI / 4)
    this.boxMesh = new THREE.InstancedMesh(boxGeo, new THREE.MeshStandardMaterial({
      roughness: 0.35, metalness: 0.55, emissive: 0x222222, emissiveIntensity: 0.6,
    }), this.capacity)
    this.boxMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
    this.boxMesh.frustumCulled = false
    this.boxMesh.count = 0
    this.scene.add(this.boxMesh)

    const beamGeo = new THREE.CylinderGeometry(0.035, 0.035, 2.6, 5, 1, true)
    beamGeo.translate(0, 1.3, 0)
    this.beamMesh = new THREE.InstancedMesh(beamGeo, new THREE.MeshBasicMaterial({
      transparent: true, opacity: 0.4, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, fog: false,
    }), this.capacity)
    this.beamMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
    this.beamMesh.frustumCulled = false
    this.beamMesh.count = 0
    this.scene.add(this.beamMesh)

    this.dummy = new THREE.Object3D()
    this.color = new THREE.Color()
  }

  spawnInitial() {
    const rng = mulberry32(this.seed + 991)
    const spots = this.world.lootSpots
    for (const spot of spots) {
      if (rng() > 0.72) continue
      const data = makeLootData(rng, spot.poi)
      const y = this.world.groundHeight(spot.x, spot.z) + 0.4
      this.add(data, spot.x, y, spot.z)
    }
    // Guaranteed weapon cluster around each major landmark.
    for (const pad of PAD_DEFS) {
      if (pad.type === 'mountain' || pad.type === 'lake') continue
      for (let i = 0; i < 2; i++) {
        const a = rng() * Math.PI * 2
        const r = 8 + rng() * pad.r * 0.35
        const x = pad.x + Math.cos(a) * r
        const z = pad.z + Math.sin(a) * r
        if (this.world.isWaterAt(x, z)) continue
        const weapon = pick(rng, SPAWN_WEAPONS)
        this.add({ type: 'weapon', weapon: weapon.id, rarity: weapon.rarity, attachments: randomAttachments(rng, weapon.rarity) }, x, this.world.groundHeight(x, z) + 0.4, z)
      }
    }
    this.rebuild()
  }

  reset() {
    this.items.length = 0
    this.nextId = 1
    this.spawnInitial()
  }

  add(data, x, y, z) {
    if (this.items.length >= this.capacity - 8) return null
    const item = { id: this.nextId++, data, x, y, z, active: true, phase: Math.random() * Math.PI * 2 }
    this.items.push(item)
    this.dirty = true
    return item
  }

  remove(item) {
    if (!item || !item.active) return
    item.active = false
    this.dirty = true
  }

  nearest(x, y, z, radius = 2.6) {
    let best = null, bestD = radius
    for (const item of this.items) {
      if (!item.active) continue
      const d = Math.hypot(item.x - x, item.y - y, item.z - z)
      if (d < bestD) { bestD = d; best = item }
    }
    return best
  }

  nearItems(x, y, z, radius = 3) {
    return this.items.filter(i => i.active && Math.hypot(i.x - x, i.y - y, i.z - z) < radius)
  }

  dropAt(x, y, z, data, spread = 0.6) {
    const a = Math.random() * Math.PI * 2
    const r = Math.random() * spread
    return this.add(data, x + Math.cos(a) * r, y + 0.35, z + Math.sin(a) * r)
  }

  update(dt) {
    this.time += dt
    if (this.dirty) this.rebuild()
    if (this.time % 0.05 > dt) return
    const dummy = this.dummy
    const beam = this.beamMesh
    const box = this.boxMesh
    let i = 0
    for (const item of this.items) {
      if (!item.active) continue
      const bob = Math.sin(this.time * 2 + item.phase) * 0.09
      const scale = item.data.type === 'weapon' ? 1.25 : item.data.type === 'armor' ? 1.05 : 0.8
      dummy.position.set(item.x, item.y + 0.45 + bob, item.z)
      dummy.rotation.set(0, this.time * 0.8 + item.phase, 0.35)
      dummy.scale.setScalar(scale)
      dummy.updateMatrix()
      box.setMatrixAt(i, dummy.matrix)
      dummy.position.set(item.x, item.y, item.z)
      dummy.rotation.set(0, 0, 0)
      dummy.scale.set(1, 1, 1)
      dummy.updateMatrix()
      beam.setMatrixAt(i, dummy.matrix)
      i++
      if (i >= this.capacity) break
    }
    box.count = i
    beam.count = i
    box.instanceMatrix.needsUpdate = true
    beam.instanceMatrix.needsUpdate = true
  }

  rebuild() {
    const dummy = this.dummy
    const color = this.color
    const box = this.boxMesh
    const beam = this.beamMesh
    let i = 0
    for (const item of this.items) {
      if (!item.active) continue
      color.set(lootColor(item.data))
      box.setColorAt(i, color)
      beam.setColorAt(i, color)
      dummy.position.set(item.x, item.y + 0.45, item.z)
      dummy.rotation.set(0, item.phase, 0.35)
      dummy.scale.setScalar(item.data.type === 'weapon' ? 1.25 : 0.85)
      dummy.updateMatrix()
      box.setMatrixAt(i, dummy.matrix)
      dummy.position.set(item.x, item.y, item.z)
      dummy.rotation.set(0, 0, 0)
      dummy.scale.set(1, 1, 1)
      dummy.updateMatrix()
      beam.setMatrixAt(i, dummy.matrix)
      i++
      if (i >= this.capacity) break
    }
    box.count = i
    beam.count = i
    box.instanceMatrix.needsUpdate = true
    beam.instanceMatrix.needsUpdate = true
    if (box.instanceColor) box.instanceColor.needsUpdate = true
    if (beam.instanceColor) beam.instanceColor.needsUpdate = true
    this.dirty = false
  }

  dispose() {
    this.scene.remove(this.boxMesh, this.beamMesh)
    this.boxMesh.geometry.dispose()
    this.boxMesh.material.dispose()
    this.beamMesh.geometry.dispose()
    this.beamMesh.material.dispose()
  }
}

import * as THREE from 'three'
import { clamp, lerp, mulberry32, formatTime } from '../core/utils.js'
import { PLAY_RADIUS, getHeight } from '../world/terrain.js'

const PHASES = [
  { wait: 22, shrink: 24, radius: 430, dps: 2 },
  { wait: 17, shrink: 20, radius: 305, dps: 3.5 },
  { wait: 15, shrink: 17, radius: 205, dps: 5 },
  { wait: 13, shrink: 15, radius: 132, dps: 7 },
  { wait: 11, shrink: 13, radius: 78, dps: 9 },
  { wait: 9, shrink: 11, radius: 34, dps: 12 },
  { wait: 7, shrink: 9, radius: 0, dps: 16 },
]

export class ZoneSystem {
  constructor(scene, seed = 1337) {
    this.scene = scene
    this.seed = seed
    this.rng = mulberry32(seed + 4242)
    this.phases = PHASES
    this.phase = 0
    this.radius = 560
    this.center = new THREE.Vector2(0, 0)
    this.targetRadius = PHASES[0].radius
    this.targetCenter = this._chooseCenter(this.radius, this.targetRadius)
    this.state = 'wait'
    this.timer = PHASES[0].wait
    this.shrinkDuration = PHASES[0].shrink
    this.fromRadius = this.radius
    this.fromCenter = this.center.clone()
    this.finished = false
    this.time = 0
    this.onPhase = null
    this._build()
  }

  _chooseCenter(currentRadius, nextRadius) {
    const maxOffset = Math.max(0, currentRadius - nextRadius) * 0.86
    const angle = this.rng() * Math.PI * 2
    const dist = Math.sqrt(this.rng()) * maxOffset
    let x = this.center.x + Math.cos(angle) * dist
    let z = this.center.y + Math.sin(angle) * dist
    const limit = Math.max(0, PLAY_RADIUS - 60 - nextRadius)
    const len = Math.hypot(x, z)
    if (len > limit && len > 0.001) { x = x / len * limit; z = z / len * limit }
    return new THREE.Vector2(x, z)
  }

  _build() {
    const wallGeo = new THREE.CylinderGeometry(1, 1, 1, 128, 1, true)
    wallGeo.translate(0, 0.5, 0)
    this.wallMat = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
      uniforms: {
        uTime: { value: 0 },
        uColor: { value: new THREE.Color(0x63dcff) },
        uOpacity: { value: 0.34 },
        uHeight: { value: 1 },
      },
      vertexShader: `
        varying vec2 vUv;
        varying vec3 vWorld;
        varying vec3 vNormal;
        void main() {
          vUv = uv;
          vec4 wp = modelMatrix * vec4(position, 1.0);
          vWorld = wp.xyz;
          vNormal = normalize(mat3(modelMatrix) * normal);
          gl_Position = projectionMatrix * viewMatrix * wp;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColor;
        uniform float uOpacity;
        varying vec2 vUv;
        varying vec3 vWorld;
        varying vec3 vNormal;
        void main() {
          float bands = sin(vUv.y * 90.0 - uTime * 2.6) * 0.5 + 0.5;
          float bands2 = sin(vUv.y * 24.0 + uTime * 0.7) * 0.5 + 0.5;
          float vertical = smoothstep(0.0, 0.14, vUv.y) * (1.0 - smoothstep(0.72, 1.0, vUv.y));
          float pulse = 0.55 + 0.45 * sin(uTime * 1.6);
          float alpha = uOpacity * (0.45 + bands * 0.3 + bands2 * 0.18) * vertical * pulse;
          vec3 col = uColor * (0.85 + bands * 0.35);
          gl_FragColor = vec4(col, alpha);
        }
      `,
    })
    this.wall = new THREE.Mesh(wallGeo, this.wallMat)
    this.wall.frustumCulled = false
    this.wall.renderOrder = 2
    this.scene.add(this.wall)

    const ringGeo = new THREE.CylinderGeometry(1, 1, 1, 96, 1, true)
    ringGeo.translate(0, 0.5, 0)
    this.nextMat = new THREE.MeshBasicMaterial({
      color: 0xffc857, transparent: true, opacity: 0.22, side: THREE.DoubleSide,
      depthWrite: false, blending: THREE.AdditiveBlending,
    })
    this.nextRing = new THREE.Mesh(ringGeo, this.nextMat)
    this.nextRing.frustumCulled = false
    this.scene.add(this.nextRing)
    this.nextRing.visible = false

    this._apply()
  }

  _apply() {
    this.wall.scale.set(this.radius, 170, this.radius)
    this.wall.position.set(this.center.x, -6, this.center.y)
    if (this.targetRadius > 1 && this.phase < this.phases.length) {
      this.nextRing.visible = true
      this.nextRing.scale.set(this.targetRadius, 7, this.targetRadius)
      this.nextRing.position.set(this.targetCenter.x, 1, this.targetCenter.y)
    } else {
      this.nextRing.visible = false
    }
  }

  update(dt) {
    this.time += dt
    this.wallMat.uniforms.uTime.value = this.time
    if (!this.finished) {
      this.timer -= dt
      if (this.state === 'wait') {
        if (this.timer <= 0) {
          this.state = 'shrink'
          this.timer = this.shrinkDuration
          this.fromRadius = this.radius
          this.fromCenter.copy(this.center)
          if (this.onPhase) this.onPhase('shrink', this.phase)
        }
      } else if (this.state === 'shrink') {
        const t = clamp(1 - this.timer / this.shrinkDuration, 0, 1)
        const eased = t * t * (3 - 2 * t)
        this.radius = lerp(this.fromRadius, this.targetRadius, eased)
        this.center.set(lerp(this.fromCenter.x, this.targetCenter.x, eased), lerp(this.fromCenter.y, this.targetCenter.y, eased))
        if (this.timer <= 0) {
          this.radius = this.targetRadius
          this.center.copy(this.targetCenter)
          this.phase++
          if (this.phase >= this.phases.length) {
            this.finished = true
            this.state = 'final'
            this.timer = 0
            if (this.onPhase) this.onPhase('final', this.phase)
          } else {
            const next = this.phases[this.phase]
            this.targetRadius = next.radius
            this.targetCenter = this._chooseCenter(this.radius, next.radius)
            this.shrinkDuration = next.shrink
            this.timer = next.wait
            this.state = 'wait'
            if (this.onPhase) this.onPhase('wait', this.phase)
          }
        }
      }
    }
    this._apply()
    const outside = this.phase < this.phases.length && this.distanceOutside(this.center.x, this.center.y) > 0
    this.wallMat.uniforms.uOpacity.value = outside ? 0.42 : 0.3
    if (this.nextRing.visible) this.nextMat.opacity = 0.14 + Math.sin(this.time * 2.2) * 0.06
  }

  distanceOutside(x, z) {
    return Math.hypot(x - this.center.x, z - this.center.y) - this.radius
  }

  isOutside(x, z) { return this.distanceOutside(x, z) > 0 }

  get damagePerSecond() {
    const p = this.phases[Math.min(this.phase, this.phases.length - 1)]
    return p ? p.dps : 16
  }

  getState() {
    return {
      phase: Math.min(this.phase + 1, this.phases.length),
      totalPhases: this.phases.length,
      timer: Math.max(0, this.timer),
      shrinking: this.state === 'shrink',
      finished: this.finished,
      center: this.center,
      radius: this.radius,
      nextCenter: this.targetCenter,
      nextRadius: this.targetRadius,
      dps: this.damagePerSecond,
      timerText: this.finished ? 'FINAL' : formatTime(this.timer),
    }
  }

  reset() {
    this.rng = mulberry32(this.seed + 4242)
    this.phase = 0
    this.radius = 560
    this.center.set(0, 0)
    this.targetRadius = PHASES[0].radius
    this.targetCenter = this._chooseCenter(this.radius, this.targetRadius)
    this.state = 'wait'
    this.timer = PHASES[0].wait
    this.shrinkDuration = PHASES[0].shrink
    this.fromRadius = this.radius
    this.fromCenter.copy(this.center)
    this.finished = false
    this._apply()
  }

  dispose() {
    this.scene.remove(this.wall, this.nextRing)
    this.wall.geometry.dispose()
    this.wallMat.dispose()
    this.nextRing.geometry.dispose()
    this.nextMat.dispose()
  }
}

import * as THREE from 'three'
import { Character } from '../entities/character.js'
import { WEAPONS, effectiveStats, weaponById } from '../game/weapons.js'
import { clamp, damp, dampAngle, distance2D, TAU } from '../core/utils.js'
import { WATER_LEVEL, PLAY_RADIUS } from '../world/terrain.js'

const ARMOR_POOL = { 1: 50, 2: 75, 3: 100 }
const BACKPACK_SLOTS = { 1: 8, 2: 12, 3: 16 }
const MAX_HEALTH = 100

export class Player {
  constructor(game, { name = 'NOVA-07', outfit, spawn, team = 0 } = {}) {
    this.game = game
    this.name = name
    this.outfit = outfit
    this.team = team
    this.isPlayer = true
    this.pos = new THREE.Vector3(spawn.x, spawn.y, spawn.z)
    this.vy = 0
    this.yaw = spawn.yaw ?? 0
    this.pitch = 0
    this.radius = 0.42
    this.height = 1.8
    this.health = MAX_HEALTH
    this.maxHealth = MAX_HEALTH
    this.armor = 0
    this.armorLevel = 0
    this.helmet = 0
    this.backpack = 1
    this.alive = true
    this.kills = 0
    this.damageDealt = 0
    this.shotsFired = 0
    this.shotsHit = 0
    this.weapons = [null, null, { def: WEAPONS.melee_machete, mag: 1, attachments: [] }]
    this.currentSlot = 0
    this.ammo = { light: 0, heavy: 0, shells: 0, sniper: 0, pistol: 60 }
    this.items = { medkit: 1, bandage: 2, grenade: 1 }
    this.fireTimer = 0
    this.reloading = false
    this.reloadTimer = 0
    this.reloadTotal = 1
    this.healing = null
    this.healTimer = 0
    this.healTotal = 1
    this.aiming = false
    this.crouching = false
    this.swimming = false
    this.sprinting = false
    this.onGround = false
    this.vehicle = null
    this.walkPhase = 0
    this.stepTimer = 0
    this.grenadeCooldown = 0
    this.hurtFlash = 0
    this.lastDamageTime = -99
    this.character = new Character({
      scene: game.scene,
      outfit,
      name,
      teamColor: outfit.accent || '#ff8a2b',
      isPlayer: true,
      quality: game.quality,
      level: game.profile.level,
    })
    this.character.setPosition(this.pos.x, this.pos.y, this.pos.z)
    this.character.setYaw(this.yaw)
    this.giveWeapon('ps_sidekick', [], true)
    this.setSlot(0)
    this.character.setArmor(0, 0)
  }

  get weaponEntry() { return this.weapons[this.currentSlot] }
  get weapon() { return this.weaponEntry?.def || null }
  get stats() { return this.weaponEntry ? effectiveStats(this.weaponEntry.def, this.weaponEntry.attachments) : null }
  get eyeHeight() { return this.crouching ? 1.12 : this.swimming ? 1.2 : 1.5 }
  get maxItems() { return BACKPACK_SLOTS[this.backpack] || 8 }

  setSlot(slot) {
    if (slot < 0 || slot > 2) return
    if (slot !== 2 && !this.weapons[slot]) return
    this.currentSlot = slot
    this.reloading = false
    this.reloadTimer = 0
    const entry = this.weaponEntry
    if (entry) {
      this.character.setWeapon(entry.def, entry.attachments)
      this.character.startReload(0.01)
      this.character.reloading = false
    }
  }

  swapWeapon() {
    const a = this.weapons[0] ? 0 : -1
    const b = this.weapons[1] ? 1 : -1
    if (a === -1 && b === -1) { this.setSlot(2); return }
    if (a === -1) { this.setSlot(1); return }
    if (b === -1) { this.setSlot(0); return }
    this.setSlot(this.currentSlot === 0 ? 1 : 0)
  }

  giveWeapon(id, attachments = [], select = false) {
    const def = weaponById(id)
    if (!def) return false
    let slot = this.weapons[0] ? (this.weapons[1] ? -1 : 1) : 0
    if (slot === -1) {
      slot = this.currentSlot === 1 ? 1 : 0
      this.dropWeapon(slot)
    }
    this.weapons[slot] = { def, mag: def.mag, attachments: [...attachments] }
    if (select) this.setSlot(slot)
    return true
  }

  dropWeapon(slot) {
    const entry = this.weapons[slot]
    if (!entry || slot === 2) return
    this.weapons[slot] = null
    if (this.currentSlot === slot) {
      this.currentSlot = 2
      this.character.setWeapon(WEAPONS.melee_machete, [])
    }
    this.game.loot?.dropAt(this.pos.x, this.pos.y + 0.6, this.pos.z, {
      type: 'weapon', weapon: entry.def.id, rarity: entry.def.rarity, attachments: [...entry.attachments],
    }, 0.5)
  }

  ammoFor(entry = this.weaponEntry) {
    if (!entry) return 0
    const type = entry.def.ammo
    if (!type || type === 'none') return Infinity
    return this.ammo[type] || 0
  }

  canPickup(item) {
    const data = item.data
    if (data.type === 'med' || data.type === 'grenade') {
      return this.items.medkit + this.items.bandage + this.items.grenade < this.maxItems
    }
    return true
  }

  pickup(item) {
    if (!item || !item.active) return { ok: false }
    const data = item.data
    let message = ''
    let rarity = data.rarity || 'common'
    switch (data.type) {
      case 'weapon': {
        const def = weaponById(data.weapon)
        let slot = this.weapons[0] ? (this.weapons[1] ? -1 : 1) : 0
        if (slot === -1) {
          slot = this.currentSlot === 2 ? 0 : this.currentSlot
          this.dropWeapon(slot)
        }
        this.weapons[slot] = { def, mag: def.mag, attachments: [...(data.attachments || [])] }
        this.setSlot(slot)
        message = `PICKED UP ${def.name}`
        break
      }
      case 'ammo': {
        this.ammo[data.ammo] = (this.ammo[data.ammo] || 0) + data.amount
        message = `+${data.amount} ${data.ammo.toUpperCase()} AMMO`
        break
      }
      case 'armor': {
        if (data.level <= this.armorLevel) return { ok: false, message: 'BETTER ARMOR EQUIPPED' }
        this.armorLevel = data.level
        this.armor = ARMOR_POOL[data.level]
        this.character.setArmor(this.armor, this.helmet)
        message = `ARMOR LV${data.level} EQUIPPED`
        break
      }
      case 'helmet': {
        if (data.level <= this.helmet) return { ok: false, message: 'BETTER HELMET EQUIPPED' }
        this.helmet = data.level
        this.character.setArmor(this.armor, this.helmet)
        message = `HELMET LV${data.level} EQUIPPED`
        break
      }
      case 'backpack': {
        if (data.level <= this.backpack) return { ok: false, message: 'BETTER PACK EQUIPPED' }
        this.backpack = data.level
        this.character.setBackpack(data.level)
        message = `BACKPACK LV${data.level} EQUIPPED`
        break
      }
      case 'med': {
        if (!this.canPickup(item)) return { ok: false, message: 'PACK FULL' }
        if (data.item === 'medkit') this.items.medkit++
        else this.items.bandage++
        message = data.item === 'medkit' ? 'MEDKIT ACQUIRED' : 'BANDAGE ACQUIRED'
        break
      }
      case 'grenade': {
        if (!this.canPickup(item)) return { ok: false, message: 'PACK FULL' }
        this.items.grenade += data.amount
        message = 'FRAG GRENADE ACQUIRED'
        break
      }
      case 'attachment': {
        const entry = this.weaponEntry
        if (!entry || entry.def.category === 'melee') return { ok: false, message: 'NO WEAPON FOR ATTACHMENT' }
        if (entry.attachments.includes(data.attachment)) return { ok: false, message: 'ALREADY ATTACHED' }
        entry.attachments.push(data.attachment)
        this.character.setWeapon(entry.def, entry.attachments)
        message = `ATTACHED ${data.attachment.replace('_', ' ').toUpperCase()}`
        break
      }
      default: return { ok: false }
    }
    this.game.loot.remove(item)
    this.game.effects?.pickup(new THREE.Vector3(item.x, item.y, item.z), data.type === 'weapon' ? 0xffb347 : 0x63dcff)
    this.game.audio.pickup(rarity)
    return { ok: true, message, rarity }
  }

  startReload() {
    if (this.currentSlot === 2 || this.reloading) return
    const entry = this.weaponEntry
    if (!entry) return
    const stats = this.stats
    const missing = stats.mag - entry.mag
    if (missing <= 0) return
    if (this.ammoFor(entry) <= 0) { this.game.ui?.toast('NO RESERVE AMMO', 'warn'); return }
    this.reloading = true
    this.reloadTotal = stats.reload
    this.reloadTimer = stats.reload
    this.character.startReload(stats.reload)
    this.game.audio.reload()
  }

  finishReload() {
    const entry = this.weaponEntry
    if (!entry) return
    const stats = this.stats
    const type = entry.def.ammo
    if (type && type !== 'none') {
      const need = stats.mag - entry.mag
      const take = Math.min(need, this.ammo[type] || 0)
      entry.mag += take
      this.ammo[type] -= take
    } else {
      entry.mag = stats.mag
    }
    this.reloading = false
    this.reloadTimer = 0
    this.character.reloading = false
  }

  tryFire() {
    if (!this.alive || this.vehicle || this.reloading || this.healing) return
    if (this.fireTimer > 0) return
    const entry = this.weaponEntry
    if (!entry) return
    const weapon = entry.def
    const stats = this.stats
    if (this.currentSlot === 2 || weapon.category === 'melee') {
      this.fireTimer = 60 / weapon.rpm
      this.character.shootRecoil(1)
      this.game.audio.gunshot('melee', 0.5)
      this.game.meleeAttack(this, stats.damage, stats.range)
      return
    }
    if (entry.mag <= 0) {
      this.game.audio.dryFire()
      this.fireTimer = 0.25
      this.startReload()
      return
    }
    if (this.swimming) {
      this.game.ui?.toast('CANNOT FIRE WHILE SWIMMING', 'warn')
      this.fireTimer = 0.4
      return
    }
    entry.mag--
    this.fireTimer = 60 / weapon.rpm
    this.shotsFired++
    this.character.shootRecoil(stats.recoil)
    const muzzle = this.character.getMuzzlePosition(new THREE.Vector3())
    const baseDir = this.getAimDirection(new THREE.Vector3())
    const moving = Math.hypot(this.velocityX || 0, this.velocityZ || 0) > 1
    let spreadDeg = stats.spread * (this.aiming ? 0.32 : 1) * (this.crouching ? 0.75 : 1) * (moving ? 1.55 : 1) * (this.onGround ? 1 : 1.5)
    if (weapon.category === 'sniper' && this.aiming) spreadDeg *= 0.3
    const pellets = weapon.pellets || 1
    for (let i = 0; i < pellets; i++) {
      const dir = this._spreadDirection(baseDir, spreadDeg)
      this.game.playerShoot(this, muzzle, dir, stats)
    }
    this.game.effects.muzzle(muzzle, weapon.category === 'sniper' ? 1.4 : 1)
    this.game.audio.gunshot(weapon.category, this.aiming ? 0.7 : 1)
    this.pitch = clamp(this.pitch + stats.recoil * 0.012 * (this.aiming ? 0.7 : 1), -1.2, 1.2)
    this.game.cameraShake = Math.min(0.5, (this.game.cameraShake || 0) + stats.recoil * 0.05)
    if (entry.mag <= 0) setTimeout(() => { if (this.alive && this.weaponEntry === entry && entry.mag === 0) this.startReload() }, 220)
  }

  _spreadDirection(base, spreadDeg) {
    const dir = base.clone()
    if (spreadDeg <= 0.001) return dir
    const rad = spreadDeg * Math.PI / 180
    const r = Math.sqrt(Math.random()) * rad
    const a = Math.random() * Math.PI * 2
    const right = new THREE.Vector3().crossVectors(dir, new THREE.Vector3(0, 1, 0)).normalize()
    if (right.lengthSq() < 0.001) right.set(1, 0, 0)
    const up = new THREE.Vector3().crossVectors(right, dir).normalize()
    dir.addScaledVector(right, Math.cos(a) * r).addScaledVector(up, Math.sin(a) * r).normalize()
    return dir
  }

  startHeal() {
    if (this.healing || !this.alive) return
    if (this.health >= this.maxHealth) { this.game.ui?.toast('HEALTH ALREADY FULL', 'warn'); return }
    let item = null, amount = 0, duration = 0
    if (this.items.medkit > 0) { item = 'medkit'; amount = 65; duration = 3.4 }
    else if (this.items.bandage > 0) { item = 'bandage'; amount = 28; duration = 1.7 }
    if (!item) { this.game.ui?.toast('NO MEDICAL SUPPLIES', 'warn'); return }
    this.healing = item
    this.healTimer = duration
    this.healTotal = duration
    this.healAmount = amount
    this.game.audio.heal()
    this.character.cancelReload()
  }

  updateHeal(dt) {
    if (!this.healing) return
    this.healTimer -= dt
    if (this.healTimer <= 0) {
      if (this.items[this.healing] > 0) this.items[this.healing]--
      this.health = Math.min(this.maxHealth, this.health + this.healAmount)
      this.healing = null
      this.healTimer = 0
      this.game.ui?.toast(`+${Math.round(this.healAmount)} HEALTH`, 'good')
    }
  }

  throwGrenade() {
    if (!this.alive || this.items.grenade <= 0 || this.grenadeCooldown > 0 || this.vehicle) return
    this.items.grenade--
    this.grenadeCooldown = 1.2
    this.game.audio.throwGrenade()
    this.game.throwGrenade(this)
  }

  getAimDirection(target = new THREE.Vector3()) {
    const cp = Math.cos(this.pitch)
    return target.set(Math.sin(this.yaw) * cp, Math.sin(this.pitch), Math.cos(this.yaw) * cp).normalize()
  }

  getEyePosition(target = new THREE.Vector3()) {
    return target.set(this.pos.x, this.pos.y + this.eyeHeight, this.pos.z)
  }

  update(dt, time) {
    this.fireTimer = Math.max(0, this.fireTimer - dt)
    this.grenadeCooldown = Math.max(0, this.grenadeCooldown - dt)
    if (!this.alive) {
      this.character.update(dt, time)
      return
    }
    const input = this.game.input
    if (!this.game.paused && this.game.state === 'match') {
      const look = input.consumeLook()
      this.yaw -= look.x
      this.pitch = clamp(this.pitch - look.y, -1.15, 1.15)
      this.aiming = input.isDown('aim') && !this.sprinting && this.currentSlot !== 2
      this.crouching = input.isDown('crouch') && !this.swimming
      if (input.wasPressed('weapon1')) this.setSlot(0)
      if (input.wasPressed('weapon2')) this.setSlot(1)
      if (input.wasPressed('weapon3')) this.setSlot(2)
      if (input.wasPressed('swap')) this.swapWeapon()
      if (input.wasPressed('reload')) this.startReload()
      if (input.wasPressed('med')) this.startHeal()
      if (input.wasPressed('grenade')) this.throwGrenade()
      const firePressed = input.wasPressed('fire')
      const fireHeld = input.isDown('fire')
      if (this.weapon && (firePressed || (fireHeld && this.weapon.def.auto))) this.tryFire()
      if (firePressed && this.healing) { this.healing = null; this.healTimer = 0 }
    } else {
      this.aiming = false
      this.crouching = false
    }

    this.updateHeal(dt)
    if (this.reloading) {
      this.reloadTimer -= dt
      if (this.reloadTimer <= 0) this.finishReload()
    }

    if (this.vehicle) {
      this.pos.copy(this.vehicle.pos)
      this.character.group.visible = false
      this.character.update(dt, time)
      return
    }
    this.character.group.visible = true
    this._move(dt)
    this.character.setPosition(this.pos.x, this.pos.y, this.pos.z)
    this.character.setYaw(this.yaw)
    this.character.moveSpeed = Math.hypot(this.velocityX || 0, this.velocityZ || 0)
    this.character.aiming = this.aiming
    this.character.crouch = this.crouching
    this.character.swimming = this.swimming
    this.character.aimPitch = this.pitch
    this.character.update(dt, time)
    if (this.aiming && this.weapon && this.currentSlot !== 2) this.character.setWeapon(this.weapon, this.weaponEntry.attachments)
  }

  _move(dt) {
    const input = this.game.input
    let mx = 0, my = 0
    if (this.game.state === 'match' && !this.game.paused) {
      mx = input.move.x
      my = input.move.y
    }
    const moveLen = Math.hypot(mx, my)
    if (moveLen > 1) { mx /= moveLen; my /= moveLen }
    const forwardX = Math.sin(this.yaw), forwardZ = Math.cos(this.yaw)
    const rightX = -Math.cos(this.yaw), rightZ = Math.sin(this.yaw)
    let dirX = forwardX * -my + rightX * mx
    let dirZ = forwardZ * -my + rightZ * mx

    const water = this.game.world.isWaterAt(this.pos.x, this.pos.z) && this.pos.y < WATER_LEVEL + 0.2
    this.swimming = water && this.pos.y < WATER_LEVEL - 0.3
    const sprintKey = this.game.input.isDown('sprint') || this.game.settings.autoSprint
    this.sprinting = sprintKey && !this.aiming && !this.crouching && !this.swimming && my < -0.2

    let speed = this.swimming ? 2.7 : this.crouching ? 2.4 : this.aiming ? 2.9 : this.sprinting ? 7.2 : 4.6
    if (this.weapon) speed *= clamp(this.weapon.mobility || 1, 0.6, 1.3)
    if (this.healing) speed *= 0.55

    let ladder = null
    for (const l of this.game.world.ladders) {
      if (Math.hypot(this.pos.x - l.x, this.pos.z - l.z) < (l.radius || 1.8) && this.pos.y > l.bottom - 1 && this.pos.y < l.top + 1) { ladder = l; break }
    }
    if (ladder && my < -0.1) {
      this.vy = 3.6
      this.onGround = false
    } else if (!this.swimming) {
      this.vy -= 18 * dt
    }

    const targetVX = dirX * speed
    const targetVZ = dirZ * speed
    this.velocityX = damp(this.velocityX || 0, targetVX, this.swimming ? 4 : 12, dt)
    this.velocityZ = damp(this.velocityZ || 0, targetVZ, this.swimming ? 4 : 12, dt)

    let nx = this.pos.x + this.velocityX * dt
    let nz = this.pos.z + this.velocityZ * dt
    const resolved = this.game.world.resolveCollision(nx, nz, this.radius, this.pos.y, this.height)
    nx = resolved.x
    nz = resolved.z
    const dist = Math.hypot(nx, nz)
    const limit = PLAY_RADIUS - 8
    if (dist > limit) { nx = nx / dist * limit; nz = nz / dist * limit }
    this.pos.x = nx
    this.pos.z = nz

    if (this.swimming) {
      this.vy = 0
      this.pos.y = damp(this.pos.y, WATER_LEVEL - 1.05 + Math.sin(performance.now() * 0.002) * 0.06, 5, dt)
      this.onGround = false
    } else {
      this.pos.y += this.vy * dt
      const ground = this.game.world.groundHeight(this.pos.x, this.pos.z)
      if (this.pos.y <= ground) {
        this.pos.y = ground
        this.vy = 0
        this.onGround = true
      } else {
        this.onGround = false
      }
      if (this.onGround && this.game.input.wasPressed('jump')) {
        this.vy = 6.4
        this.onGround = false
        this.game.audio.footstep('grass')
      }
    }

    const hspeed = Math.hypot(this.velocityX, this.velocityZ)
    if (hspeed > 0.6 && this.onGround) {
      this.stepTimer -= dt
      if (this.stepTimer <= 0) {
        this.game.audio.footstep(this.swimming ? 'water' : 'grass')
        this.stepTimer = this.sprinting ? 0.3 : 0.45
      }
    }
  }

  takeDamage(amount, source = null, headshot = false) {
    if (!this.alive || this.game.state !== 'match') return
    let dmg = amount
    if (headshot && this.helmet > 0) dmg *= 0.68
    if (this.armor > 0) {
      const absorbed = Math.min(this.armor, dmg * 0.62)
      this.armor -= absorbed
      dmg -= absorbed
      if (this.armor <= 0.01) { this.armor = 0; this.armorLevel = 0; this.character.setArmor(0, this.helmet) }
    }
    this.health -= dmg
    this.lastDamageTime = this.game.matchTime
    this.hurtFlash = 1
    this.game.audio.damage()
    this.game.onPlayerHurt(dmg, source, headshot)
    if (this.health <= 0) {
      this.health = 0
      this.die(source)
    }
  }

  die(source = null) {
    if (!this.alive) return
    this.alive = false
    this.health = 0
    this.healing = null
    this.reloading = false
    this.character.die()
    this.game.onPlayerDeath(source)
  }

  heal(amount) {
    this.health = Math.min(this.maxHealth, this.health + amount)
  }

  getHudState() {
    const entry = this.weaponEntry
    const stats = entry ? this.stats : null
    return {
      health: this.health,
      armor: this.armor,
      helmet: this.helmet,
      backpack: this.backpack,
      weaponName: entry ? entry.def.name : 'UNARMED',
      category: entry ? entry.def.category : '',
      mag: entry ? entry.mag : 0,
      magSize: stats ? stats.mag : 0,
      reserve: entry ? this.ammoFor(entry) : 0,
      ammoType: entry ? entry.def.ammo : '',
      auto: entry ? entry.def.auto : false,
      reloading: this.reloading,
      reloadProgress: this.reloading ? 1 - this.reloadTimer / Math.max(0.01, this.reloadTotal) : 0,
      healing: this.healing,
      healProgress: this.healing ? 1 - this.healTimer / Math.max(0.01, this.healTotal) : 0,
      swimming: this.swimming,
      crouching: this.crouching,
      sprinting: this.sprinting,
      aiming: this.aiming,
      vehicle: !!this.vehicle,
    }
  }

  dispose() {
    this.character.dispose()
  }
}

input.oldString:
  this.character.update(dt, time)
  if (this.aiming && this.weapon && this.currentSlot !== 2) this.character.setWeapon(this.weapon, this.weaponEntry.attachments)
}

