import * as THREE from 'three'
import { Character } from '../entities/character.js'
import { SPAWN_WEAPONS, effectiveStats, weaponById } from '../game/weapons.js'
import { SKINS } from '../core/save.js'
import { clamp, damp, dampAngle, distance2D, mulberry32, pick, randInt, ORIGINAL_NAMES, TAU } from '../core/utils.js'
import { WATER_LEVEL } from '../world/terrain.js'

const SKILLS = {
  recruit: { accuracy: 0.5, reaction: 0.95, aggression: 0.35, damage: 0.72, sight: 62, healChance: 0.5 },
  veteran: { accuracy: 0.7, reaction: 0.55, aggression: 0.65, damage: 0.9, sight: 78, healChance: 0.72 },
  elite: { accuracy: 0.85, reaction: 0.32, aggression: 0.88, damage: 1, sight: 92, healChance: 0.88 },
}

const BOT_COLORS = [
  { primary: '#3b3f43', secondary: '#16181b', accent: '#ff5a5a' },
  { primary: '#3d5c3a', secondary: '#1c2a1b', accent: '#a9d66b' },
  { primary: '#7c2429', secondary: '#241012', accent: '#ff8a2b' },
  { primary: '#46356e', secondary: '#191226', accent: '#b78bff' },
  { primary: '#2f6f8f', secondary: '#152430', accent: '#63dcff' },
  { primary: '#9c7427', secondary: '#2b2113', accent: '#ffd166' },
  { primary: '#c7dbe3', secondary: '#3b5361', accent: '#9fdcff' },
  { primary: '#1f6f7a', secondary: '#102a33', accent: '#ff7ad9' },
]

export class Bot {
  constructor(game, { spawn, team = 1, name, skill = 'veteran', index = 0 }) {
    this.game = game
    this.team = team
    this.index = index
    this.name = name || pick(Math.random, ORIGINAL_NAMES) + '-' + String(10 + index)
    this.skillName = skill
    this.skill = SKILLS[skill] || SKILLS.veteran
    this.pos = new THREE.Vector3(spawn.x, spawn.y, spawn.z)
    this.yaw = spawn.yaw ?? Math.random() * Math.PI * 2
    this.health = 100
    this.armor = randInt(Math.random, 0, 2) === 2 ? 50 : 0
    this.armorLevel = this.armor > 0 ? 1 : 0
    this.helmet = Math.random() > 0.7 ? 1 : 0
    this.alive = true
    this.state = 'loot'
    this.target = null
    this.targetScan = 0
    this.dest = null
    this.lootTarget = null
    this.thinkTimer = Math.random() * 0.4
    this.fireTimer = 0.5 + Math.random()
    this.reactionTimer = 0.4 + Math.random() * this.skill.reaction
    this.reloading = false
    this.reloadTimer = 0
    this.healTimer = 0
    this.medkits = randInt(Math.random, 1, 2)
    this.stuckTimer = 0
    this.lastPos = this.pos.clone()
    this.deadTime = 0
    this.damageTaken = 0
    this.velocityX = 0
    this.velocityZ = 0
    this.walkPhase = Math.random() * TAU
    const palette = BOT_COLORS[index % BOT_COLORS.length]
    const skin = pick(Math.random, SKINS)
    this.outfit = {
      primary: palette.primary, secondary: palette.secondary, accent: palette.accent,
      skinColor: skin.skin, hairColor: skin.hair, hair: pick(Math.random, ['short', 'mohawk', 'bun', 'long', 'bald', 'helmet']),
    }
    this.weapon = pick(Math.random, SPAWN_WEAPONS)
    this.mag = this.weapon.mag
    this.reserve = 150
    this.character = new Character({
      scene: game.scene,
      outfit: this.outfit,
      name: this.name,
      teamColor: game.teamColor(this.team),
      isPlayer: false,
      quality: game.quality,
      simple: true,
    })
    this.character.teamLabel = game.teamLabel(this.team)
    this.character.setName(this.name, game.teamColor(this.team))
    this.character.setWeapon(this.weapon, [])
    this.character.setArmor(this.armor, this.helmet)
    this.character.setPosition(this.pos.x, this.pos.y, this.pos.z)
    this.character.setYaw(this.yaw)
    this.character.setHealth(this.health, 100, this.armor)
  }

  get stats() { return effectiveStats(this.weapon, []) }

  update(dt, time) {
    if (!this.alive) {
      this.deadTime += dt
      this.character.update(dt, time)
      return
    }
    this.fireTimer = Math.max(0, this.fireTimer - dt)
    this.reactionTimer = Math.max(0, this.reactionTimer - dt)
    this.thinkTimer -= dt
    const zone = this.game.zone
    if (zone && zone.isOutside(this.pos.x, this.pos.z)) {
      this.takeDamage(zone.damagePerSecond * dt, null, false, true)
      if (!this.alive) return
    }
    if (this.reloading) {
      this.reloadTimer -= dt
      if (this.reloadTimer <= 0) {
        this.mag = this.stats.mag
        this.reserve -= this.stats.mag
        this.reloading = false
        this.character.reloading = false
      }
    }
    if (this.healTimer > 0) {
      this.healTimer -= dt
      if (this.healTimer <= 0) {
        this.health = Math.min(100, this.health + 42)
        this.medkits--
        this.character.setHealth(this.health, 100, this.armor)
        this.character.cancelReload()
      }
    }
    if (this.thinkTimer <= 0) {
      this.think()
      this.thinkTimer = 0.28 + Math.random() * 0.25
    }
    this._move(dt)
    if (this.state === 'fight' && this.target && this.target.alive) {
      const dx = this.target.pos.x - this.pos.x
      const dz = this.target.pos.z - this.pos.z
      const dist = Math.hypot(dx, dz)
      this.yaw = dampAngle(this.yaw, Math.atan2(dx, dz), 9, dt)
      this.character.aiming = true
      this.character.aimPitch = Math.atan2((this.target.pos.y + 1.2) - (this.pos.y + 1.3), dist)
      if (this.reactionTimer <= 0 && this.fireTimer <= 0 && !this.reloading && this.healTimer <= 0) {
        if (dist < this.stats.range && this.game.world.hasLineOfSight(this.pos.x, this.pos.y + 1.35, this.pos.z, this.target.pos.x, this.target.pos.y + 1.15, this.target.pos.z)) {
          this.shoot(dist)
        }
      }
    } else {
      this.character.aiming = false
    }
    this.character.setPosition(this.pos.x, this.pos.y, this.pos.z)
    this.character.setYaw(this.yaw)
    this.character.moveSpeed = Math.hypot(this.velocityX, this.velocityZ)
    this.character.update(dt, time)
  }

  think() {
    const game = this.game
    const zone = game.zone
    if (this.healTimer > 0) return
    if (!zone) return
    const zoneState = zone.getState()
    const outside = zone.isOutside(this.pos.x, this.pos.z)
    const nearEdge = zone.distanceOutside(this.pos.x, this.pos.z) > -14
    if (outside || (nearEdge && zoneState.shrinking)) {
      this.state = 'rotate'
      this.target = null
      this.dest = this._zonePoint(0.55)
      return
    }
    this.targetScan -= 0.3
    if (this.targetScan <= 0) {
      this.targetScan = 0.45 + Math.random() * 0.3
      this.target = game.findBotTarget(this)
    }
    if (this.target && this.target.alive) {
      const dist = distance2D(this.pos.x, this.pos.z, this.target.pos.x, this.target.pos.z)
      if (dist < this.skill.sight && game.world.hasLineOfSight(this.pos.x, this.pos.y + 1.4, this.pos.z, this.target.pos.x, this.target.pos.y + 1.1, this.target.pos.z)) {
        this.state = 'fight'
        return
      }
    }
    if (this.health < 52 && this.medkits > 0 && Math.random() < this.skill.healChance) {
      this.state = 'heal'
      this.healTimer = 2.6
      this.target = null
      this.dest = null
      this.character.startReload(2.6)
      return
    }
    const item = game.loot.nearest(this.pos.x, this.pos.y, this.pos.z, 34)
    if (item && (this._wantsLoot(item) || this.state !== 'loot')) {
      this.lootTarget = item
      this.state = 'loot'
      this.dest = { x: item.x, z: item.z }
      this.target = null
      return
    }
    if (!this.dest || distance2D(this.pos.x, this.pos.z, this.dest.x, this.dest.z) < 3) {
      this.dest = this._zonePoint(0.62)
    }
    this.state = 'rotate'
    this.target = null
  }

  _wantsLoot(item) {
    const data = item.data
    if (data.type === 'weapon') {
      const def = weaponById(data.weapon)
      if (!def) return false
      const order = { common: 0, rare: 1, epic: 2, legendary: 3 }
      return (order[def.rarity] || 0) > (order[this.weapon.rarity] || 0) || data.weapon === this.weapon.id
    }
    if (data.type === 'armor') return data.level > this.armorLevel
    if (data.type === 'helmet') return data.level > this.helmet
    if (data.type === 'med') return this.medkits < 3
    if (data.type === 'ammo') return true
    return false
  }

  _zonePoint(factor = 0.6) {
    const zone = this.game.zone
    const a = Math.random() * Math.PI * 2
    const r = Math.sqrt(Math.random()) * Math.max(6, zone.radius * factor)
    return { x: zone.center.x + Math.cos(a) * r, z: zone.center.y + Math.sin(a) * r }
  }

  _move(dt) {
    if (this.healTimer > 0) {
      this.velocityX = damp(this.velocityX, 0, 10, dt)
      this.velocityZ = damp(this.velocityZ, 0, 10, dt)
      this._integrate(dt)
      return
    }
    let targetX = null, targetZ = null
    if (this.state === 'fight' && this.target && this.target.alive) {
      const dist = distance2D(this.pos.x, this.pos.z, this.target.pos.x, this.target.pos.z)
      const preferred = this.weapon.category === 'shotgun' ? 7 : this.weapon.category === 'sniper' ? 42 : this.weapon.category === 'smg' ? 14 : 26
      const toX = (this.target.pos.x - this.pos.x) / (dist || 1)
      const toZ = (this.target.pos.z - this.pos.z) / (dist || 1)
      if (dist > preferred + 5) { targetX = this.pos.x + toX * 12; targetZ = this.pos.z + toZ * 12 }
      else if (dist < preferred - 5) { targetX = this.pos.x - toX * 10; targetZ = this.pos.z - toZ * 10 }
      else {
        const strafe = Math.sin(this.game.matchTime * 1.4 + this.index) * 8
        targetX = this.pos.x - toZ * strafe
        targetZ = this.pos.z + toX * strafe
      }
    } else if (this.state === 'loot' && this.lootTarget?.active) {
      targetX = this.lootTarget.x
      targetZ = this.lootTarget.z
      if (distance2D(this.pos.x, this.pos.z, targetX, targetZ) < 1.6) {
        this.game.botPickup(this, this.lootTarget)
        this.lootTarget = null
        this.dest = null
        this.state = 'rotate'
      }
    } else if (this.dest) {
      targetX = this.dest.x
      targetZ = this.dest.z
      if (distance2D(this.pos.x, this.pos.z, targetX, targetZ) < 2) {
        this.dest = null
      }
    }
    let dx = 0, dz = 0
    if (targetX !== null) {
      const ddx = targetX - this.pos.x, ddz = targetZ - this.pos.z
      const len = Math.hypot(ddx, ddz)
      if (len > 0.2) { dx = ddx / len; dz = ddz / len }
    }
    let speed = this.state === 'fight' ? 3.4 : 4.9
    if (this.state === 'rotate') speed = 6.1
    if (this.state === 'loot') speed = 5.2
    const water = this.game.world.isWaterAt(this.pos.x, this.pos.z) && this.pos.y < WATER_LEVEL + 0.2
    if (water) speed *= 0.55
    this.velocityX = damp(this.velocityX, dx * speed, 7, dt)
    this.velocityZ = damp(this.velocityZ, dz * speed, 7, dt)
    if (this.state !== 'fight' && (dx || dz)) {
      this.yaw = dampAngle(this.yaw, Math.atan2(dx, dz), 5, dt)
    }
    this._integrate(dt)
    if (water) this.pos.y = damp(this.pos.y, WATER_LEVEL - 1.1, 5, dt)
  }

  _integrate(dt) {
    let nx = this.pos.x + this.velocityX * dt
    let nz = this.pos.z + this.velocityZ * dt
    const resolved = this.game.world.resolveCollision(nx, nz, 0.42, this.pos.y, 1.8)
    nx = resolved.x
    nz = resolved.z
    this.pos.x = nx
    this.pos.z = nz
    const ground = this.game.world.groundHeight(this.pos.x, this.pos.z)
    this.pos.y = ground
    const moved = distance2D(this.pos.x, this.pos.z, this.lastPos.x, this.lastPos.z)
    if (moved < 0.01) {
      this.stuckTimer += dt
      if (this.stuckTimer > 1.2) {
        this.stuckTimer = 0
        this.dest = this._zonePoint(0.7)
        this.lastPos.copy(this.pos)
      }
    } else {
      this.stuckTimer = 0
      this.lastPos.copy(this.pos)
    }
  }

  shoot(dist) {
    const stats = this.stats
    this.fireTimer = 60 / stats.rpm * (this.weapon.auto ? 1 : 1.25)
    if (this.mag <= 0) {
      this.startReload()
      return
    }
    this.mag--
    const target = this.target
    if (!target || !target.alive) return
    const origin = this.character.getMuzzlePosition(new THREE.Vector3())
    const aim = new THREE.Vector3(target.pos.x, target.pos.y + (Math.random() > 0.86 ? 1.55 : 1.15), target.pos.z)
    const dir = aim.sub(origin).normalize()
    const error = (1 - this.skill.accuracy) * clamp(0.035 + dist * 0.0009, 0.03, 0.16)
    dir.x += (Math.random() - 0.5) * error * 2
    dir.y += (Math.random() - 0.5) * error * 1.2
    dir.z += (Math.random() - 0.5) * error * 2
    dir.normalize()
    this.game.effects.muzzle(origin, 0.85)
    if (distance2D(this.game.player.pos.x, this.game.player.pos.z, this.pos.x, this.pos.z) < 70) {
      this.game.audio.gunshot(this.weapon.category, 0.55)
    }
    for (let i = 0; i < (this.weapon.pellets || 1); i++) {
      const pelletDir = dir.clone()
      if ((this.weapon.pellets || 1) > 1) {
        pelletDir.x += (Math.random() - 0.5) * 0.08
        pelletDir.y += (Math.random() - 0.5) * 0.05
        pelletDir.z += (Math.random() - 0.5) * 0.08
        pelletDir.normalize()
      }
      this.game.resolveShot(origin, pelletDir, stats.range, stats.damage * this.skill.damage, this)
    }
    if (this.mag <= 0) this.startReload()
  }

  startReload() {
    if (this.reloading) return
    this.reloading = true
    this.reloadTimer = this.stats.reload
    this.character.startReload(this.stats.reload)
  }

  takeDamage(amount, source = null, headshot = false, silent = false) {
    if (!this.alive) return
    let dmg = amount
    if (headshot && this.helmet > 0) dmg *= 0.7
    if (this.armor > 0) {
      const absorbed = Math.min(this.armor, dmg * 0.6)
      this.armor -= absorbed
      dmg -= absorbed
      if (this.armor <= 0.01) { this.armor = 0; this.armorLevel = 0 }
    }
    this.health -= dmg
    this.damageTaken += dmg
    this.character.setHealth(this.health, 100, this.armor)
    if (!silent) {
      this.game.effects.blood(new THREE.Vector3(this.pos.x, this.pos.y + 1.2, this.pos.z))
      if (source === this.game.player) {
        this.game.effects.damageNumber(new THREE.Vector3(this.pos.x, this.pos.y + 1.5, this.pos.z), dmg, headshot ? '#ff5a5a' : '#ffe2a8')
      }
      this.game.audio.hit(headshot)
    }
    if (this.health <= 0) {
      this.health = 0
      this.die(source)
    } else if (!this.target && source) {
      this.target = source
      this.state = 'fight'
      this.reactionTimer = this.skill.reaction * 0.5
    }
  }

  die(source = null) {
    if (!this.alive) return
    this.alive = false
    this.deadTime = 0
    this.character.die()
    this.game.onBotDeath(this, source)
  }

  dispose() {
    this.character.dispose()
  }
}

import * as THREE from 'three'
import { clamp, damp, dampAngle, distance2D } from '../core/utils.js'
import { WATER_LEVEL } from '../world/terrain.js'

const bodyMat = new THREE.MeshStandardMaterial({ color: 0x6c5a3a, roughness: 0.62, metalness: 0.35 })
const trimMat = new THREE.MeshStandardMaterial({ color: 0x2a2f33, roughness: 0.5, metalness: 0.6 })
const seatMat = new THREE.MeshStandardMaterial({ color: 0x22282c, roughness: 0.9 })
const glowMat = new THREE.MeshBasicMaterial({ color: 0xffd28a })
const wheelMat = new THREE.MeshStandardMaterial({ color: 0x15181a, roughness: 0.95 })

function box(parent, mat, x, y, z, w, h, d) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat)
  m.position.set(x, y, z)
  m.castShadow = true
  m.receiveShadow = true
  parent.add(m)
  return m
}

export class Vehicle {
  constructor(game, spawn) {
    this.game = game
    this.pos = new THREE.Vector3(spawn.x, spawn.y, spawn.z)
    this.spawn = { ...spawn }
    this.yaw = spawn.rot || 0
    this.speed = 0
    this.health = 320
    this.maxHealth = 320
    this.occupied = false
    this.driver = null
    this.wheelSpin = 0
    this.roll = 0
    this.runoverCooldown = 0
    this.destroyed = false
    this.group = new THREE.Group()
    this._build()
    this.group.position.copy(this.pos)
    this.group.rotation.y = this.yaw
    game.scene.add(this.group)
  }

  _build() {
    const g = this.group
    box(g, bodyMat, 0, 0.62, 0, 1.7, 0.42, 2.9)
    box(g, bodyMat, 0, 0.9, -0.35, 1.5, 0.28, 1.5)
    box(g, trimMat, 0, 1.05, -0.9, 1.5, 0.34, 0.5)
    box(g, trimMat, 0, 1.22, -0.4, 0.12, 0.5, 0.12)
    box(g, trimMat, 0.62, 1.22, -0.4, 0.12, 0.5, 0.12)
    box(g, trimMat, -0.62, 1.22, -0.4, 0.12, 0.5, 0.12)
    box(g, trimMat, 0, 1.46, -0.4, 1.5, 0.12, 0.14)
    box(g, seatMat, 0, 0.9, 0.15, 1.3, 0.32, 0.7)
    box(g, trimMat, 0, 0.95, 1.42, 1.7, 0.3, 0.3)
    const lightL = box(g, glowMat, -0.55, 0.78, 1.5, 0.34, 0.2, 0.08)
    const lightR = box(g, glowMat, 0.55, 0.78, 1.5, 0.34, 0.2, 0.08)
    lightL.material = glowMat
    lightR.material = glowMat
    this.wheels = []
    const wheelGeo = new THREE.CylinderGeometry(0.46, 0.46, 0.34, 12)
    wheelGeo.rotateZ(Math.PI / 2)
    for (const x of [-0.92, 0.92]) {
      for (const z of [-1.0, 1.05]) {
        const wheel = new THREE.Mesh(wheelGeo, wheelMat)
        wheel.position.set(x, 0.46, z)
        wheel.castShadow = true
        g.add(wheel)
        this.wheels.push(wheel)
      }
    }
    // Exhaust + antenna
    const pipe = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.08, 0.5, 6), trimMat)
    pipe.position.set(-0.5, 0.85, -1.5)
    pipe.rotation.x = Math.PI / 2
    g.add(pipe)
  }

  get forward() { return new THREE.Vector3(Math.sin(this.yaw), 0, Math.cos(this.yaw)) }

  enter(player) {
    if (this.occupied || this.destroyed) return false
    this.occupied = true
    this.driver = player
    player.vehicle = this
    player.character.group.visible = false
    this.game.ui?.toast('VEHICLE ACQUIRED · DRIVE', 'good')
    this.game.audio.pickup('rare')
    return true
  }

  exit() {
    if (!this.occupied) return
    const player = this.driver
    const side = new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw))
    const x = this.pos.x + side.x * 2.2
    const z = this.pos.z + side.z * 2.2
    player.pos.set(x, this.game.world.groundHeight(x, z), z)
    player.vehicle = null
    player.character.group.visible = true
    player.vy = 0
    this.occupied = false
    this.driver = null
    this.speed = 0
  }

  takeDamage(amount) {
    this.health -= amount
    if (this.health <= 0 && !this.destroyed) this.explode()
  }

  explode() {
    this.destroyed = true
    this.game.effects.explosion(this.pos.clone().add(new THREE.Vector3(0, 1, 0)), 1.4)
    this.game.audio.explosion()
    if (this.driver) {
      const driver = this.driver
      this.exit()
      driver.takeDamage(55, null)
    }
    this.game.explode(this.pos.clone().add(new THREE.Vector3(0, 0.8, 0)), 6, 65, null)
    this.group.visible = false
  }

  reset() {
    this.pos.set(this.spawn.x, this.spawn.y, this.spawn.z)
    this.yaw = this.spawn.rot || 0
    this.speed = 0
    this.health = this.maxHealth
    this.destroyed = false
    this.group.visible = true
    this.occupied = false
    this.driver = null
    this.group.position.copy(this.pos)
    this.group.rotation.y = this.yaw
  }

  update(dt, time) {
    if (this.destroyed) return
    this.runoverCooldown = Math.max(0, this.runoverCooldown - dt)
    if (this.occupied && this.driver) {
      const input = this.game.input
      const throttle = this.game.state === 'match' && !this.game.paused ? -input.move.y : 0
      const steer = this.game.state === 'match' && !this.game.paused ? input.move.x : 0
      const maxSpeed = 17
      const target = throttle > 0 ? maxSpeed : throttle < 0 ? -6.5 : 0
      this.speed = damp(this.speed, target, throttle !== 0 ? 1.7 : 2.4, dt)
      if (Math.abs(this.speed) > 0.4) {
        this.yaw -= steer * dt * 1.5 * clamp(Math.abs(this.speed) / 8, 0.25, 1.4)
      }
      const fx = Math.sin(this.yaw), fz = Math.cos(this.yaw)
      let nx = this.pos.x + fx * this.speed * dt
      let nz = this.pos.z + fz * this.speed * dt
      const resolved = this.game.world.resolveCollision(nx, nz, 1.5, this.pos.y + 0.4, 2.2)
      const blocked = Math.abs(resolved.x - nx) + Math.abs(resolved.z - nz) > 0.05
      this.pos.x = resolved.x
      this.pos.z = resolved.z
      if (blocked) {
        if (Math.abs(this.speed) > 7) {
          this.takeDamage(Math.abs(this.speed) * 1.8)
          this.game.audio.footstep('metal')
        }
        this.speed *= 0.35
      }
      const ground = this.game.world.groundHeight(this.pos.x, this.pos.z)
      this.pos.y = damp(this.pos.y, ground, 12, dt)
      if (this.game.world.isWaterAt(this.pos.x, this.pos.z)) this.speed = damp(this.speed, 0, 4, dt)
      this.driver.pos.copy(this.pos)
      this.wheelSpin += this.speed * dt * 1.6
      this.roll = damp(this.roll, -steer * clamp(this.speed / maxSpeed, -1, 1) * 0.09, 6, dt)
      this.group.rotation.set(0, this.yaw, 0)
      this.group.rotation.z = this.roll
      for (const w of this.wheels) w.rotation.x = this.wheelSpin
      // Run over enemies
      if (Math.abs(this.speed) > 5 && this.runoverCooldown <= 0) {
        for (const bot of this.game.bots) {
          if (!bot.alive) continue
          if (this.game.isEnemy(this.driver, bot) && distance2D(bot.pos.x, bot.pos.z, this.pos.x, this.pos.z) < 2.1) {
            bot.takeDamage(42 + Math.abs(this.speed) * 2.5, this.driver)
            this.runoverCooldown = 0.5
            this.game.cameraShake = 0.3
            break
          }
        }
      }
    } else {
      this.speed = damp(this.speed, 0, 3, dt)
    }
    this.group.position.copy(this.pos)
    this.group.position.y += Math.sin(time * 8 + this.pos.x) * 0.008
  }
}

import * as THREE from 'three'
import { World } from '../world/world.js'
import { LootManager } from './loot.js'
import { ZoneSystem } from './zone.js'
import { Effects } from './effects.js'
import { LobbyScene } from './lobby.js'
import { Player } from '../entities/player.js'
import { Bot } from '../entities/bot.js'
import { Vehicle } from '../entities/vehicle.js'
import { currentOutfit, recordMatch, saveProfile } from '../core/save.js'
import { WEAPONS, weaponById } from './weapons.js'
import { clamp, damp, dampAngle, distance2D, mulberry32, pick, randInt, ORIGINAL_NAMES, raySphere, formatTime, TAU } from '../core/utils.js'
import { PLAY_RADIUS, WATER_LEVEL } from '../world/terrain.js'

const TEAM_COLORS = ['#54e6a5', '#ff6b6b', '#ffb347', '#b78bff', '#63dcff', '#ff7ad9', '#ffd166']
const nextFrame = () => new Promise(resolve => requestAnimationFrame(() => resolve()))
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms))

export class Game {
  constructor({ renderer, canvas, profile, audio, input }) {
    this.renderer = renderer
    this.canvas = canvas
    this.profile = profile
    this.settings = profile.settings
    this.audio = audio
    this.input = input
    this.ui = null
    this.state = 'boot'
    this.mode = 'solo'
    this.quality = this.settings.quality || 'high'
    this.scene = new THREE.Scene()
    this.camera = new THREE.PerspectiveCamera(70, 1, 0.08, 3200)
    this.camera.position.set(0, 6, 12)
    this.lobby = null
    this.world = null
    this.worldScene = null
    this.loot = null
    this.zone = null
    this.effects = null
    this.vehicles = []
    this.player = null
    this.bots = []
    this.grenades = []
    this.matchTime = 0
    this.matchStarted = false
    this.paused = false
    this.spectating = false
    this.spectateTarget = null
    this.spectateIndex = 0
    this.cameraShake = 0
    this.fov = 70
    this.interactTarget = null
    this.teamSize = 1
    this.placement = null
    this.resultShown = false
    this.hudTimer = 0
    this.zoneTick = 0
    this.lastHudState = null
    this.startedAt = 0
    this.stats = { kills: 0, damage: 0 }
    this._seed = 1337
  }

  async prepare() {
    const ui = this.ui
    ui?.setLoading(6, 'BOOTING RENDERER')
    await nextFrame()
    this.applySettings(false)
    this.lobby = new LobbyScene(this.renderer)
    this.lobby.setCharacter(currentOutfit(this.profile), this.profile.name, this.profile.level)
    this.lobby.resize(this.canvas.clientWidth, this.canvas.clientHeight)
    ui?.setLoading(28, 'SCULPTING ISLAND OF ASH')
    await nextFrame()
    await sleep(30)
    this.worldScene = new THREE.Scene()
    this.world = new World(this.worldScene, this.quality, this._seed)
    ui?.setLoading(62, 'RAISING LANDMARKS')
    await nextFrame()
    await sleep(30)
    this.effects = new Effects(this.worldScene, this.quality)
    this.loot = new LootManager(this.worldScene, this.world, this._seed)
    this.zone = new ZoneSystem(this.worldScene, this._seed)
    this.zone.onPhase = (kind, phase) => this.onZonePhase(kind, phase)
    this.vehicles = this.world.vehicleSpawns.map(spawn => new Vehicle(this, spawn))
    ui?.setLoading(84, 'PLACING SUPPLY DROPS')
    await nextFrame()
    await sleep(30)
    this.loot.spawnInitial()
    ui?.setLoading(100, 'ALL SYSTEMS READY')
    await sleep(220)
    this.showLobby()
  }

  applySettings(rebuild = false) {
    const s = this.settings
    this.quality = s.quality || 'high'
    const scale = clamp((s.renderScale || 100) / 100, 0.5, 1.5)
    const dpr = Math.min(window.devicePixelRatio || 1, this.quality === 'low' ? 1 : 2)
    this.renderer.setPixelRatio(clamp(dpr * scale, 0.5, 2))
    this.renderer.shadowMap.enabled = !!s.shadows && this.quality !== 'low'
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap
    if (this.world?.sky?.sun) this.world.sky.sun.castShadow = this.renderer.shadowMap.enabled
    this.audio.setVolumes(s.volume ?? 80, s.sfx ?? 100)
    this.input.applyButtonScale(s.buttonSize ?? s.buttonScale ?? 100)
    if (this.worldScene) this.worldScene.fog = new THREE.Fog(0xb8d2da, this.quality === 'low' ? 380 : 520, this.quality === 'low' ? 1100 : 1560)
    this.camera.far = this.quality === 'low' ? 1800 : 3200
    this.camera.updateProjectionMatrix()
    if (this.lobby) this.lobby.resize(this.canvas.clientWidth, this.canvas.clientHeight)
    this.resize()
  }

  showLobby() {
    this.state = 'lobby'
    this.paused = false
    this.spectating = false
    this.input.setPlaying(false)
    this.input.setBlocked(false)
    this.lobby.setCharacter(currentOutfit(this.profile), this.profile.name, this.profile.level)
    this.ui?.showMenu()
    this.ui?.refreshMenu()
    this.ui?.setOnlineState('SERVER OFFLINE · LOCAL READY')
    this.resize()
  }

  async startMatch(mode = this.mode) {
    if (this.state === 'loading') return
    this.mode = mode
    this.state = 'loading'
    this.ui?.closePanels()
    this.ui?.showLoading(12, 'DEPLOYMENT AUTHORIZED')
    this.input.setPlaying(false)
    this.audio.init()
    await nextFrame()
    this.resetMatch()
    this.ui?.setLoading(72, 'SYNCING OPERATIVES')
    await nextFrame()
    this.ui?.hideLoading()
    this.ui?.showHud()
    this.ui?.refreshMenu()
    this.state = 'match'
    this.paused = false
    this.input.setPlaying(true)
    this.input.setBlocked(false)
    this.ui?.announce('MATCH START', `${this.mode.toUpperCase()} · LAST OPERATIVE STANDING`, 2600)
    this.ui?.showBanner('DEPLOYMENT COMPLETE', 'AURORA PROTOCOL · ISLAND OF ASH')
    this.audio.setAmbient(true)
    this.ui?.toast(`DROP COMPLETE · ${this.aliveCount()} OPERATIVES`, 'good')
  }

  resetMatch() {
    this.audio.init()
    this.effects.clear()
    for (const g of this.grenades) { this.worldScene.remove(g.mesh); g.mesh.geometry.dispose(); g.mesh.material.dispose() }
    this.grenades.length = 0
    if (this.player) this.player.dispose()
    for (const bot of this.bots) bot.dispose()
    this.bots.length = 0
    this.player = null
    this.spectating = false
    this.spectateTarget = null
    this.spectateIndex = 0
    this.matchTime = 0
    this.matchStarted = false
    this.placement = null
    this.resultShown = false
    this.cameraShake = 0
    this.zoneTick = 0
    this.stats = { kills: 0, damage: 0 }
    this.zone.reset()
    this.loot.reset()
    for (const v of this.vehicles) v.reset()
    const rng = mulberry32((Date.now() & 0xffff) + 7)
    const spawn = this._pickSpawn(rng)
    const outfit = currentOutfit(this.profile)
    this.teamSize = this.mode === 'duo' ? 2 : this.mode === 'squad' ? 4 : 1
    this.player = new Player(this, { name: this.profile.name, outfit, spawn, team: 0 })
    const total = this.mode === 'practice' ? 10 : clamp(Number(this.settings.matchSize) || 25, 10, 50)
    const botCount = Math.max(3, total - 1)
    const skill = this.settings.botSkill || 'veteran'
    const spawns = this._botSpawns(botCount + 2, spawn, rng)
    for (let i = 0; i < botCount; i++) {
      const team = this.teamSize > 1 && i < this.teamSize - 1 ? 0 : Math.floor(i / this.teamSize) + 1
      const s = spawns[i % spawns.length]
      const name = ORIGINAL_NAMES[(i + 3) % ORIGINAL_NAMES.length] + '-' + String(10 + i)
      const bot = new Bot(this, { spawn: s, team, name, skill, index: i })
      this.bots.push(bot)
    }
    this.camera.position.set(spawn.x + 8, spawn.y + 7, spawn.z + 8)
    this.camera.lookAt(spawn.x, spawn.y + 1.5, spawn.z)
    this.updateCamera(1 / 60, true)
    this.lastHudState = null
    this.hudTimer = 0
    this.startedAt = performance.now()
  }

  _pickSpawn(rng) {
    const spots = this.world.lootSpots
    for (let attempt = 0; attempt < 80; attempt++) {
      const spot = spots[Math.floor(rng() * spots.length)]
      if (!spot) continue
      if (this.world.isWaterAt(spot.x, spot.z)) continue
      const x = spot.x + (rng() - 0.5) * 6
      const z = spot.z + (rng() - 0.5) * 6
      if (this.world.isWaterAt(x, z)) continue
      if (this.world.insideCollider(x, z, 1.2, spot.y)) continue
      return { x, y: this.world.groundHeight(x, z), z, yaw: rng() * TAU }
    }
    return { x: 0, y: this.world.groundHeight(0, 92), z: 92, yaw: 0 }
  }

  _botSpawns(count, playerSpawn, rng) {
    const out = []
    const spots = this.world.lootSpots
    let guard = 0
    while (out.length < count && guard++ < count * 40) {
      const spot = spots[Math.floor(rng() * spots.length)]
      if (!spot) continue
      const x = spot.x + (rng() - 0.5) * 10
      const z = spot.z + (rng() - 0.5) * 10
      if (this.world.isWaterAt(x, z)) continue
      if (Math.hypot(x - playerSpawn.x, z - playerSpawn.z) < 55) continue
      if (out.some(s => Math.hypot(s.x - x, s.z - z) < 16)) continue
      out.push({ x, y: this.world.groundHeight(x, z), z, yaw: rng() * TAU })
    }
    while (out.length < count) {
      const a = rng() * TAU
      const r = 120 + rng() * 350
      const x = Math.cos(a) * r, z = Math.sin(a) * r
      out.push({ x, y: this.world.groundHeight(x, z), z, yaw: rng() * TAU })
    }
    return out
  }

  teamColor(team) { return TEAM_COLORS[team % TEAM_COLORS.length] }
  teamLabel(team) { return this.player && team === this.player.team ? 'ALLY' : 'HOSTILE' }
  isEnemy(a, b) { return a && b && a.team !== b.team }

  aliveCount() {
    let n = this.player?.alive ? 1 : 0
    for (const b of this.bots) if (b.alive) n++
    return n
  }

  aliveTeams() {
    const teams = new Set()
    if (this.player?.alive) teams.add(this.player.team)
    for (const b of this.bots) if (b.alive) teams.add(b.team)
    return teams.size
  }

  update(dt) {
    dt = Math.min(dt, 0.05)
    if (this.state === 'lobby') {
      this.lobby?.update(dt, performance.now() / 1000)
      return
    }
    if (this.state !== 'match' && this.state !== 'result') return
    if (this.paused) return
    this.matchTime += dt
    this.zone.update(dt)
    this.world.update(dt, this.matchTime)
    if (this.player) {
      this.player.update(dt, this.matchTime)
      if (this.player.alive) this.world.setSunFocus(this.player.pos.x, this.player.pos.z)
      if (this.player.alive && this.zone.isOutside(this.player.pos.x, this.player.pos.z)) {
        this.zoneTick += dt
        if (this.zoneTick >= 1) {
          this.zoneTick = 0
          this.player.takeDamage(this.zone.damagePerSecond, null, false)
          if (this.player.alive) this.ui?.toast('OUTSIDE SAFE ZONE · MOVE!', 'warn')
        }
      } else {
        this.zoneTick = 0
      }
    }
    for (const bot of this.bots) {
      if (bot.alive) bot.update(dt, this.matchTime)
      else bot.update(dt, this.matchTime)
    }
    for (const v of this.vehicles) v.update(dt, this.matchTime)
    this._updateGrenades(dt)
    this.loot.update(dt)
    this.effects.update(dt)
    this.cameraShake = Math.max(0, this.cameraShake - dt * 1.8)
    this._updateInteraction()
    if (!this.spectating) this.updateCamera(dt)
    else this._updateSpectate(dt)
    this.hudTimer -= dt
    if (this.hudTimer <= 0) {
      this.hudTimer = 0.08
      this.ui?.updateHUD(this)
    }
    if (this.state === 'match' && this.player && this.player.alive && this.aliveTeams() <= 1 && this.matchTime > 3) {
      this.finishMatch(true)
    }
  }

  _updateInteraction() {
    if (!this.player || !this.player.alive || this.spectating) {
      if (this.interactTarget) { this.interactTarget = null; this.ui?.setInteract(null) }
      return
    }
    if (this.player.vehicle) {
      this.interactTarget = { type: 'exit' }
      this.ui?.setInteract('EXIT VEHICLE')
      if (this.input.wasPressed('interact')) this.player.vehicle.exit()
      return
    }
    const item = this.loot.nearest(this.player.pos.x, this.player.pos.y + 0.7, this.player.pos.z, 2.7)
    if (item) {
      this.interactTarget = { type: 'loot', item }
      this.ui?.setInteract('PICK UP · ' + this.lootLabel(item))
      if (this.input.wasPressed('interact')) this.interact()
      return
    }
    let bestVehicle = null, bestDist = 3.4
    for (const v of this.vehicles) {
      if (v.destroyed || v.occupied) continue
      const d = distance2D(v.pos.x, v.pos.z, this.player.pos.x, this.player.pos.z)
      if (d < bestDist) { bestDist = d; bestVehicle = v }
    }
    if (bestVehicle) {
      this.interactTarget = { type: 'vehicle', vehicle: bestVehicle }
      this.ui?.setInteract('DRIVE VEHICLE')
      if (this.input.wasPressed('interact')) this.interact()
      return
    }
    this.interactTarget = null
    this.ui?.setInteract(null)
  }

  lootLabel(item) {
    if (!item) return ''
    const d = item.data
    if (d.type === 'weapon') return weaponById(d.weapon).name
    if (d.type === 'ammo') return `${d.ammo.toUpperCase()} AMMO`
    if (d.type === 'armor') return `ARMOR LV${d.level}`
    if (d.type === 'helmet') return `HELMET LV${d.level}`
    if (d.type === 'backpack') return `PACK LV${d.level}`
    if (d.type === 'med') return d.item === 'medkit' ? 'MEDKIT' : 'BANDAGE'
    if (d.type === 'grenade') return 'FRAG GRENADE'
    if (d.type === 'attachment') return d.attachment.replace('_', ' ').toUpperCase()
    return 'SUPPLY'
  }

  interact() {
    if (!this.interactTarget || !this.player || !this.player.alive) return
    const t = this.interactTarget
    if (t.type === 'loot') {
      const result = this.player.pickup(t.item)
      if (result.ok) this.ui?.toast(result.message, 'loot')
      else if (result.message) this.ui?.toast(result.message, 'warn')
      this.interactTarget = null
      this.ui?.setInteract(null)
    } else if (t.type === 'vehicle') {
      t.vehicle.enter(this.player)
      this.interactTarget = null
      this.ui?.setInteract(null)
    } else if (t.type === 'exit') {
      this.player.vehicle?.exit()
      this.interactTarget = null
      this.ui?.setInteract(null)
    }
  }

  findBotTarget(bot) {
    let best = null, bestD = Infinity
    if (this.player?.alive && this.isEnemy(bot, this.player)) {
      const d = distance2D(bot.pos.x, bot.pos.z, this.player.pos.x, this.player.pos.z)
      if (d < bestD) { bestD = d; best = this.player }
    }
    for (const other of this.bots) {
      if (other === bot || !other.alive || !this.isEnemy(bot, other)) continue
      const d = distance2D(bot.pos.x, bot.pos.z, other.pos.x, other.pos.z)
      if (d < bestD) { bestD = d; best = other }
    }
    return best
  }

  playerShoot(player, origin, dir, stats) {
    let aimDir = dir
    if (this.settings.aimAssist && this.input.touchMode) {
      let best = null, bestDot = 0.992, bestDist = 120
      for (const bot of this.bots) {
        if (!bot.alive) continue
        const to = new THREE.Vector3(bot.pos.x, bot.pos.y + 1.15, bot.pos.z).sub(origin)
        const d = to.length()
        if (d > bestDist) continue
        const dot = to.normalize().dot(dir)
        if (dot > bestDot) { bestDot = dot; best = to }
      }
      if (best) aimDir = dir.clone().lerp(best, 0.42).normalize()
    }
    const result = this.resolveShot(origin, aimDir, stats.range, stats.damage, player)
    if (result.hit) {
      player.shotsHit++
      player.damageDealt += result.damage
      this.ui?.hitmarker(!!result.killed)
      this.ui?.damageIndicator(result.point)
    }
  }

  resolveShot(origin, dir, maxRange, damage, shooter, options = {}) {
    const wall = this.world.raycast(origin, dir, maxRange)
    let wallDist = wall ? wall.distance : maxRange
    let best = null
    let bestDist = wallDist
    let bestHead = false
    const candidates = []
    if (shooter !== this.player && this.player?.alive && this.isEnemy(shooter, this.player)) candidates.push(this.player)
    for (const bot of this.bots) {
      if (!bot.alive || bot === shooter) continue
      if (shooter === this.player || this.isEnemy(shooter, bot)) candidates.push(bot)
    }
    for (const target of candidates) {
      const chest = new THREE.Vector3(target.pos.x, target.pos.y + 1.12, target.pos.z)
      const head = new THREE.Vector3(target.pos.x, target.pos.y + 1.62, target.pos.z)
      const tc = raySphere(origin, dir, chest, 0.48)
      if (tc !== null && tc < bestDist) { bestDist = tc; best = target; bestHead = false }
      const th = raySphere(origin, dir, head, 0.25)
      if (th !== null && th < bestDist) { bestDist = th; best = target; bestHead = true }
    }
    const point = origin.clone().addScaledVector(dir, Math.min(bestDist, maxRange))
    const tracerColor = shooter === this.player ? 0xffe2a8 : 0xff9a6a
    this.effects.tracer(origin, point, tracerColor)
    let killed = false
    if (best) {
      const finalDamage = damage * (bestHead ? 1.85 : 1)
      if (best === this.player) {
        this.player.takeDamage(finalDamage, shooter, bestHead)
        this.ui?.damageDirection?.(best.pos || shooter?.pos)
      } else {
        const wasAlive = best.alive
        best.takeDamage(finalDamage, shooter, bestHead)
        killed = wasAlive && !best.alive
      }
      if (best === this.player) this.ui?.hitmarker(false)
      return { hit: true, headshot: bestHead, target: best, damage: finalDamage, killed, point }
    }
    if (wall) {
      this.effects.impact(wall.point, wall.normal, shooter === this.player ? 0xffd9a0 : 0xd0c0a0, 2)
    }
    return { hit: false, damage: 0, killed: false, point }
  }

  meleeAttack(attacker, damage, range) {
    const forward = new THREE.Vector3(Math.sin(attacker.yaw), 0, Math.cos(attacker.yaw))
    const targets = []
    if (attacker !== this.player && this.player?.alive && this.isEnemy(attacker, this.player)) targets.push(this.player)
    for (const bot of this.bots) {
      if (bot.alive && bot !== attacker && (attacker === this.player || this.isEnemy(attacker, bot))) targets.push(bot)
    }
    let hitAny = false
    for (const target of targets) {
      const dx = target.pos.x - attacker.pos.x
      const dz = target.pos.z - attacker.pos.z
      const d = Math.hypot(dx, dz)
      if (d > range + 0.6) continue
      if ((dx * forward.x + dz * forward.z) / (d || 1) < 0.35) continue
      if (target === this.player) this.player.takeDamage(damage, attacker, false)
      else target.takeDamage(damage, attacker, false)
      this.effects.blood(new THREE.Vector3(target.pos.x, target.pos.y + 1.2, target.pos.z))
      this.audio.hit(false)
      if (attacker === this.player) { this.ui?.hitmarker(false); this.player.damageDealt += damage }
      hitAny = true
      break
    }
    if (!hitAny) this.effects.impact(attacker.pos.clone().add(forward.multiplyScalar(range * 0.7)).setY(attacker.pos.y + 1), null, 0xd0c0a0, 1)
  }

  throwGrenade(player) {
    const origin = player.getEyePosition(new THREE.Vector3())
    const dir = player.getAimDirection(new THREE.Vector3())
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.16, 8, 6), new THREE.MeshStandardMaterial({ color: 0x3f4a34, roughness: 0.7 }))
    mesh.position.copy(origin).addScaledVector(dir, 0.6)
    mesh.castShadow = true
    this.worldScene.add(mesh)
    this.grenades.push({
      mesh, pos: mesh.position,
      vel: dir.clone().multiplyScalar(19).add(new THREE.Vector3(0, 4.2, 0)),
      timer: 2.7, source: player, trail: 0,
    })
  }

  _updateGrenades(dt) {
    for (let i = this.grenades.length - 1; i >= 0; i--) {
      const g = this.grenades[i]
      g.timer -= dt
      g.vel.y -= 18 * dt
      g.pos.addScaledVector(g.vel, dt)
      const ground = this.world.groundHeight(g.pos.x, g.pos.z)
      if (g.pos.y < ground + 0.16) {
        g.pos.y = ground + 0.16
        g.vel.y *= -0.42
        g.vel.x *= 0.62
        g.vel.z *= 0.62
        if (Math.abs(g.vel.y) < 1) g.vel.y = 0
      }
      g.mesh.rotation.x += dt * 6
      g.mesh.rotation.z += dt * 4
      if (g.timer <= 0) {
        this.explode(g.pos.clone(), 6.5, 92, g.source)
        this.worldScene.remove(g.mesh)
        g.mesh.geometry.dispose()
        g.mesh.material.dispose()
        this.grenades.splice(i, 1)
      }
    }
  }

  explode(pos, radius, damage, source) {
    this.effects.explosion(pos, radius / 6)
    const distToPlayer = this.player ? distance2D(this.player.pos.x, this.player.pos.z, pos.x, pos.z) : 999
    this.audio.explosion()
    if (distToPlayer < 30) this.cameraShake = Math.max(this.cameraShake, 0.8 * (1 - distToPlayer / 30))
    const apply = (target) => {
      if (!target.alive) return
      const d = Math.hypot(target.pos.x - pos.x, target.pos.y + 1 - pos.y, target.pos.z - pos.z)
      if (d > radius) return
      const falloff = 1 - clamp(d / radius, 0, 1) * 0.7
      if (target === this.player) this.player.takeDamage(damage * falloff, source, false)
      else target.takeDamage(damage * falloff, source, false)
    }
    apply(this.player)
    for (const bot of this.bots) apply(bot)
  }

  onZonePhase(kind, phase) {
    if (this.state !== 'match') return
    if (kind === 'shrink') {
      this.ui?.announce('ZONE CLOSING', 'THE AURORA WALL IS MOVING', 2400)
      this.audio.zoneWarning()
    } else if (kind === 'wait' && phase > 0) {
      this.ui?.announce(`ZONE ${phase + 1}`, 'ROTATE TO THE MARKED CIRCLE', 2000)
      if (this.settings.zoneAudio) this.audio.zoneWarning()
    } else if (kind === 'final') {
      this.ui?.announce('FINAL ZONE', 'NO PLACE LEFT TO HIDE', 2600)
    }
  }

  onPlayerHurt(amount, source, headshot) {
    this.ui?.flashDamage(amount, source)
    this.cameraShake = Math.min(0.6, this.cameraShake + amount * 0.006)
  }

  onPlayerDeath(source) {
    if (this.state !== 'match') return
    this.placement = this.mode === 'solo' || this.mode === 'practice' ? this.aliveCount() : this.aliveTeams()
    const killerName = source?.name || 'THE ZONE'
    this.ui?.killfeed(killerName, this.player.name, source ? (source.weapon?.name || 'WEAPON') : 'ZONE', !source)
    this.ui?.announce('ELIMINATED', `PLACEMENT #${this.placement}`, 3000)
    this.audio.defeat()
    this.input.setPlaying(false)
    this.ui?.showResult(this.buildResult(false))
    this.spectateTarget = null
    this.spectateIndex = 0
  }

  onBotDeath(bot, source) {
    const killerName = source?.name || 'THE ZONE'
    const weaponName = source?.weapon?.name || (source === this.player ? this.player.weapon?.name : null) || 'ZONE'
    this.ui?.killfeed(killerName, bot.name, source ? weaponName : 'ZONE', !source)
    if (source === this.player) {
      this.player.kills++
      this.audio.kill()
      this.ui?.announce('ELIMINATED', `${bot.name} · ${this.player.kills} TOTAL`, 1500)
      this.ui?.hitmarker(true)
    } else if (source && source !== this.player) {
      source.kills = (source.kills || 0) + 1
    }
    const pos = bot.pos.clone()
    this.loot.dropAt(pos.x, pos.y, pos.z, { type: 'weapon', weapon: bot.weapon.id, rarity: bot.weapon.rarity, attachments: [] }, 0.8)
    this.loot.dropAt(pos.x, pos.y, pos.z, { type: 'ammo', ammo: bot.weapon.ammo === 'none' ? 'light' : bot.weapon.ammo, amount: randInt(Math.random, 20, 40) }, 1.4)
    if (bot.medkits > 0) this.loot.dropAt(pos.x, pos.y, pos.z, { type: 'med', item: 'medkit' }, 1.1)
    if (bot.armor > 0) this.loot.dropAt(pos.x, pos.y, pos.z, { type: 'armor', level: Math.max(1, bot.armorLevel) }, 0.9)
    if (this.spectateTarget === bot) this._nextSpectate()
    if (this.state === 'match' && this.player.alive && this.aliveTeams() <= 1) this.finishMatch(true)
  }

  finishMatch(victory) {
    if (this.state !== 'match') return
    this.state = 'result'
    this.input.setPlaying(false)
    this.placement = victory ? 1 : this.placement
    const result = this.buildResult(victory)
    this.ui?.showResult(result)
    if (victory) {
      this.audio.victory()
      this.ui?.announce('ELITE VICTORY', 'LAST OPERATIVE STANDING', 4000)
    }
    this.input.setBlocked(false)
  }

  buildResult(victory) {
    const time = Math.max(1, Math.round(this.matchTime))
    const kills = this.player?.kills || 0
    const damage = Math.round(this.player?.damageDealt || 0)
    const placement = victory ? 1 : (this.placement || this.aliveCount())
    let xp = 0, levels = 0, unlocked = []
    if (!this.resultShown) {
      this.resultShown = true
      const saved = recordMatch(this.profile, { placement, kills, damage, victory, time })
      xp = saved.xp
      levels = saved.levels
      unlocked = saved.unlocked || []
      if (levels > 0) this.audio.levelUp()
    }
    return {
      victory, placement, kills, damage, time, xp, levels, unlocked,
      alive: this.aliveCount(), mode: this.mode, matchTime: formatTime(this.matchTime),
    }
  }

  startSpectate() {
    this.spectating = true
    this.spectateIndex = 0
    this._nextSpectate()
    this.ui?.hideResult()
    this.ui?.setSpectate(this.spectateTarget?.name || null)
    this.ui?.toast('SPECTATOR MODE · TAP NEXT TO CYCLE', 'good')
  }

  _nextSpectate() {
    const alive = this.bots.filter(b => b.alive)
    if (!alive.length) {
      this.spectating = false
      this.ui?.setSpectate(null)
      this.ui?.showResult(this.buildResult(this.player?.alive === true && this.aliveTeams() <= 1))
      return
    }
    this.spectateIndex = (this.spectateIndex + 1) % alive.length
    this.spectateTarget = alive[this.spectateIndex]
    this.ui?.setSpectate(this.spectateTarget.name)
    this.camera.position.set(this.spectateTarget.pos.x + 6, this.spectateTarget.pos.y + 5, this.spectateTarget.pos.z + 6)
  }

  _updateSpectate(dt) {
    if (!this.spectateTarget || !this.spectateTarget.alive) {
      this._nextSpectate()
      if (!this.spectateTarget) return
    }
    const t = this.spectateTarget
    const dist = 6
    const desired = new THREE.Vector3(t.pos.x - Math.sin(t.yaw) * dist, t.pos.y + 3.2, t.pos.z - Math.cos(t.yaw) * dist)
    this.camera.position.lerp(desired, 1 - Math.exp(-5 * dt))
    const look = new THREE.Vector3(t.pos.x + Math.sin(t.yaw) * 5, t.pos.y + 1.2, t.pos.z + Math.cos(t.yaw) * 5)
    this.camera.lookAt(look)
  }

  exitSpectate() {
    this.spectating = false
    this.spectateTarget = null
    this.ui?.setSpectate(null)
    this.ui?.showResult(this.buildResult(false))
  }

  updateCamera(dt, instant = false) {
    if (!this.player) return
    const cam = this.camera
    let desired, lookAt, fovTarget = 70
    if (this.player.vehicle && !this.player.vehicle.destroyed) {
      const v = this.player.vehicle
      const fwd = v.forward
      desired = new THREE.Vector3(v.pos.x, v.pos.y + 3.4, v.pos.z).addScaledVector(fwd, -7.5)
      lookAt = new THREE.Vector3(v.pos.x, v.pos.y + 1.2, v.pos.z).addScaledVector(fwd, 8)
      fovTarget = 76
    } else {
      const eye = this.player.getEyePosition(new THREE.Vector3())
      const dir = this.player.getAimDirection(new THREE.Vector3())
      const aiming = this.player.aiming && this.player.alive
      const right = new THREE.Vector3(-Math.cos(this.player.yaw), 0, Math.sin(this.player.yaw))
      const dist = aiming ? 2.2 : 4.4
      desired = eye.clone().addScaledVector(dir, -dist).addScaledVector(right, aiming ? 0.52 : 0.7)
      desired.y += 0.18
      const delta = desired.clone().sub(eye)
      const len = delta.length()
      if (len > 0.01) {
        const nd = delta.clone().divideScalar(len)
        const hit = this.world.raycast(eye, nd, len)
        if (hit) desired = eye.clone().addScaledVector(nd, Math.max(0.4, hit.distance - 0.3))
      }
      lookAt = eye.clone().addScaledVector(dir, 40)
      const zoom = this.player.stats?.zoom || 1
      fovTarget = aiming ? clamp(70 / Math.max(1, zoom), 18, 66) : 70
    }
    if (instant) cam.position.copy(desired)
    else cam.position.lerp(desired, 1 - Math.exp(-14 * dt))
    if (this.cameraShake > 0.002) {
      const s = this.cameraShake * 0.16
      cam.position.x += (Math.random() - 0.5) * s
      cam.position.y += (Math.random() - 0.5) * s
      lookAt.x += (Math.random() - 0.5) * s * 0.6
      lookAt.y += (Math.random() - 0.5) * s * 0.6
    }
    cam.lookAt(lookAt)
    this.fov = damp(this.fov, fovTarget, 10, dt)
    if (Math.abs(cam.fov - this.fov) > 0.05) {
      cam.fov = this.fov
      cam.updateProjectionMatrix()
    }
  }

  resize() {
    const w = this.canvas.clientWidth || window.innerWidth
    const h = this.canvas.clientHeight || window.innerHeight
    this.renderer.setSize(w, h, false)
    this.camera.aspect = w / Math.max(1, h)
    this.camera.updateProjectionMatrix()
    this.lobby?.resize(w, h)
  }

  render() {
    if (this.state === 'lobby' || this.state === 'boot') {
      if (this.lobby) this.lobby.render()
      else {
        this.renderer.setClearColor(0x050a10, 1)
        this.renderer.clear()
      }
      return
    }
    this.renderer.render(this.worldScene, this.camera)
  }

  returnToLobby() {
    if (this.player) { this.player.dispose(); this.player = null }
    for (const bot of this.bots) bot.dispose()
    this.bots.length = 0
    this.effects.clear()
    this.spectating = false
    this.audio.setAmbient(false)
    this.showLobby()
    this.ui?.refreshMenu()
  }

  setPaused(paused) {
    this.paused = paused
    this.input.setPlaying(!paused && this.state === 'match')
    if (paused) this.input.setBlocked(true)
    else if (this.state === 'match') this.input.setBlocked(false)
  }

  setOnlineState(label) { this.ui?.setOnlineState(label) }

  getPlayerState() { return this.player?.getHudState() || null }
}

