update(dt) {
  dt = Math.min(dt, 0.05)
  if (this.state === 'lobby') {
    this.lobby?.update(dt, performance.now() / 1000)
    return
  }
  if (this.state !== 'match' && this.state !== 'result') return
  if (this.paused) return
  this.matchTime += dt
  this.zone.update(dt)
  this.world.update(dt, this.matchTime)
  if (this.player) {
    this.player.update(dt, this.matchTime)
    if (this.player.alive) this.world.setSunFocus(this.player.pos.x, this.player.pos.z)
    if (this.player.alive && this.zone.isOutside(this.player.pos.x, this.player.pos.z)) {
      this.zoneTick += dt
      if (this.zoneTick >= 1) {
        this.zoneTick = 0
        this.player.takeDamage(this.zone.damagePerSecond, null, false)
        if (this.player.alive) this.ui?.toast('OUTSIDE SAFE ZONE · MOVE!', 'warn')
      }
    } else {
      this.zoneTick = 0
    }
  }
  for (const bot of this.bots) {
    if (bot.alive) bot.update(dt, this.matchTime)
    else bot.update(dt, this.matchTime)
  }
  for (const v of this.vehicles) v.update(dt, this.matchTime)
  this._updateGrenades(dt)
  this.loot.update(dt)
  this.effects.update(dt)
  this.cameraShake = Math.max(0, this.cameraShake - dt * 1.8)
  this._updateInteraction()
  if (!this.spectating) this.updateCamera(dt)
  else this._updateSpectate(dt)
  this.hudTimer -= dt
  if (this.hudTimer <= 0) {
    this.hudTimer = 0.08
    this.ui?.updateHUD(this)
  }
  if (this.state === 'match' && this.player && this.player.alive && this.aliveTeams() <= 1 && this.matchTime > 3) {
    this.finishMatch(true)
  }
}

_updateInteraction() {
  if (!this.player || !this.player.alive || this.spectating) {
    if (this.interactTarget) { this.interactTarget = null; this.ui?.setInteract(null) }
    return

  const hspeed = Math.hypot(this.velocityX, this.velocityZ)
  if (hspeed > 0.6 && this.onGround) {
    this.stepTimer -= dt
    if (this.stepTimer <= 0) {
      this.game.audio.footstep(this.swimming ? 'water' : 'grass')
      this.stepTimer = this.sprinting ? 0.3 : 0.45
    }
  }
}

takeDamage(amount, source = null, headshot = false) {
  if (!this.alive || this.game.state !== 'match') return
  let dmg = amount
  if (headshot && this.helmet > 0) dmg *= 0.68
  if (this.armor > 0) {
    const absorbed = Math.min(this.armor, dmg * 0.62)
    this.armor -= absorbed
    dmg -= absorbed
    if (this.armor <= 0.01) { this.armor = 0; this.armorLevel = 0; this.character.setArmor(0, this.helmet) }
  }
  this.health -= dmg
  this.lastDamageTime = this.game.matchTime
  this.hurtFlash = 1
  this.game.audio.damage()
  this.game.onPlayerHurt(dmg, source, headshot)
  if (this.health <= 0) {
    this.health = 0
    this.die(source)
  }
}

die(source = null) {
  if (!this.alive) return
  this.alive = false
  this.health = 0
  this.healing = null
  this.reloading = false
  this.character.die()
  this.game.onPlayerDeath(source)
}

heal(amount) {
  this.health = Math.min(this.maxHealth, this.health + amount)
}

