const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright')

const log = (...a) => console.log(...a)
const results = []
function check(name, ok, detail = '') {
  results.push({ name, ok: !!ok, detail })
  log(`${ok ? 'PASS' : 'FAIL'} · ${name}${detail ? ' · ' + detail : ''}`)
}

async function waitState(page, state, timeout = 15000) {
  const start = Date.now()
  while (Date.now() - start < timeout) {
    const s = await page.evaluate(() => window.__BATTLE_WORLD__?.game?.state)
    if (s === state) return true
    await page.waitForTimeout(150)
  }
  return false
}

;(async () => {
  const browser = await chromium.launch({ headless: true })
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } })
  const page = await ctx.newPage()
  const errors = []
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()) })
  page.on('pageerror', e => errors.push('pageerror: ' + e.message))
  await page.goto('http://localhost:3000/', { waitUntil: 'networkidle', timeout: 60000 })
  await page.waitForTimeout(4500)
  await page.locator('#btn-play').click()
  check('match starts', await waitState(page, 'match'), await page.evaluate(() => window.__BATTLE_WORLD__.game.state))

  // ── movement ─────────────────────────────────────────────────
  const before = await page.evaluate(() => {
    const p = window.__BATTLE_WORLD__.game.player
    return { x: p.pos.x, y: p.pos.y, z: p.pos.z }
  })
  await page.keyboard.down('KeyW')
  await page.waitForTimeout(1400)
  await page.keyboard.up('KeyW')
  await page.waitForTimeout(350)
  const after = await page.evaluate(() => {
    const p = window.__BATTLE_WORLD__.game.player
    return { x: p.pos.x, y: p.pos.y, z: p.pos.z }
  })
  const moved = Math.hypot(after.x - before.x, after.z - before.z)
  check('WASD moves player', moved > 1.2, `moved ${moved.toFixed(2)}m`)

  // ── jump ─────────────────────────────────────────────────────
  await page.keyboard.press('Space')
  await page.waitForTimeout(260)
  const jump = await page.evaluate(() => {
    const p = window.__BATTLE_WORLD__.game.player
    return { y: p.pos.y, vy: p.vy, ground: p.onGround }
  })
  check('jump leaves ground', jump.y > after.y + 0.05 || jump.vy > 0.1 || !jump.ground, JSON.stringify(jump))

  // ── firing ───────────────────────────────────────────────────
  const fireBefore = await page.evaluate(() => {
    const g = window.__BATTLE_WORLD__.game, p = g.player
    return { mag: p.weaponEntry.mag, shots: p.shotsFired, name: p.weapon.name, auto: p.weapon.auto }
  })
  await page.evaluate(() => window.__BATTLE_WORLD__.game.input.press('fire'))
  await page.waitForTimeout(700)
  await page.evaluate(() => window.__BATTLE_WORLD__.game.input.release('fire'))
  await page.waitForTimeout(300)
  const fireAfter = await page.evaluate(() => {
    const p = window.__BATTLE_WORLD__.game.player
    return { mag: p.weaponEntry.mag, shots: p.shotsFired }
  })
  check('fire consumes ammo', fireAfter.mag < fireBefore.mag && fireAfter.shots > fireBefore.shots, `${fireBefore.name} ${fireBefore.mag}->${fireAfter.mag}`)

  // ── reload ───────────────────────────────────────────────────
  const reloaded = await page.evaluate(async () => {
    const g = window.__BATTLE_WORLD__.game, p = g.player
    const def = p.weapon
    const reserve = p.ammo[def.ammo]
    p.startReload()
    await new Promise(r => setTimeout(r, (def.reload + 0.8) * 1000))
    return { mag: p.weaponEntry.mag, expected: Math.min(def.mag, reserve + p.weaponEntry.mag), reloading: p.reloading }
  })
  check('reload refills magazine', reloaded.mag > 0 && !reloaded.reloading, JSON.stringify(reloaded))

  // ── loot pickup through interaction prompt ───────────────────
  const pickup = await page.evaluate(async () => {
    const g = window.__BATTLE_WORLD__.game, p = g.player
    const item = g.loot.items.find(i => i.active)
    if (!item) return { ok: false, reason: 'no loot' }
    const before = p.weapons.map(w => w?.def?.id || null)
    p.pos.set(item.x, g.world.groundHeight(item.x, item.z) + 0.1, item.z)
    p.vy = 0
    await new Promise(r => setTimeout(r, 900))
    const prompt = !document.getElementById('interact-prompt').classList.contains('hidden')
    const target = g.interactTarget?.type || null
    g.interact()
    await new Promise(r => setTimeout(r, 300))
    return { ok: !item.active, prompt, target, before, after: p.weapons.map(w => w?.def?.id || null), label: document.getElementById('interact-label').textContent }
  })
  check('loot prompt appears', pickup.prompt && pickup.target === 'loot', JSON.stringify(pickup))
  check('loot pickup removes world item', pickup.ok, pickup.label)

  // ── zone ─────────────────────────────────────────────────────
  const zone = await page.evaluate(async () => {
    const g = window.__BATTLE_WORLD__.game
    const phase0 = g.zone.phase
    g.zone.timer = 0.05
    await new Promise(r => setTimeout(r, 500))
    const shrinking = g.zone.state
    const hud = document.getElementById('zone-state').textContent
    return { phase0, shrinking, hud, radius: g.zone.radius }
  })
  check('zone shrink phase starts', zone.shrinking === 'shrink', JSON.stringify(zone))

  // ── bot damage / kill ────────────────────────────────────────
  const combat = await page.evaluate(async () => {
    const g = window.__BATTLE_WORLD__.game, p = g.player
    const bot = g.bots.find(b => b.alive)
    if (!bot) return { ok: false, reason: 'no bot' }
    p.pos.set(bot.pos.x + 8, g.world.groundHeight(bot.pos.x + 8, bot.pos.z), bot.pos.z)
    p.vy = 0
    const origin = p.getEyePosition(new p.pos.constructor())
    const chest = new p.pos.constructor(bot.pos.x, bot.pos.y + 1.12, bot.pos.z)
    const dir = chest.clone().sub(origin).normalize()
    const hp0 = bot.health
    const hit1 = g.resolveShot(origin, dir, 200, 28, p)
    const hp1 = bot.health
    for (let i = 0; i < 12 && bot.alive; i++) g.resolveShot(origin, dir, 200, 28, p)
    await new Promise(r => setTimeout(r, 400))
    return {
      ok: hit1.hit, hp0, hp1, botAlive: bot.alive, kills: p.kills,
      killfeed: document.getElementById('killfeed').textContent,
    }
  })
  check('shots damage bots', combat.ok && combat.hp1 < combat.hp0, JSON.stringify(combat))
  check('bot kill updates kills + feed', combat.kills > 0 && /ELIMINATED|VK|SIDEKICK|AEGIS|HORNET|BREACHER|LONGSHOT|RAPTOR|JUDGE|VULCAN|MACHETE/i.test(combat.killfeed || ''), `kills ${combat.kills}`)

  // ── inventory / map / pause panels ───────────────────────────
  for (const [panel, sel] of [['inventory', '.panel-inventory'], ['map', '.panel-map'], ['pause', '.panel-pause'], ['loadout', '.panel-loadout'], ['profile', '.panel-profile'], ['character', '.panel-character'], ['settings', '.panel-settings'], ['help', '.panel-help']]) {
    const open = await page.evaluate(p => { window.__BATTLE_WORLD__.ui.openPanel(p, true); return document.querySelector(`[data-panel-id="${p}"]`)?.classList.contains('open') }, panel)
    check(`panel opens: ${panel}`, open)
  }
  await page.evaluate(() => window.__BATTLE_WORLD__.ui.closePanels(true))

  // ── grenade / heal ───────────────────────────────────────────
  const utility = await page.evaluate(async () => {
    const g = window.__BATTLE_WORLD__.game, p = g.player
    p.health = 40
    p.items.medkit = 1
    p.startHeal('medkit')
    const healing = p.healing
    await new Promise(r => setTimeout(r, 3700))
    const health = p.health
    const nades = g.grenades.length
    p.items.grenade = 1
    p.grenadeCooldown = 0
    p.throwGrenade()
    const thrown = g.grenades.length > nades
    return { healing, health, thrown }
  })
  check('medkit heals over time', utility.healing === 'medkit' && utility.health > 40, JSON.stringify(utility))
  check('grenade throw spawns projectile', utility.thrown, JSON.stringify(utility))

  // ── death + result + spectate ───────────────────────────────
  const death = await page.evaluate(async () => {
    const g = window.__BATTLE_WORLD__.game, p = g.player
    p.health = 1
    p.armor = 0
    p.takeDamage(999, null, false)
    await new Promise(r => setTimeout(r, 500))
    const panel = document.querySelector('[data-panel-id="result"]')
    return {
      alive: p.alive,
      open: panel.classList.contains('open'),
      title: document.getElementById('result-title').textContent,
      place: document.getElementById('res-place').textContent,
      spectateVisible: getComputedStyle(document.getElementById('btn-result-spectate')).display !== 'none',
      state: g.state,
    }
  })
  check('death opens result panel', !death.alive && death.open && death.title === 'ELIMINATED', JSON.stringify(death))
  if (death.spectateVisible) {
    await page.locator('#btn-result-spectate').click()
    await page.waitForTimeout(500)
    const spec = await page.evaluate(() => ({
      spectating: window.__BATTLE_WORLD__.game.spectating,
      banner: !document.getElementById('spectate-banner').classList.contains('hidden'),
      name: document.getElementById('spectate-name').textContent,
    }))
    check('spectator mode starts', spec.spectating && spec.banner && spec.name.length > 0, JSON.stringify(spec))
    await page.locator('#btn-spectate-next').click()
    await page.waitForTimeout(300)
    const next = await page.evaluate(() => window.__BATTLE_WORLD__.game.spectateTarget?.name)
    check('spectate next cycles target', !!next, String(next))
    await page.locator('#btn-spectate-exit').click()
    await page.waitForTimeout(300)
    const exit = await page.evaluate(() => !window.__BATTLE_WORLD__.game.spectating && document.querySelector('[data-panel-id="result"]').classList.contains('open'))
    check('spectate exit returns result', exit)
  } else {
    check('spectator button available', false, 'button hidden')
  }

  // ── return to lobby + replay ────────────────────────────────
  await page.evaluate(() => { window.__BATTLE_WORLD__.ui.closePanels(true); window.__BATTLE_WORLD__.game.returnToLobby() })
  await page.waitForTimeout(800)
  check('return to lobby', await page.evaluate(() => window.__BATTLE_WORLD__.game.state === 'lobby' && !document.getElementById('menu-screen').classList.contains('hidden')))
  await page.locator('#btn-play').click()
  check('replay starts', await waitState(page, 'match'))
  const replay = await page.evaluate(() => ({
    alive: window.__BATTLE_WORLD__.game.aliveCount(),
    health: window.__BATTLE_WORLD__.game.player.health,
    loot: window.__BATTLE_WORLD__.game.loot.items.filter(i => i.active).length,
  }))
  check('replay resets state', replay.alive >= 10 && replay.health === 100 && replay.loot > 50, JSON.stringify(replay))

  check('no runtime errors', errors.length === 0, errors.slice(0, 6).join(' | '))
  await page.screenshot({ path: '/tmp/opencode/gameplay-desktop.png' })

  // ── mobile touch controls ───────────────────────────────────
  const mobile = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 })
  const mp = await mobile.newPage()
  const mErrors = []
  mp.on('console', m => { if (m.type() === 'error') mErrors.push('console: ' + m.text()) })
  mp.on('pageerror', e => mErrors.push('pageerror: ' + e.message))
  await mp.goto('http://localhost:3000/', { waitUntil: 'networkidle', timeout: 60000 })
  await mp.waitForTimeout(4500)
  check('touch-mode class applied', await mp.evaluate(() => document.body.classList.contains('touch-mode')))
  await mp.locator('#btn-play').click()
  check('mobile match starts', await waitState(mp, 'match'))

  const mpos0 = await mp.evaluate(() => ({ x: window.__BATTLE_WORLD__.game.player.pos.x, z: window.__BATTLE_WORLD__.game.player.pos.z }))
  const stick = await mp.locator('#joystick').boundingBox()
  await mp.mouse.move(stick.x + stick.width / 2, stick.y + stick.height / 2)
  await mp.mouse.down()
  await mp.mouse.move(stick.x + stick.width / 2, stick.y + stick.height * 0.12, { steps: 4 })
  await mp.waitForTimeout(1400)
  await mp.mouse.up()
  await mp.waitForTimeout(300)
  const mpos1 = await mp.evaluate(() => ({ x: window.__BATTLE_WORLD__.game.player.pos.x, z: window.__BATTLE_WORLD__.game.player.pos.z }))
  check('touch joystick moves player', Math.hypot(mpos1.x - mpos0.x, mpos1.z - mpos0.z) > 0.8, `moved ${Math.hypot(mpos1.x - mpos0.x, mpos1.z - mpos0.z).toFixed(2)}m`)

  const mFireBefore = await mp.evaluate(() => window.__BATTLE_WORLD__.game.player.weaponEntry.mag)
  const fireBtn = await mp.locator('.tbtn-fire').boundingBox()
  await mp.mouse.move(fireBtn.x + fireBtn.width / 2, fireBtn.y + fireBtn.height / 2)
  await mp.mouse.down()
  await mp.waitForTimeout(500)
  await mp.mouse.up()
  await mp.waitForTimeout(300)
  const mFireAfter = await mp.evaluate(() => ({ mag: window.__BATTLE_WORLD__.game.player.weaponEntry.mag, shots: window.__BATTLE_WORLD__.game.player.shotsFired }))
  check('touch fire button shoots', mFireAfter.mag < mFireBefore, `${mFireBefore}->${mFireAfter.mag}`)

  const overlap = await mp.evaluate(() => {
    const rect = id => { const el = document.getElementById(id); if (!el) return null; const r = el.getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height, r: r.right, b: r.bottom } }
    const overlap2 = (a, b) => a && b && a.x < b.r && a.r > b.x && a.y < b.b && a.b > b.y
    const stick = rect('joystick')
    const fire = rect('hud') && document.querySelector('.tbtn-fire').getBoundingClientRect()
    const vitals = document.querySelector('.vitals').getBoundingClientRect()
    const mini = document.querySelector('.minimap-wrap').getBoundingClientRect()
    const fireR = { x: fire.x, y: fire.y, r: fire.right, b: fire.bottom }
    const v = { x: vitals.x, y: vitals.y, r: vitals.right, b: vitals.bottom }
    const m = { x: mini.x, y: mini.y, r: mini.right, b: mini.bottom }
    return { stickFire: overlap2(stick, fireR), vitalsStick: overlap2(v, stick), minimapFire: overlap2(m, fireR) }
  })
  check('touch HUD has no major overlaps', !overlap.stickFire && !overlap.vitalsStick && !overlap.minimapFire, JSON.stringify(overlap))

  await mp.screenshot({ path: '/tmp/opencode/gameplay-mobile.png' })
  check('no mobile runtime errors', mErrors.length === 0, mErrors.slice(0, 6).join(' | '))

  await mobile.close()
  await ctx.close()
  await browser.close()

  const failed = results.filter(r => !r.ok)
  log(`\nSUMMARY ${results.length - failed.length}/${results.length} passed`)
  if (failed.length) {
    log('FAILED:', failed.map(f => f.name).join(', '))
    process.exitCode = 1
  }
})().catch(e => { console.error(e); process.exit(1) })

