    part(g, box, MAT.dark, 0, 0.1, 0.12, 0.05, 0.04, 0.06)
    part(g, box, accent, 0, 0.13, 0.12, 0.03, 0.02, 0.05)
    g.userData.muzzle = new THREE.Vector3(0, 0, 0.2)
