const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright')
;(async () => {
  const browser = await chromium.launch({ headless: true })
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } })
  const page = await ctx.newPage()
  const errors = []
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()) })
  page.on('pageerror', e => errors.push(e.message))
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle', timeout: 60000 })
  await page.waitForTimeout(4500)
  const menu = await page.evaluate(() => ({
    playVisible: !!document.getElementById('btn-play') && !document.getElementById('menu-screen').classList.contains('hidden'),
    state: window.__BATTLE_WORLD__?.game?.state,
  }))
  await page.locator('#btn-play').click()
  const start = Date.now()
  let state = null
  while (Date.now() - start < 15000) {
    state = await page.evaluate(() => window.__BATTLE_WORLD__?.game?.state)
    if (state === 'match') break
    await page.waitForTimeout(150)
  }
  await page.waitForTimeout(800)
  const match = await page.evaluate(() => ({
    state: window.__BATTLE_WORLD__?.game?.state,
    alive: window.__BATTLE_WORLD__?.game?.aliveCount(),
    health: window.__BATTLE_WORLD__?.game?.player?.health,
  }))
  console.log(JSON.stringify({ menu, state, match, errors }, null, 2))
  await page.screenshot({ path: '/tmp/opencode/dist-smoke.png' })
  await browser.close()
})().catch(e => { console.error(e); process.exit(1) })

